window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":91,"source":"خطبه 91.docx","mode":"explicit-parts","parts":["خطبه ۹۱\nبخش اول\nمتن:\nو من خطبة له (علیه السلام) تعرف بخطبة الأشباح و هي من جلائل خطبه(علیه السلام)‏\nوصفُ اللّه تعالى‏:\nالْحَمْدُ لِلَّهِ الَّذِي لَا يَفِرُهُ الْمَنْعُ وَ الْجُمُودُ وَ لَا يُكْدِيهِ الْإِعْطَاءُ وَ الْجُودُ، إِذْ كُلُّ مُعْطٍ مُنْتَقِصٌ سِوَاهُ وَ كُلُّ مَانِعٍ مَذْمُومٌ مَا خَلَاهُ، وَ هُوَ الْمَنَّانُ بِفَوَائِدِ النِّعَمِ وَ عَوَائِدِ الْمَزِيدِ وَ الْقِسَمِ، عِيَالُهُ الْخَلَائِقُ ضَمِنَ أَرْزَاقَهُمْ وَ قَدَّرَ أَقْوَاتَهُمْ وَ نَهَجَ سَبِيلَ الرَّاغِبِينَ إِلَيْهِ وَ الطَّالِبِينَ مَا لَدَيْهِ وَ لَيْسَ بِمَا سُئِلَ بِأَجْوَدَ مِنْهُ بِمَا لَمْ يُسْأَلْ؛ الْأَوَّلُ الَّذِي لَمْ يَكُنْ لَهُ قَبْلٌ فَيَكُونَ شَيْ‏ءٌ قَبْلَهُ، وَ الْآخِرُ الَّذِي [لَمْ يَكُنْ‏] لَيْسَ لهُ بَعْدٌ فَيَكُونَ شَيْ‏ءٌ بَعْدَهُ؛ وَ الرَّادِعُ أَنَاسِيَّ الْأَبْصَارِ عَنْ أَنْ تَنَالَهُ أَوْ تُدْرِكَهُ؛ مَا اخْتَلَفَ عَلَيْهِ دَهْرٌ فَيَخْتَلِفَ مِنْهُ الْحَالُ وَ لَا كَانَ فِي مَكَانٍ فَيَجُوزَ عَلَيْهِ الِانْتِقَالُ\nترجمه:\nحمد و ستايش مخصوص خداوندى است که بازداشتن و امساک چيزى بر دارايى اش نمى افزايد، و سخاوت و بخشش او را فقير نمى سازد; چراکه هر بخشنده اى غير از او دارايى اش نقصان مى يابد، و هرکس جز او، دست از عطا و بخشش بازدارد، مذموم شمرده مى شود. اوست بخشنده انواع نعمت ها و افزون کننده درآمدها و بهره ها. همه بندگان جيره خوار اويند، و روزى همه آنها را تضمين کرده، و قوت آنها را معين ساخته است و راه را به علاقه مندان خود، و جويندگانِ آنچه نزد اوست، نشان داده است. چنان نيست که سخاوت او در آنجا که از وى چيزى بخواهند، بيشتر از موقعى باشد که از او نخواهند.\nاو آغازى است که قبل ندارد، تا پيش از او چيزى باشد، و پايانى است که بعد ندارد، تا بعد از او وجودى باشد (بلکه از ازل تا ابد بوده و خواهد بود). مردمک چشم ها را، از مشاهده و درک ذاتش بازداشته است (نه چشم ظاهر او را مى بيند، و نه چشم باطن به کنه ذاتش مى رسد). زمانى بر آن نگذشته تا حالش دگرگون شود، و در مکانى نبوده که جابه جايى براى او تصوّر شود.\nتفسیر:\nخطبه الاشباح \nاین خطبه از خطبه‌های نورانی و درخشان امیرالمؤمنین (ع) است. این روایت در سایر منابع روایی نیز ذکر شده و راوی آن امام جعفر صادق (ع) است و از نظر سند، متواتر است.\nمسعده بن صدقه از یاران امام صادق (ع) نقل می‌کند که حضرت فرمود: روزی جدم امیرالمؤمنین (ع) بر منبر قرار داشت و سخنرانی می‌کرد که فردی وارد مجلس شد و گفت: خدا را برای من وصف کن، آن‌گونه که او را می‌بینم. دلم می‌خواهد عشق و معرفتم به خدا زیاد شود. امیرالمؤمنین (ع) ناراحت شد و فرمود: به مردم بگویید همه برای نماز به مسجد بیایند. مردم جمع شدند؛ مجلس مملو از جمعیت شد. حضرت درحالی‌که آثار ناراحتی در چهره‌اش آشکار بود، به منبر رفت. پس از حمد و ثنای الهی و صلوات بر پیامبر (ص) و خاندانش (ع) فرمود:\n«أَلْحَمْدُ لِلَّهِ الَّذِی لَا یفِرُّهُ الْمَنْعُ وَالْجُمُودُ وَلَا یکدِیهِ الْإِعْطَاءُ وَالْجُودُ»\nستایش خدایی را سزاست که نبخشیدن، بر مال او نیفزاید و بخشش، او را فقیر نسازد.\nبرخی انسان‌ها بخیل و طمع‌کارند و می‌ترسند از بخشش، ثروتشان کم شود و به کسی نمی‌دهند تا ثروتشان زیاد شود؛ درحالی‌که خدای متعال این‌گونه نیست. اگر به کسی چیزی ندهد، سرمایه‌اش زیاد نمی‌شود و اگر همهٔ خلائق را روزی دهد، چیزی از خزانه‌اش کم نمی‌شود.\n«إِذْ کلُّ مُعْطٍ مُنْتَقِصٌ سِوَاهُ»\nزیرا هر بخشنده‌ای جز او، اموالش کاهش یابد.\nهر کسی در عالم بخشنده باشد، ثروتش کم می‌شود. تنها کسی که هر چه خرج کند، ضرری به سرمایه‌اش نمی‌خورد، خداست. دراین‌رابطه حدیث قدسی با این مضمون وجود دارد: ای مردم! بدانید اگر اول و آخر و جن و انس شما در یک صحرا با هم جمع شوید، همه از من درخواست کنید و هر کس را هر چیزی که بخواهد بدهم، چیزی از من کم نمی‌شود. مثل‌اینکه سر سوزنی را داخل اقیانوسی پهناور بزنیم؛ سرسوزن خیس می‌شود، اما چیزی از اقیانوس کم نمی‌شود. البته این مثال برای مقایسه با خدای متعال هم مثال دقیقی نیست.\n«وَکلُّ مَانِعٍ مَذْمُومٌ مَا خَلَاهُ»\nو جز او هر کس از بخشش دست کشد، مورد نکوهش قرار گیرد.\nهر کس در عالم دیگران را از انفاق منع کند، مذموم و ناپسند است، غیر از خدای متعال. تنها کسی که در عالم اگر اعطا نکند، مذموم نیست، خدای متعال است. چون انسان‌ها اگر چیزی به کسی نمی‌دهند، به‌خاطر بخل، ترس یا حرص است؛ اما خدا این‌گونه نیست. اگر به بنده چیزی ندهد، مصلحتِ بنده در آن است. اگر بدهد از روی جود و بخشش است و اگر ندهد، از روی حساب‌وکتاب است. مضمون حدیث قدسی: عده‌ای از بندگان، اگر پول به آن‌ها بدهم، فاسد می‌شوند و طغیان می‌کنند؛ مصلحتِ آن‌ها در تنگدستی است، چون کم‌ظرفیت هستند.\n«وَهُوَ الْمَنَّانُ بِفَوَائِدِ النِّعَمِ وَعَوَائِدِ الْمَزِیدِ وَالْقِسَمِ»\nاوست بخشندهٔ انواع نعمت‌ها و بهره‌های فزاینده و تقسیم‌کنندهٔ روزی پدیده‌ها.\nخدایی که بسیار بخشنده است و نعمت‌هایی که به ما می‌دهد، سودمند و پرفایده است (نعمت شخصی) و نعمت‌هایی که به جامعه می‌دهد، هر کدام برای اصلاح یک جامعه کافی است که می‌توان به امنیتِ اجتماعی به‌عنوان یک نعمت اشاره کرد. «منّان» در اینجا یعنی کسی که پیش از آنکه دهانِ بنده برای درخواست باز شود، خدا اجابت می‌کند. نیازی به دعاکردن و التماسِ بنده نیست.\n«عِیالُهُ الْخَلَائِقُ»\nمخلوقات، همه جیره‌خوارِ سفرهٔ اویند.\n«ضَمِنَ أَرْزَاقَهُمْ»\nخدا رزقِ تک‌تکِ این بنده‌ها را تضمین کرده است. خدا در دورافتاده‌ترین بیابان‌ها و کوه‌ها، مخلوقاتش را در موعد مقرر روزی می‌دهد.\n«وَقَدَّرَ أَقْوَاتَهُمْ»\nو قوتِ غالبِ آن‌ها را مقرر نموده است.\n«وَنَهَجَ سَبِیلَ الرَّاغِبِینَ إِلَیهِ وَالطَّالِبِینَ مَا لَدَیهِ»\nبه مشتاقانِ خویش و خواستارانِ آنچه در نزد اوست، راهِ روشن را نشان داد.\nخدایی است که راه خودش را برای بنده روشن کرد، به شرطی که راغب و متمایل باشد. اگر کسی خدا را بخواهد، راهش را پیدا می‌کند که همان راه اهل‌بیت (ع) است. راه برای این فرد واضح است. کسی که خدا را نمی‌بیند، کور است که نمی‌بیند؛ کسی که دغدغه دارد، راه خدا را دیده است.\n«لَیسَ بِمَا سُئِلَ بِأَجْوَدَ مِنْهُ بِمَا لَمْ یسْأَلْ»\nسخاوتِ خدا در آنجا که از او بخواهند، یا جایی که از او درخواست نکنند، بیشتر نیست.\nاین‌طور نیست کسی بیشتر دعا بخواند عطای بیشتری از خدا دریافت کند تا شخصی که دعا نخوانده؛ درحالی‌که خدا به همه جود و عطا دارد. درخواست و دعای ما در عطای خدا تأثیری ندارد.\nسؤال: اگر دعا تأثیر ندارد، پس چرا ما مأمور به دعا هستیم؟! نقش دعا چیست؟!\nنکته اول: یک سلسله از ادعیه، معرفتی هستند. دعا برای خداشناسی و معارف، ویژگیِ دعاست؛ با تضرع که معرفت حاصل شود. مانند دعای عرفه.\nنکته دوم: دعاهایی که درخواستی هستند، آیا تأثیر ندارند؟ سنت خدا بر این است که ظرفِ خالی را پر می‌کند. اگر کسی با ظرفِ خالی به درگاه الهی آمد و لب به سخن باز نکرد، خدا حتماً به او عطا می‌کند، چون ظرفِ او خالی است. برعکس، کسی که ظرفش آلوده و پر باشد، اما شب تا صبح دعا و ناله کند، به او عطایی نمی‌شود؛ ظرفِ پر هر چه داده شود سرریز می‌شود و این خلاف حکمت است و خدا حکیم محض است. ذره‌ای خلل در حکمت او نیست. ظرفی که عاری از نجاست نباشد با آب زمزم پر نمی‌شود، چون به هدر می‌رود.\nتأثیر دعا در این است که ظرفِ وجود را بزرگ می‌کند. وظیفهٔ ما دعا خواندن است و دعا، وسعت‌دادن به انسان است؛ وقتی انسان به خدا متصل شود، ظرفِ او بزرگ می‌شود. پس هر دعایی ظرف را بزرگ نمی‌کند؛ دعای بدون توجه و طوطی‌وار خواندن، گنجایش ظرف را وسعت نمی‌دهد. دعایی که با برقراریِ اتصال خوانده شود، ظرف را بزرگ می‌کند و خدا ظرفِ خالی را پر می‌کند.\nپیش از آنکه دنبال دعا خواندن باشید، دنبال افزایش ظرفیت باشید. دعا مقدمهٔ وسعتِ ظرف است، اما دعایی که با توجه باشد. اگر در دعا گنجایش ظرف نباشد، دعا نبوده، صرفِ روخوانیِ عربی بوده است.\nفرمود: «قُرِنَ الْحَیاءُ بِالْحِرْمَانِ». در امور دنیایی، کسی که مصر و جسور نباشد، چیزهایی را از دست می‌دهد؛ پررویی و جسور بودن در دنیا، زودتر به مقصود می‌رسد. اما در بارگاه خدا و امور معنوی این‌گونه نیست؛ آنچه ملاک است، ظرفیت است.\nفرمود: به آنچه به آن امید ندارید، بیشتر امیدوار باشید. گاهی به آنچه امیدِ رسیدن نیست؛ اما ظرفیت آن فراهم شده باشد، عطا می‌رسد. اما گاهی تکیه بر «من» است. همه چیز بر مبنای «من» حساب می‌شود.\nروایت: موسی بن عمران به دنبال شعلهٔ آتشی رفت؛ اما پیغمبر برگشت؛ اصلاً دعا و درخواستی برای پیامبر شدن نکرد، اما ظرفیت ایجاد شد و خدا آن را پر کرد. ساحران برای آبروی فرعون جمع شدند؛ درخواست و فکر آن‌ها این نبود که مؤمن شده برگردند، اما ظرفیتِ مؤمن و موحد شدن بود، کمک‌کار موسی شدند. موسای کلیم ظرفیت داشت، بدون درخواست، پیامبری به او عطا شد. حضرت ابراهیم وقتی ظرفِ پیامبری‌اش پر شد، برای فرزندان خود هم امامت درخواست کرد. فرمود: «لَا ینَالُ عَهْدِی الظَّالِمِینَ»؛ داده نمی‌شود؛ چون ظرفیت ندارند.\n«الْأَوَّلُ الَّذِی لَمْ یکنْ لَهُ قَبْلٌ فَیکونَ شَیءٌ قَبْلَهُ وَالْآخِرُ الَّذِی لَیسَ لَهُ بَعْدٌ فَیکونَ شَیءٌ بَعْدَهُ»\nخدا اولی است که آغاز ندارد تا پیش از او چیزی بوده باشد، و آخری است که پایان ندارد تا چیزی پس از او وجود داشته باشد. خدا همان کسی است که اول است و قبل از او کسی نیست، و آخری است که بعد از او کسی نیست.\n«وَالرَّادِعُ أَنَاسِی الْأَبْصَارِ عَنْ أَنْ تَنَالَهُ أَوْ تُدْرِکهُ»\nمردمکِ چشم‌ها را از مشاهدهٔ خود بازداشته است.\nخدا همان کسی است که مانع و بازدارندهٔ مردمکِ چشم‌هاست از اینکه بخواهند خدا را ببینند یا درک کنند؛ چون خدا جسم و دیدنی نیست. البته چشمِ دل می‌تواند جلواتِ خدای متعال را ببیند. ابو بصیر نابینا بود. می‌گوید: در ایام حج در خانهٔ خدا در کنار امام محمدباقر (ع) ایستاده بودم، صدا بلند بود. عرض کردم: الحمدلله امسال چقدر حاجی داریم. امام محمدباقر (ع) فرمود: این‌گونه نیست. چه بسیار است سروصدا و چقدر حاجی کم است! حضرت دستی بر صورتم کشید و ذکری گفت. چشمم بینا شد (نه چشم سر، بلکه چشمی که با آن باطنِ افراد را می‌دیدم). دور بیت‌الله را دیدم؛ اکثراً حیوان و تعداد کمی با قیافهٔ انسان بودند. دوباره حضرت دست بر صورتم کشید و چشمم بسته شد. با چشمِ سر نمی‌شود خدا را دید، ولی با چشمِ دل می‌شود جلواتِ خدا را دید.\n«مَا اخْتَلَفَ عَلَیهِ دَهْرٌ فَیخْتَلِفَ مِنْهُ الْحَالُ»\nخدای متعال هیچ‌وقت در گیرودارِ این روزگار نبوده است؛ وقتی انسان در گیرودارِ روزگار نباشد، احوالش هم متغیر نیست. خدا این‌گونه نیست؛ سختی و رنج و جنگ برایش معنا ندارد.\n«وَلَا کانَ فِی مَکانٍ فَیجُوزَ عَلَیهِ الِانْتِقَالُ»\nو در مکانی قرار ندارد تا پندارِ جابه‌جایی نسبت به او روا باشد. خدا در جای خاصی نیست؛ خدا در همه‌جا هست؛ در آسمان‌ها و در زمین و در همه‌جا.\n«اللَّهُمَّ نَوِّرْ أَسْمَاعَنَا وَأَبْصَارَنَا»","بخش دوم\nمتن:\nوَ لَوْ وَهَبَ مَا تَنَفَّسَتْ عَنْهُ مَعَادِنُ الْجِبَالِ وَ ضَحِكَتْ عَنْهُ أَصْدَافُ الْبِحَارِ مِنْ فِلِزِّ اللُّجَيْنِ وَ الْعِقْيَانِ وَ نُثَارَةِ الدُّرِّ وَ حَصِيدِ الْمَرْجَانِ مَا أَثَّرَ ذَلِكَ فِي جُودِهِ وَ لَا أَنْفَدَ سَعَةَ مَا عِنْدَهُ؛ وَ لَكَانَ عِنْدَهُ مِنْ ذَخَائِرِ الْأَنْعَامِ مَا لَا تُنْفِدُهُ مَطَالِبُ الْأَنَامِ لِأَنَّهُ الْجَوَادُ الَّذِي لَا يَغِيضُهُ سُؤَالُ السَّائِلِينَ وَ لَا [يُبَخِّلُهُ‏] يُبْخِلُهُ إِلْحَاحُ الْمُلِحِّينَ‏.\nصفاته تعالى في القرآن:\nفَانْظُرْ أَيُّهَا السَّائِلُ فَمَا دَلَّكَ الْقُرْآنُ عَلَيْهِ مِنْ صِفَتِهِ فَائْتَمَّ بِهِ وَ اسْتَضِئْ بِنُورِ هِدَايَتِهِ، وَ مَا كَلَّفَكَ الشَّيْطَانُ عِلْمَهُ مِمَّا لَيْسَ فِي الْكِتَابِ عَلَيْكَ فَرْضُهُ وَ لَا فِي سُنَّةِ النَّبِيِّ صلی الله علیه وآله وَ أَئِمَّةِ الْهُدَى أَثَرُهُ فَكِلْ عِلْمَهُ إِلَى اللَّهِ سُبْحَانَهُ فَإِنَّ ذَلِكَ مُنْتَهَى حَقِّ اللَّهِ عَلَيْكَ؛ وَ اعْلَمْ أَنَّ الرَّاسِخِينَ فِي الْعِلْمِ هُمُ الَّذِينَ أَغْنَاهُمْ عَنِ اقْتِحَامِ السُّدَدِ الْمَضْرُوبَةِ دُونَ الْغُيُوبِ الْإِقْرَارُ بِجُمْلَةِ مَا جَهِلُوا تَفْسِيرَهُ مِنَ الْغَيْبِ الْمَحْجُوبِ، فَمَدَحَ اللَّهُ تَعَالَى اعْتِرَافَهُمْ بِالْعَجْزِ عَنْ تَنَاوُلِ مَا لَمْ يُحِيطُوا بِهِ عِلْماً وَ سَمَّى تَرْكَهُمُ التَّعَمُّقَ فِيمَا لَمْ يُكَلِّفْهُمُ الْبَحْثَ عَنْ كُنْهِهِ رُسُوخاً. فَاقْتَصِرْ عَلَى ذَلِكَ وَ لَا تُقَدِّرْ عَظَمَةَ اللَّهِ سُبْحَانَهُ عَلَى قَدْرِ عَقْلِكَ فَتَكُونَ مِنَ الْهَالِكِينَ. \nترجمه:\nاگر آنچه از درون سينه معادن کوهها بيرون مى ريزد، يا از دهان صدف هاى دريا خارج مى شود: از نقره خالص و طلاى ناب و دانه هاى دُرّ و شاخه هاى مرجان (و در يک کلمه، تمام ذخاير جهان) را ببخشد، در جود و سخايش کمترين اثرى نمى گذارد، و از وسعت نعمت هايش نمى کاهد; آن قدر نزد او از ذخاير نعمت ها است، که تقاضاهاى مردم آن را از ميان نمى برد; چرا که او سخاوتمندى است که پاسخ گويى به تقاضاى سائلان، چيزى از او نمى کاهد، و اصرارِ اصرارکنندگان، او را به بخل وانمى دارد.\nاى کسى که از صفات خدا سؤال کردى! درست بنگر آنچه را قرآن از صفات او بيان کرده است از آن پيروى کن و از نور هدايتش روشنايى بگير و آنچه را شيطان فرا گرفتنش را به تو تکليف مى کند - از امورى که در کتاب خدا بر تو واجب نشده و اثرى از آن در سنّت پيامبر(صلى الله عليه وآله) و ائمه هُدى نيامده است - علمش را به خداوند واگذار کن; که اين نهايت حق خدا بر توست. و بدان راسخان و استواران در علم، آنها هستند که خداوند آنان را به خاطر اقرار اجمالى به تمام آنچه از آنها پوشيده است و تفسير آن را نمى دانند، از فرو رفتن در عمق اسرار نهانى بى نياز ساخته و از اين جهت که به عجز خويش در برابر آنچه از تفسيرش ناتوانند اعتراف دارند خداوند آنها را ستوده و ترک بحث و تعمّق در آنچه پروردگار بر عهده آنان نگذاشته است را رسوخ در علم ناميده (و آنان را راسخان و ثابت قدمان در دانش خوانده است;) به همين مقدار قناعت کن و عظمت خداوند سبحان را با مقياس عقل خود، اندازه مگير که از هالکان خواهى بود.\nتفسیر:\n خلاصه‌ای از بخش اول:\nشخصی از امیرالمؤمنین صلواتُ‌اللهِ علیه پرسید: خدا را چنان وصف کن که گویی ما او را می‌بینیم.\nحضرت از این سخن او ناراحت شدند؛\nچرا در شناخت خدا آن‌قدر ضعف دارید که گمان می‌کنید خدا جسم است و می‌توان او را مانند یک جسم توصیف کرد؟\nآن‌گاه به لطف و عطای خدا اشاره فرمودند:\nاگر خدا به همه عطا کند، چیزی از او کم نمی‌شود؛ و اگر از همه منع کند، چیزی بر او افزوده نمی‌گردد و اگر به کسی چیزی ندهد، از روی حکمت است که منع می‌کند.\nبرای روشن‌تر شدن این معنا، یک مثال مادی می‌زند:\nانسان‌ها باوجود ثروت زیاد، در برابر درخواست کمِ دیگران انفاق می‌کنند؛ اما اگر درخواست بزرگ باشد، دست رد به سینه می‌زنند و حتی از اصرار دیگران ناراحت هم می‌شوند. اما خداوند این‌گونه نیست.\nجود، علم و عظمت خدا را با خودتان قیاس نکنید.\n♦️وَلَوْ وَهَبَ مَا تَنَفَّسَتْ عَنْهُ مَعَادِنُ الْجِبَالِ\nاگر خدا ببخشد آنچه را که کوه‌ها نفس کشیده و بیرون ریخته‌اند.\n(منظور: معادن)\nکوه‌ها دم و بازدمی دارند که در هر بازدم، معادن از آن بیرون می‌ریزد.\nکوه را به انسانی تشبیه کرده است.\n♦️وَضَحِکتْ عَنْهُ أَصْدَافُ الْیحَارِ\nو صدف‌هایی که خندیدند [ضَحِکت]\nو مرواریدها از دل صدف بیرون آمدند. همه را خدا ببخشد.\n♦️مِنْ فِلِزِّ الْجُؤْنِ وَالْعِقْیانِ\nاز نقره‌های خالص [لُجّی] و طلای خالص [عِقیان] را ببخشد.\n♦️وَنُثَارَتِ الدُّرِّ وَحَصِیدِ الْمَرْجَانِ\nمرواریدهای غلتان و صیقلی [نُثارَة] و خوشه‌های مرجان [حَصید] را که هر کدام شیئی قیمتی و کم‌نظیرند، ببخشد.\n♦️مَا أَثَّرَ ذَاک فِی جُودِهِ وَلَا أَنْفَدَ سَعَةَ مَا عِنْدَهُ\nهیچ اثری در جود و لطف خدا ندارد.\nکسی هم اگر اصرار کند، ناراحت نمی‌شود.\nگسترهٔ اموال و ذخایر خدا از بین نمی‌رود. [لا أَنْفَدَ]\nمثل سوزنی که در دریای عظیم فروبرود؛ سرسوزن خیس می‌شود، اما آیا از آب اقیانوس چیزی کم می‌شود؟!\n♦️ ولکانَ عِنْدَهُ مِنْ ذَخَائِرِ الْإِنْعَامِ مَا لَا تُنْفِدُهُ مَطَالِبُ الْأَنَامِ\nهر آنچه نزد خداست، از ذخایر انعام، با درخواستِ انسان‌ها از میان نمی‌رود.\nاَنعام به معنای نعمت‌هاست؛ یعنی هرچه انسان طلب کند، برای خدا پایان‌پذیر نیست، چون برای خدا وزن، مقدار و اندازه معیار نیست.\nاِنْعام به معنای چهارپایان است؛ یکی از مصداق‌های نعمت‌ها، چهارپایان‌اند که از نعمت‌های مصرفی انسان‌ها به شمار می‌روند و نسبت به قرن‌های قبل چه اندازه افزایش یافته‌اند؛ خدا همه را می‌رساند و کم‌شدن در او راه ندارد.\n♦️لِأَنَّهُ الْجَوَادُ الَّذِی لَا یغِیضُهُ سُؤَالُ السَّائِلِینَ\nزیرا او آن بخشنده‌ای است که پرسشِ درخواست‌کنندگان، از گنجینه‌اش نمی‌کاهد. [لا یغِیضُ]\nعلت اینکه گنجینهٔ خدا تمام نمی‌شود چیست؟\nچون خدا بخیل نیست؛ بخل در او راه ندارد.\nبخل یکی از عواملی است که روزیِ انسان را کم می‌کند.\nانسان برای گسترده شدن ظرفیت و روزی خود باید بخل را کنار بگذارد.\n♦️وَلَا یبْخِلُهُ إِلْحَاحُ الْمُلِحِّینَ\nاصرارِ مُصِرّان و پافشاریِ اصرارکنندگان، خدا را به بخل نمی‌اندازد.\nدست رد به سینه نمی‌زند، بلکه به اندازهٔ ظرفیت و استعداد هر کس عطا خواهد کرد.\nیکی از نام‌های خدا «جواد» است؛ این فقط یک مصداق از اوصاف اوست. با یک اسم و صفت، نمی‌توان خدا را شناخت.\nآیا همین یک صفت را هم می‌شود از خدا فهمید؟!\nاصلاً در دایرهٔ فکر انسان می‌گنجد؟\nچگونه می‌توان عظمتِ کنهِ جودِ خدا را فهمید؟! اصلاً شدنی نیست.\nسؤالی که حضرت را ناراحت کرد این بود که این یک اصلِ ابتداییِ اعتقادی است که خدا دیدنی نیست؛ پس چرا چنین پرسش جسمانی‌ای مطرح می‌شود؟\n♦️فَانْظُرْ أَیهَا السَّائِلُ فَمَا دَلَّک الْقُرْآنُ عَلَیهِ مِنْ صِفَتِهِ فَاعْتَمِدْ بِهِ\nای پرسشگر، به همان صفاتی بسنده کن که قرآن برای خدا بیان کرده است.\nیک بحث عمیق کلامی اینجاست که آیا نام‌ها و صفات الهی به قرآن و روایت محدودند، یا انسان می‌تواند برای خدا صفتی در نظر بگیرد؟\nقول اول: اگر با تفکر و تعمق، صفتی باشد که هیچ نقص و ضعفی برای خدا نیاورد، می‌توان آن را پذیرفت.\nقول دوم: نام‌ها و صفات الهی متوقف بر آن چیزی است که قرآن و عترت فرموده‌اند؛ نمی‌توان برای خدا اسم و صفتی انتخاب کرد، چون چه‌بسا همان اسم، خدا را ناقص جلوه دهد.\nدر خداشناسیِ اسماء الهی، باید به قرآن رجوع کرد و فقط از آل الله پیروی نمود.\n♦️وَاسْتَضِیءْ بِهُدَایتِهِ\nاز هدایت خدانور بگیر. از هدایت خدا، نور و ضیاء بخواه.\nدو علم دربارهٔ خدا سخن می‌گوید:\nعلم کلام: سخن از صفات الهی است؛\nاینکه علم خدا چگونه است، آیا ذاتی است یا غیرذاتی، آیا نامحدود است، آیا شبیه علمِ خلق هست یا نه. این علم برای اثبات وجود خدا برهان اقامه می‌کند. این، خداشناسی و مجموعه‌ای از دانستنی‌هاست که در برابر منکر خدا، چند دلیل برای او نقل می‌شود.\nعلم عرفان: همین صفات در عرصهٔ عرفان به اسماءالله تبدیل می‌شوند. در این بخش، بحثِ صرفِ علم نیست، بلکه عمل است؛ اسم‌ها نور دارند.\nنام‌هایی مثل قدوس و سلام، استدلال نمی‌خواهند. در این اسماء، طلبِ نور لازم است و این با علم کلام متفاوت است.\nآنچه نور می‌دهد، سلوک است؛ باید به‌سوی آن رفت و از آن نور گرفت. از اسماءالله سبحان و منان، طلبِ نور و هدایت کنید.\n♦️وَمَا کلَّفَک الشَّیطَانُ عِلْمَهُ بِمَا لَیسَ فِی الْکتَابِ عَلَیک فَرْضُهُ\nآنچه شیطان تو را به دانستنِ آن مکلف می‌کند، درحالی‌که نه در قرآن آمده و نه در سخنان ائمه به آن توجه داده‌اند.\nبرخی از علوم در باب توحید مطرح‌اند که فقط برای عده‌ای خاص و برای اولیا قابل فهم‌اند و از سطح فهم معمولِ مردم بیرون‌اند. شیطان دقیقاً در همان‌جا وسوسه می‌کند که خدا را آن‌گونه بشناس و درباره‌اش فکر کن.\n♦️وَلَا فِی سُنَّةِ النَّبِی صَلَّی اللَّهُ عَلَیهِ وَآلِهِ وَأَئِمَّةِ الْهُدَیٰ أَثَرُهُ فَکلْ عِلْمَهُ إِلَی اللَّهِ سُبْحَانَهُ\nو نه در سنت نبی، آن علمِ توحیدیِ خاص به طور عمومی برای همه بیان شده است.\nهر کس بدون پشتوانهٔ علمی و پیش‌زمینه وارد این حوزه شود، احتمال انحراف دارد.\nمطالب توحیدی در دسترس همگان نیست و به‌سادگی دست‌یافتنی نیست؛ نباید فریبِ شیطان را خورد. وقتی انسان نتواند توحید را بفهمد، به خیال و توهمِ خدا پناه می‌برد.\nهیچ حقیقتِ نامحدودی برای یک ذهنِ محدود دست‌یافتنی و قابل تسلط نیست. انسان با ذهن محدود نمی‌تواند به آن وارد شود؛ پس باید در همان‌جا توقف کرد.\n♦️فَإِنَّ ذَٰلِک مُنْتَهَیٰ حَقِّ اللَّهِ عَلَیک\nاین نهایت حقِ خدا بر توست.\nیکی از حقوق خدا بر ما این است: انتظار نداشته باشیم که اشخاص در این مرحله به اوج برسند؛ بلکه بهترین کار این است که به نادانیِ خود اقرار کنند.\nدر مواجهه با صفات ذاتی و اسماءالله، حق خدا این است که به ندانستن و نفهمیدن اعتراف کنی.\nاین نفهمیدن، خودِ فهمیدن است.\nهر کس ادعا کند فهمیده، معلوم می‌شود که نادان است.\n♦️وَاعْلَمْ أَنَّ الرَّاسِخِینَ فِی الْعِلْمِ هُمُ الَّذِینَ أَغْنَاهُمْ عَنِ اقْتِحَامِ السُّدَدِ الْمَضْرُوبَةِ دُونَ الْغُیوبِ الْإِقْرَارُ بِجُمْلَةِ مَا جَهِلُوا تَفْسِیرَهُ مِنَ الْغُیوبِ الْمَحْجُوبَةِ\nبدانید که راسخان در علم، همان‌گونه که قرآن بیان فرموده و اهل‌بیت علیهم‌السلام هستند، کسانی‌اند که استواری و ثباتشان در علم، آنان را از فرورفتن [اقتحام] در منطقهٔ ممنوعه و درهای بستهٔ غیب بی‌نیاز کرده است؛ زیرا به آنچه از غیب و تفسیر آن نمی‌دانستند، اقرار کردند. غیب  الغیوب فقط خودِ خداست و کنه آن پوشیده و ناشناختنی است.\nهمین که فهمیدند نمی‌فهمند، راسخان فی العلم شدند.\nدر روایات، راسخان در علم را اهل‌بیت معرفی می‌کند؛ همان‌ها را در خطبه معرفی می‌کند برای کسانی که این بخش را نمی‌فهمند و به ناتوانی خود نیز اقرار می‌کنند.\n♦️فَمَدَحَ اللَّهُ اعْتِرَافَهُمْ بِالْعَجْزِ عَنْ تَنَاوُلِ مَا لَمْ یحِیطُوا بِهِ عِلْمًا\nخداوند این اعتراف به عجز را ستایش می‌کند؛ اینکه گفتند ما ذات و صفات تو را نمی‌شناسیم و علم ما بر آن احاطه ندارد.\nسخن از نشناختن است، چون خدا شناختنی نیست. وقتی امیرالمؤمنین او را نشناخت، برای دیگران روشن می‌شود که هیچ‌کس هرگز نمی‌تواند واجب‌الوجود را احاطه کند و بر صفات او محیط شود.\n♦️وَسَمَّیٰ تَرْکهُمْ التَّعَمُّقَ قَدَرًا لَمْ یکلِّفْهُمُ الْبَحْثَ عَنْ کنْهِهِ رُسُوخًا\nآن‌ها از تعمق و نفوذ در ذات خدا دست برداشتند.\nهمین که وارد آن محدودهٔ ممنوعه نمی‌شوند، راسخ در علم‌اند.\nبرعکس، کسی که بخواهد وارد آن محدوده شود، از حیطهٔ راسخان هم بیرون می‌رود، چون حدّ خود را نشناخته است.\nکسی که حدّ خود را نشناسد، اصلِ نخست را نفهمیده، خودشناسی نکرده و در نتیجه خداشناس هم نخواهد بود.\n♦️فَاقْتَصِرْ عَلَیٰ ذَٰلِک وَلَا تُقَدِّرْ عَظَمَةَ اللَّهِ سُبْحَانَهُ عَلَیٰ قَدْرِ عَقْلِک فَتَکونَ مِنَ الْهَالِکینَ\nخطاب به پرسشگر:\nعلوم خدا در حد کلیات، واجب است و ورود به کنهِ خدا ممنوع.\nهیچ‌گاه عظمت خدای سبحان را باعقل خود اندازه‌گیری مکن. علم خدا را باعقل خود نسنج؛ این کار به انحراف و هلاکت می‌کشاند.\nهنوز حقیقتِ روح برای انسان آشکار نشده است.\nخواب، عنصری است که با آن سروکار داریم، اما حقیقتش بر انسان روشن نیست.\n«النَّوْمُ أَخُ الْمَوْتِ»؛ این تشبیه نیست، حقیقتِ خواب و حقیقتِ مرگ یکی است. ذهنِ محاسبه‌گر وقتی این حقیقت را نمی‌داند و نمی‌فهمد، چگونه می‌تواند خدا را محاسبه کند؟!\nمگر خواب را فهمید که بخواهد مرگ را بفهمد و بداند چیست؟\n✳️ علم بر سه نوع است:\nعلمِ مشروط:\nمثلاً هر کس با مقدار معینی بنزین تا مسافت مشخصی می‌تواند حرکت کند.\nیا اگر دارویی خاص در شرایط خاص استفاده شود، بیماری بهبود می‌یابد. این‌ها علم مشروط‌اند.\nعلمِ محتوم:\nعلمی که اما و اگر ندارد؛ همان است که واقع می‌شود.\nدسترسیِ آل الله به این علمِ محتوم است؛ علمی که حتمی و قطعی است.\nعظمت پیامبر در این است که به این علوم قطعی آگاهی و دانایی دارد.\nعلمِ مکنون و مستور:\nاین علم حتی از آل الله و انبیا نیز مستور است. دسترسی به آن مخصوصِ خداست.\n🔺سؤال:\nآیا امیرالمؤمنین در لیلة المبیت، وقتی به‌جای پیامبر خوابید، می‌دانست که کشته نمی‌شود؟\nاگر می‌دانست که خیلی ارزش نداشت؛ شجاعت هم نمی‌خواست. ندانستنِ امیرالمؤمنین از چه سنخی است؟\nامام صادق صلواتُ‌اللهِ علیه فرمود:\n«الْإِمَامُ إِذَا شَاءَ أَنْ یعْلَمَ عَلِمَ»\nامام هرگاه بخواهد بداند، خدا به او عنایت می‌کند؛ اما اگر خدا نخواهد، نمی‌داند. این همان علمِ مکنونی است که باید نداند.\nامیرالمؤمنین صلواتُ‌اللهِ علیه باید جان‌برکف در بستر بخوابد و کشته نشود.\nابراهیم خلیل سوار بر منجنیق از خود دست کشید تا گلستان شود.\nکارد را به‌قصد بریدن گلوی فرزند می‌کشد؛ اگر می‌دانست چاقو نمی‌برد، امتحان معنا نداشت.\nاو می‌رود تا ببرد و علم دارد، اما خدا آن بخش از علم را به او آگاه نمی‌کند.\nبنا بود که چاقو ببرد، اما در علم خدا نباید ببرد.\nخدا کسی نیست که بتوان او را بازجویی کرد: چرا؟ چگونه؟\nپیامبران هم مأمورانی هستند که در برابر برخی امور الهی، اگر خدا نخواهد، نمی‌دانند؛ آنان فقط مأمورِ ابلاغ سخنان خدا هستند.\nعلمِ مکنون در حوزه‌ای است که حتی اهل‌بیت هم در آن وارد نمی‌شوند.\n✅ آیا امیرالمؤمنین آن‌گونه که شایستهٔ خدا بود، خدا را شناخت؟\nنشناخت؛ چون کنهِ ذات او بر کسی معلوم نیست. اما شناختِ امیرالمؤمنین نسبت به خدا، با شناختِ ما قابل‌قیاس نیست.\nما هیچ نمی‌دانیم، اما علی آنچه را باید بداند می‌داند؛ فقط کنه را نمی‌داند.\nندانستنِ ما مانند ندانستنِ علی نیست؛ ما و او یکسان نیستیم.\n«مَا عَرَفْنَاک» آنان جز ذاتِ خدا را بسیار می‌شناسند.\nاللَّهُمَّ حَقِّقْنَا بِحَقَائِقِ الْإِیمَانِ","بخش سوم\nمتن:\nهُوَ الْقَادِرُ الَّذِي إِذَا ارْتَمَتِ الْأَوْهَامُ لِتُدْرِكَ مُنْقَطَعَ قُدْرَتِهِ وَ حَاوَلَ الْفِكْرُ الْمُبَرَّأُ مِنْ [خَطْرِ] خَطَرَاتِ الْوَسَاوِسِ أَنْ يَقَعَ عَلَيْهِ فِي عَمِيقَاتِ غُيُوبِ مَلَكُوتِهِ وَ تَوَلَّهَتِ الْقُلُوبُ إِلَيْهِ لِتَجْرِيَ فِي كَيْفِيَّةِ صِفَاتِهِ وَ غَمَضَتْ مَدَاخِلُ الْعُقُولِ فِي حَيْثُ لَا تَبْلُغُهُ الصِّفَاتُ لِتَنَاوُلِ عِلْمِ ذَاتِهِ، رَدَعَهَا وَ هِيَ تَجُوبُ مَهَاوِيَ سُدَفِ الْغُيُوبِ مُتَخَلِّصَةً إِلَيْهِ سُبْحَانَهُ، فَرَجَعَتْ إِذْ جُبِهَتْ مُعْتَرِفَةً بِأَنَّهُ لَا يُنَالُ بِجَوْرِ الِاعْتِسَافِ كُنْهُ مَعْرِفَتِهِ وَ لَا تَخْطُرُ بِبَالِ أُولِي الرَّوِيَّاتِ خَاطِرَةٌ مِنْ تَقْدِيرِ جَلَالِ عِزَّتِه.\nالَّذِي ابْتَدَعَ الْخَلْقَ عَلَى غَيْرِ مِثَالٍ امْتَثَلَهُ وَ لَا مِقْدَارٍ احْتَذَى عَلَيْهِ مِنْ خَالِقٍ مَعْبُودٍ كَانَ قَبْلَهُ، وَ أَرَانَا مِنْ مَلَكُوتِ قُدْرَتِهِ وَ عَجَائِبِ مَا نَطَقَتْ بِهِ آثَارُ حِكْمَتِهِ وَ اعْتِرَافِ الْحَاجَةِ مِنَ الْخَلْقِ إِلَى أَنْ يُقِيمَهَا بِمِسَاكِ قُوَّتِهِ مَا دَلَّنَا بِاضْطِرَارِ قِيَامِ الْحُجَّةِ لَهُ عَلَى مَعْرِفَتِهِ، فَظَهَرَتِ الْبَدَائِعُ الَّتِي أَحْدَثَتْهَا آثَارُ صَنْعَتِهِ وَ أَعْلَامُ حِكْمَتِهِ، فَصَارَ كُلُّ مَا خَلَقَ حُجَّةً لَهُ وَ دَلِيلًا عَلَيْهِ، وَ إِنْ كَانَ خَلْقاً صَامِتاً فَحُجَّتُهُ بِالتَّدْبِيرِ نَاطِقَةٌ وَ دَلَالَتُهُ عَلَى الْمُبْدِعِ قَائِمَةٌ.\nترجمه:\nاو خداوند توانايى است که اگر نيروى اوهام و انديشه ها براى درک گستره قدرتش بکار افتد و افکار بلندِ مبرّاى از وسوسه ها، براى فهم عميق غيب ملکوتش به جولان درآيد و قلب هاى مملوّ از عشق به او، براى پى بردن به کيفيّات صفاتش به کوشش پردازد و عقل هاى پر توان، با دقّت و باريک بينى هر چه بيشتر، براى درک ذات پاکش - در آنجايى که توصيفات بشرى به آن نمى رسد - گام بردارد، دست ردّ بر سينه همه آنها مى گذارد و همه را به عقب مى راند، در حالى که در تاريکى هاى غيب، براى خلاصى خويش به خداوند سبحان پناه مى برند (و از گرفتار شدن در دام شرک و تشيبه بيمناکند.) سپس باز مى گردند و اعتراف مى کنند که هرگز با تلاش و کوشش نمى توان به کنه ذات و صفات او رسيد و با فکر و عقل نارساى بشر نتوان او را درک کرد و اندازه عظمت و عزّتش به فکر انديشمندان خطور نمى کند.\nاو خدايى است که موجودات را از کتم عدم بوجود آورده، بى آنکه از نقشه قبلى ديگرى اقتباس کند، يا در آفرينش از آفريدگارى پيش از خود، سرمشق بگيرد، و آنقدر از ملکوت قدرت خود و شگفتى هايى که آثار حکمتش از آن سخن مى گويد و از نياز موجودات به قدرتِ برپا دارنده اى خبر مى دهد، به ما نشان داده که ما را بى اختيار به معرفت و شناخت او دعوت مى کند. بدين ترتيب، ابداعاتى را آثار صنع او و نشانه هاى حکمتش بوجود آورده، که هر يک از مخلوقاتش حجّت و دليلى بر وجود او هستند; هر چند به ظاهر مخلوقى خاموشند، ولى (با زبان بى زبانى، امّا با صراحت و وضوح) از تدبير او سخن مى گويند و همواره گواه بر آفريدگارند.\nتفسیر:\nخطبهٔ اشباح\nنهج‌البلاغه یعنی جهان‌بینی حضرت؛ یعنی نگاه توحیدی به‌نظام آفرینش داشتن.\n💠هُوَ الْقَادِرُ الَّذِی إِذَا ارْتَمَتِ الْأَوْهَامُ لِتُدْرِکَ مُنْقَطَعَ قُدْرَتِهِ وَ حَاوَلَ الْفِکْرُ الْمُبَرَّأُ مِنْ خَطَرَاتِ الْوَسَاوِسِ أَنْ یَقَعَ عَلَیْهِ فِی عَمِیقَاتِ غُیُوبِ مَلَکُوتِهِ\nخدای متعال قادر است. قادر بودن خدا از صفاتِ ذات خداست. قادری است که وقتی اوهامِ انسان‌ها برای رسیدن به منتهاالیه قدرت خدا حرکت کنند، هرگز دستشان به آن نمی‌رسد. اگر انسان فکر را (آن فکری که از خطورِ وسوسه‌های شیطانی در امان است) برای شناختِ کیفیت ذات خدا به کار بیندازد که خدا را در عمیق‌ترین بخش‌های ملکوتش بشناسد، نمی‌تواند.\nهواوهوس موجب پنهان‌شدن و کاهش قدرت تفکر می‌شود و از عاقلانه فکرکردن جلوگیری می‌کند.\n💠وَ تَوَلَّهَتِ الْقُلُوبُ إِلَیْهِ لِتَجْرِیَ فِی کَیْفِیَّهِ صِفَاتِهِ\nاگر قلوب (چشم باطن) برای شناختِ کنه ذات خدا واله و حیران شوند، نمی‌توانند. نه اینکه قلب ضعیف باشد؛ قلب نسبت به شناخت ذات خدا ناتوان است. حتی عارفان هم در این کار درمانده‌اند.\nپیامبر صلی‌الله علیه و آله (که در نورانیتِ چشم باطن کسی به ایشان نمی‌رسد) فرمود:\n«ما عرفناک حق معرفتک»\n💠وَ غَمَضَتْ مَدَاخِلُ الْعُقُولِ فِی حَیْثُ لَا تَبْلُغُهُ الصِّفَاتُ لِتَنَاوُلِ عِلْمِ ذَاتِهِ رَدَعَهَا\nغمضت (کنایه از دقت و باریک‌بینی)\nاگر عقول توجه بسیار کنند که خبر از ذات خدا داشته باشند، اصلاً ممکن نیست.\nخدای متعال دستِ رد بر عقل می‌زند (ردع) و کار عقل پیش نمی‌رود.\nخدا دستِ رد به سینهٔ عقل، وهم و قلب می‌زند؛ درحالی‌که آن‌ها مهلکه‌ها و دره‌هایی را که از غیب تاریک هستند، طی کرده‌اند. کنه ذات خدا تاریک است؛ یعنی از نظر دسترسی و مبهم بودن، تاریک است.\n💠وَ هِیَ تَجُوبُ مَهَاوِیَ سُدَفِ الْغُیُوبِ مُتَخَلِّصَهً إِلَیْهِ سُبْحَانَهُ، فَرَجَعَتْ إِذْ جُبِهَتْ مُعْتَرِفَهً بِأَنَّهُ لَا یُنَالُ بِجَوْرِ الِاعْتِسَافِ کُنْهُ مَعْرِفَتِهِ وَ لَا تَخْطُرُ بِبَالِ أُولِی الرَّوِیَّاتِ خَاطِرَهٌ مِنْ تَقْدِیرِ جَلَالِ عِزَّتِه\nاین صحبت‌ها دربارهٔ انسان‌های خالص است که تمام اخلاص خود را به کار بسته‌اند. با قلب و عقل خالص می‌خواهند به کنه ذات خدا دست یابند؛ ولی شدنی نیست. انسان ممکن‌الوجود است و خدا واجب‌الوجود؛ چطور انسانی که خدا امکانِ وجود به او می‌دهد، به واجب‌الوجود مسلط شود؟!\nهر مسیری که انسان بخواهد برای دسترسی به کنه ذات خدا طی کند، بیراهه است.\nدانشمندان و فلاسفه سر از عظمت خدا درنمی‌آورند. فکرکردن دربارهٔ عظمت خدا، انسان را سربه‌راه می‌کند.\nاینکه حضرت بیان می‌کند خدا قادر است، یک گزاره یا خبرِ ساده نیست؛ بلکه باید وقتی این جمله را شنیدیم، تأثیر آن را در زندگی بررسی کنیم. علم خدا انسان را سربه‌راه می‌کند و مانع از گردن‌کشیِ او می‌شود.\nسؤال: پس با این مطالب، راهی برای شناخت خدا نیست؟\nبعضی در پاسخ گفته‌اند خیر، هیچ راهی نیست؛ این‌ها «معطله» نام دارند که بیان می‌دارند هرگونه شناختی نسبت به خدا تعطیل است.\nولی حضرت برای اینکه کسی این فکر خام و غلط را نداشته باشد، می‌فرماید:\n💠الَّذِی ابْتَدَعَ الْخَلْقَ عَلَی غَیْرِ مِثَالٍ امْتَثَلَهُ وَ لَا مِقْدَارٍ احْتَذَی عَلَیْهِ مِنْ خَالِقٍ مَعْبُودٍ کَانَ قَبْلَهُ وَ أَرَانَا مِنْ مَلَکُوتِ قُدْرَتِهِ وَ عَجَائِبِ مَا نَطَقَتْ بِهِ آثَارُ حِکْمَتِهِ وَ اعْتِرَافِ الْحَاجَهِ مِنَ الْخَلْقِ إِلَی أَنْ یُقِیمَهَا بِمِسَاکِ قُوَّتِهِ مَا دَلَّنَا بِاضْطِرَارِ قِیَامِ الْحُجَّهِ لَهُ عَلَی مَعْرِفَتِهِ\nخدای متعال عالم را خلق کرد. خلقِ او ابداعی و بدون کپی‌برداری و نمونه‌برداری بود. خدا سرمشقی از خدای قبلی نگرفت که عالم را خلق کند؛ اصلاً قبل از خلق، خلقی نبود و خلق کرد بدون آنکه از روشِ دیگران الگوبرداری (احْتَذَی عَلَیْهِ) کرده باشد.\nو ملکوتِ قدرتش را به ما نشان داد. کنه ذات خدا شناختنی نیست، اما راه برای شناخت خدا باز است.\nقدرت خود را نشان داد. عجایب خلقت را نشان داد؛ همان عجایبی که با شما صحبت می‌کنند که خدا چقدر قدرت دارد. هر کدام از این عجایب را که انسان نگاه می‌کند، با انسان سخن می‌گویند.\nآسمان‌ها که بدون ستون‌های دیدنی سرپا هستند (بغیر عمد ترون‌ها)، تصادمی و تصادفی نیستند، بلکه مخلوقِ خدایند.\nوقتی سخن از ذات باشد دستمان کوتاه است، ولی جلوهٔ او در آثار خدا دیدنی است. خدا به مخلوقات نشان داد که مخلوق محتاج است. این همان برهان امکان و وجوب (امکان الوجود) است.\nدر انفس و آفاق، مظاهر خداشناسی هست. انسانی که محتاج است، چه کسی در عالم احتیاج او را برطرف می‌کند؟ درست است که مقدار احتیاج متفاوت است، ولی همه محتاجیم؛ یک نفر باید غنی باشد و او خداست.\nخدا انسان را راهنمایی کرد و به او نشان داد؛ اموری را که حتماً انسان به اضطرار و ناچار است به خالق بودنِ خدا اقرار کند. خدا هست و خالق و مدبر هستی هم خداست؛ حتی کافر و مشرک هم نمی‌تواند بگوید خدا نیست.\nبه تعبیر قرآن: «ولَئِن سَئَلتَهم من خلقَ السمواتِ و الرضِ لیَقولُنَّ الله»\nکسی نمی‌تواند این را نپذیرد.\nفطرت‌ها فریاد می‌زنند که خدا هست.\nخداشناسی لاجرم و اضطراری است. این اضطرار به معنای اجبار نیست؛ یعنی راهی برای انکار باقی نمانده و به هر جا بنگریم خدا را نشان می‌دهد.\nمخلوقات آینهٔ خدا هستند. آینهٔ دنیا هر کس مقابلش بایستد همان را نشان می‌دهد؛ اما مرآت بودن مخلوقات به‌گونه‌ای است که فقط یک نفر را نشان می‌دهند.\nزمین آینهٔ خدا نماست. هر پدیده‌ای آینهٔ خدا نماست و فقط خالق خود را نشان می‌دهد.\nمثالِ مورچه که برخی بذرها را دونیم و برخی را چهار قسمت می‌کند؛\nطی تحقیقات ثابت شده که برخی بذرها اگر نصف شوند رشد نمی‌کنند، اما برخی دیگر اگر دو نصف شوند، در تاریکی و رطوبتِ زمین‌باز هم رشد می‌کنند. چه کسی این را به مورچه یاد داده که آن بذر را چهار قسمت کند تا مانع رشدش شود؟ مورچه با این زبان می‌گوید که خدا به او آموزش داده است.\n💠وَ ظَهَرَتِ فِی الْبَدَائِعِ الَّتِی أَحْدَثَهَا آثارُ صَنْعَتِهِ وَ أَعْلَامُ حِکْمَتِهِ فَصَارَ کُلُّ مَا خَلَقَ حُجَّهً لَهُ وَ دَلِیلًا عَلَیْهِ وَ إِنْ کَانَ خَلْقاً صَامِتاً فَحُجَّتُهُ بِالتَّدْبِیرِ نَاطِقَهٌ وَ دَلَالَتُهُ عَلَی الْمُبْدِعِ قَائِمَهٌ\nخدا آثار صنعت و نشانه‌های حکمتِ خود را در پدیده‌هایی که آفریده نشان داد. هر کدام از این مخلوقات، حجتی بر وجود خدا هستند. هر کدام از این مخلوقات، نشانه و دلیل قطعی بر وجود خدا هستند.\nاگرچه مخلوقات صامت هستند، اما درونِ پرغوغایی دارند؛ سروصدایی دارند که خالق ما خداست. آن‌ها بر مسیرِ حکمت خدا حرکت می‌کنند، مطیع هستند و به تدبیرِ خدا سخن می‌گویند. این‌ها دلالت بر وجود یک مبدع دائمی دارند و بیان می‌دارند که خالق شما خداست و استمرار وجود شما نیز به دست خداست.\nدر عالم هستی گستاخ‌تر از انسان نداریم که از جهت قدرت ضعیف‌ترین موجود است؛ ولی از جهت ادعا، ادعای زیادی دارد. آسمان با این عظمت در برابر خدا سرِ تسلیم فرود آورده است، ولی انسان «نه» می‌گوید.\nشناخت خدا غیرممکن نیست و درعین‌حال واجب است؛ خدا را از طریق مخلوقات می‌توان شناخت.\nمهم‌ترین دلیلی که می‌توان بر وجود خدا اقامه کرد، برهان نظم است.\n«غَفَرَ اللّٰهُ لِی وَلَکمْ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِینَ»","بخش چهارم\nمتن:\nفَأَشْهَدُ أَنَّ مَنْ شَبَّهَكَ بِتَبَايُنِ أَعْضَاءِ خَلْقِكَ وَ تَلَاحُمِ حِقَاقِ مَفَاصِلِهِمُ الْمُحْتَجِبَةِ لِتَدْبِيرِ حِكْمَتِكَ، لَمْ يَعْقِدْ غَيْبَ ضَمِيرِهِ عَلَى مَعْرِفَتِكَ وَ لَمْ يُبَاشِرْ قَلْبَهُ الْيَقِينُ بِأَنَّهُ لَا نِدَّ لَكَ، وَ كَأَنَّهُ لَمْ يَسْمَعْ تَبَرُّؤَ التَّابِعِينَ مِنَ الْمَتْبُوعِينَ إِذْ يَقُولُونَ \"تَاللَّهِ إِنْ كُنَّا لَفِي ضَلالٍ مُبِينٍ إِذْ نُسَوِّيكُمْ بِرَبِّ الْعالَمِينَ\". كَذَبَ الْعَادِلُونَ بِكَ، إِذْ شَبَّهُوكَ بِأَصْنَامِهِمْ وَ نَحَلُوكَ حِلْيَةَ الْمَخْلُوقِينَ بِأَوْهَامِهِمْ وَ جَزَّءُوكَ تَجْزِئَةَ الْمُجَسَّمَاتِ بِخَوَاطِرِهِمْ وَ قَدَّرُوكَ عَلَى الْخِلْقَةِ الْمُخْتَلِفَةِ الْقُوَى بِقَرَائِحِ عُقُولِهِمْ. وَ أَشْهَدُ أَنَّ مَنْ سَاوَاكَ بِشَيْ‏ءٍ مِنْ خَلْقِكَ فَقَدْ عَدَلَ بِكَ وَ الْعَادِلُ بِكَ كَافِرٌ بِمَا تَنَزَّلَتْ بِهِ مُحْكَمَاتُ آيَاتِكَ وَ نَطَقَتْ عَنْهُ‏ شَوَاهِدُ حُجَجِ بَيِّنَاتِكَ؛ وَ إِنَّكَ أَنْتَ اللَّهُ الَّذِي لَمْ تَتَنَاهَ فِي الْعُقُولِ، فَتَكُونَ فِي مَهَبِّ فِكْرِهَا مُكَيَّفاً، وَ لَا فِي رَوِيَّاتِ خَوَاطِرِهَا فَتَكُونَ مَحْدُوداً مُصَرَّفاً.\nقَدَّرَ مَا خَلَقَ فَأَحْكَمَ تَقْدِيرَهُ، وَ دَبَّرَهُ فَأَلْطَفَ تَدْبِيرَهُ، وَ وَجَّهَهُ لِوِجْهَتِهِ فَلَمْ يَتَعَدَّ حُدُودَ مَنْزِلَتِهِ، وَ لَمْ يَقْصُرْ دُونَ الِانْتِهَاءِ إِلَى غَايَتِهِ، وَ لَمْ يَسْتَصْعِبْ إِذْ أُمِرَ بِالْمُضِيِّ عَلَى إِرَادَتِهِ، فَكَيْفَ وَ إِنَّمَا صَدَرَتِ الْأُمُورُ عَنْ مَشِيئَتِهِ الْمُنْشِئُ أَصْنَافَ الْأَشْيَاءِ بِلَا رَوِيَّةِ فِكْرٍ آلَ إِلَيْهَا وَ لَا قَرِيحَةِ غَرِيزَةٍ أَضْمَرَ عَلَيْهَا وَ لَا تَجْرِبَةٍ أَفَادَهَا مِنْ حَوَادِثِ الدُّهُورِ وَ لَا شَرِيكٍ أَعَانَهُ عَلَى ابْتِدَاعِ عَجَائِبِ الْأُمُورِ، فَتَمَّ خَلْقُهُ بِأَمْرِهِ وَ أَذْعَنَ لِطَاعَتِهِ وَ أَجَابَ إِلَى دَعْوَتِهِ لَمْ يَعْتَرِضْ دُونَهُ رَيْثُ الْمُبْطِئِ وَ لَا أَنَاةُ الْمُتَلَكِّئِ، فَأَقَامَ مِنَ الْأَشْيَاءِ أَوَدَهَا وَ نَهَجَ حُدُودَهَا وَ لَاءَمَ بِقُدْرَتِهِ بَيْنَ مُتَضَادِّهَا وَ وَصَلَ أَسْبَابَ قَرَائِنِهَا وَ فَرَّقَهَا أَجْنَاساً مُخْتَلِفَاتٍ فِي الْحُدُودِ وَ الْأَقْدَارِ وَ الْغَرَائِزِ وَ الْهَيْئَاتِ، بَدَايَا خَلَائِقَ أَحْكَمَ صُنْعَهَا وَ فَطَرَهَا عَلَى مَا أَرَادَ وَ ابْتَدَعَهَا.\nترجمه:\nمن گواهى مى دهم آن کس که تو را به مخلوقاتت تشبيه کرده و براى تو همانند آنها اعضاى مختلف و مفاصل به هم پيوسته - که به حکمتت در لابه لاى عضلات پنهان گشته اند - قائل شود، هرگز در اعماق ضمير خود تو را نشناخته و يقين به اين حقيقت، که براى تو شبيه و نظيرى نيست، در درون جانش قرار نگرفته است و گويا سخن تابعان را که از رهبران گمراه خود (در قيامت) بيزارى مى جويند نشنيده است! آن روز که مى گويند: «به خدا سوگند ما در گمراهى آشکار بوديم که شما را با پروردگار جهانيان برابر مى شمرديم». دروغ گفتند آنان که براى تو همتايى قائل شدند و تو را به بتهاى خود تشبيه نمودند و لباس و زينت مخلوقين را با اوهام و خيالات خود بر تو پوشانيدند و تو را همچون اجسام، با پندارهاى خود تجزيه کردند (و اجزايى همچون دست و پا، براى تو قائل شدند) و با سليقه هاى منحطّ خود، تو را به مخلوقى که قواى گوناگون دارد، مقايسه نمودند.\nو گواهى مى دهم آنانکه تو را با چيزى از مخلوقات مساوى شمردند همتايى براى تو قائل شده اند، و آن کس که براى تو همتايى قائل شود، نسبت به آنچه آيات محکمات تو آورده و شواهد «دلايل آشکار» تو از آن سخن مى گويد: کافر شده است! تو همان خدايى هستى که عقل ها به تو احاطه نمى يابد، تا در مسير وزش افکار در کيفيّت خاصى قرار گيرى! و در خاطره ها و انديشه ها جاى نمى گيرى، تا محدود و قابل تغيير باشى!\nآنچه را آفريده به درستى اندازه گيرى نموده، و به خوبى تدبير کرده، و در مسير خودش قرار داده است. لذا هيچ موجودى از حدّ خود تجاوز نکرده، و پيش از رسيدن به هدف، باز نمى ايستد، و به هنگامى که به آن فرمان داده شد، که مطابق اراده پروردگار حرکت کن سرپيچى ننمود; چگونه ممکن است سرپيچى کند، حال آنکه همه چيز از اراده او سرچشمه گرفته است؟!\nاو کسى است که موجودات مختلف را بدون نياز به تفکّر و انديشه اى که به دست آورده باشد و بدون غريزه اى که در درون نهان کند و بى نياز از تجربه حوادث زمان هاى گذشته، و بدون کمک شريک و همتايى که او را در آفرينش موجودات شگفت انگيز يارى دهد، آفريد. و اين سان آفرينش موجودات به فرمان او کامل شد، همه سر بر فرمانش نهادند و دعوتش را اجابت کردند، بى آن که در برابرش سستى کنند يا در اطاعت امرش درنگ نمايند; بدين گونه، موجودات را بى هيچ کژى برپا داشت و راهى را که بايد بپيمايند معيّن فرمود. با قدرت خويش در ميان اشياى متضاد الفت ايجاد کرد و آنها را که با يکديگر همگون بودند، پيوند داد، و موجودات جهان را به انواع مختلف از نظر حدود و اندازه ها، و غرايز و اَشکال و هيأت هاى گوناگون تقسيم نمود. اينها مخلوقات شگفت انگيزى است که آفرينش آنها را استوار نمود، و با حکمت قرين ساخت و آن سان که مى خواست ايجاد و ابداع فرمود.\nتفسیر:\n خطبهٔ اشباح\nدر بخش پیشین فرمود: حقیقت و انتهای کنه ذات خدا شناختنی نیست؛ برای شناخت باید به صفاتی که در زبان قرآن و اهل‌بیت (ع) آمده اکتفا کرد و خداوند را از طریق آثار صنعِ او شناخت؛ آنجا که می‌فرماید: «ظَهَرَ فِی الْبَدَائِعِ الَّتِی أَحْدَثَهَا آثَارُ صَنْعَتِهِ».\n«وَأَشْهَدُ أَنَّ مَنْ شَبَّهَک بِتَبَایُنِ أَعْضَاءِ خَلْقِک»\nشهادت می‌دهم که اگر کسی خدا را به مخلوقات تشبیه کند؛ مخلوقی که اعضای او از هم جداست [تباین]؛ دست، پا، گوش و قلب؛ هرکدام ویژگی، جایگاه خاص و کارکردی دارند. از صفاتِ مخلوق است که اعضای مختلف دارد.\nفرمود شناختِ اجمالیِ خدا هم حساب‌وکتاب دارد. اگر شناخت کلیِ خدا مقدور نیست، به معنای تعطیلیِ شناخت نیست؛ در وادی مشبهه گرفتار نشوید. خدا را با خود تشبیه نکنید؛ چون انسان علم دارد و خدا هم عالم است، پس شبیه به هم‌اند؟ هرگز این‌گونه تصور نکنید.\n«وَتَلَاحُمِ حِقَاقِ مَفَاصِلِهِمُ الْمُحْتَجِبَةِ لِتَدْبِیرِ حِکمَتِک»\nاگر خدا را تشبیه کند به کسی که اعضای مختلفِ او در نقاطِ اتصالِ مفصل [حِقاق] به‌هم‌چسبیده و متصل شده‌اند [تلاحم]؛ و مفاصلِ به‌هم‌پیوسته رها نیستند، بلکه در پوششی به نام پوست و گوشت در میان حجابی پوشیده شده‌اند؛ و آن‌هم از تدبیرِ حکمتِ خداوند است.\nانسان این‌گونه اجزا و بخش به بخش عضو دارد، خدا را این‌گونه تصور و تشبیه نکنید؛ چرا که اگر تشبیه شود و خدا جزء داشته باشد، محتاج است. هر کلی به اجزا احتیاج دارد و محتاجِ اجزای خود است؛ اما خدا محتاجِ گوش، دست و چشم نیست. خدا باید غنی بالذات باشد. چه تدبیری است که خدا انسان را این‌گونه خلق کرده؟ انسان یکپارچه و یک‌تکه نیست؛ بنا بر تدبیرِ خدا، هر جا که نیاز به تحرک بود مفصل قرارداد که در زیر لایه‌ای از گوشت همیشه مرطوب و نرم باشد و بتواند حرکت کند، و بیرون از گوشت، مفصل مانند چوبِ خشک شده، قادر به حرکت نیست. نگاه‌کردن به خلقتِ خود، دلیل بر وجود خداست. گوشت و پوستِ نرمِ قابل تحرک، می‌تواند یکی از دلایل خداشناسی باشد.\n«لَمْ یَعْقِدْ غَیْبَ ضَمِیرِهِ عَلَی مَعْرِفَتِک»\nاعتقاد پیدا نکرده است از درونِ خود به معرفتِ خدا؛ کسی که برای خدا چنین تصوری داشته باشد.\n«وَلَمْ یُبَاشِرْ قَلْبَهُ الْیَقِینُ بِأَنَّهُ لَا نِدَّ لَک»\nو قلبِ او همراه نشده با یقینی که به او بفهماند خدا نظیر و مانندی ندارد [لا نِدَّ]. اگر برای خدا اجزا تصور شود یا تشبیه گردد، لازمه‌اش چندخدایی است؛ دیگر تک خدایی در کار نیست.\n«وَکأَنَّهُ لَمْ یسْمَعْ تَبَرُّؤَ التَّابِعِینَ مِنَ الْمَتْبُوعِینَ إِذْ یقُولُونَ: تَاللَّهِ إِنْ کنَّا لَفِی ضَلَالٍ مُبِینٍ، إِذْ نُسَوِّیکم بِرَبِّ الْعَالَمِینَ»\nکسی که این‌گونه سخن بگوید، گویا نشنیده است برائت جستنِ گمراهان [تبرَّ التابع] از رهبرانِ خود که در قرآن ذکر آن آمده است. روز قیامت در محکمهٔ عدل الهی، گمراهانی که به تثلیثِ خدا قائل بودند، اقرار به گمراهیِ خود دارند، چون رؤسا برای آنان خدا را با مخلوق مساوی کرده و گمراهان هم پذیرفته بودند. (شعرا، ۹۸)\n«کذَبَ الْعَادِلُونَ بِک»\nدروغ گفته‌اند کسانی که برای خدا شبیه و نظیر قائل شدند. (عادل، عِدل، معادل و شبیه، از کلمهٔ عدل و عدالت نیست). احدی به خدا شباهت ندارد؛ او واجب‌الوجود است و ذاتِ او علم است. هرگز ارتباط و شباهت بین واجب‌الوجود و ممکن‌الوجود برقرار نیست.\n«إِذْ شَبَّهُوک بِأَصْنَامِهِمْ»\nاقسام مشبهه:\n۱. گروهی که خدا را به صنم‌های خود تشبیه می‌کنند؛ خدا را مساوی با بت‌هایشان می‌دانند.\n«وَنَحَلُوک حِلْیَةَ الْمَخْلُوقِینَ بِأَوْهَامِهِمْ»\n۲. گروهی که زینتِ مخلوق را با وهم و تخیلِ خود بر خدا پوشاندند [نحلو] و نسبت دادند. با وهم و فکرِ خود گفتند اگر انسان جوان باشد قدرتِ بیشتری دارد، پس خدا جوان است؛ انسان چشم درشت داشته باشد زینت است، پس خدا چشم درشت است؛ موی مجعد یک حُسن است، پس خدا موی مجعد دارد. این صفات برای انسان حُسن و زینت است، اما خدا از این صفات مبراست.\n«وَجَزَّؤُک تَجْزِئَةَ الْمُجَسَّمَاتِ بِخَوَاطِرِهِمْ»\n۳. گروه سومِ مشبهه، خدا را جزءجزء کردند؛ مانند جسمانیات؛ صاحبِ دست، گوش و چشم. با اوهام و پندارِ غلطِ خود خدا را جسمانی تصور کردند، وگرنه عقلِ سلیم برای خدا اجزا را نمی‌پذیرد.\n«وَقَدَّرُوک عَلَی الْخِلْقَةِ الْمُخْتَلِفَةِ الْقُوَی بِقَرَائِحِ عُقُولِهِمْ»\n۴. گروهی که تشبیه کردند خدا را با مخلوقاتی که صاحبِ قوای مختلف هستند؛ بینایی و شنوایی. خدا با این ابزار می‌بیند! گوش دارد پس می‌شنود! این‌ها هم با قریحهٔ عقلِ خود ادعا کرده و خدا را شناختند. انسان به این ابزار نیازمند است؛ اما خدا همهٔ وجودِ او سمع و همهٔ ذاتِ او علم است؛ نیاز به ابزار ندارد و جزء هم ندارد.\n«وَأَشْهَدُ أَنَّ مَنْ سَاوَاک بِشَیْءٍ مِنْ خَلْقِک فَقَدْ عَدَلَ بِک»\nشهادت می‌دهم اگر خدا را با یکی از مخلوقات مساوی شمارند [ساواک]، قطعاً برای خدا شریک قائل شدند [عِدل].\n«وَالْعَادِلُ بِک کافِرٌ بِمَا تَنَزَّلَتْ بِهِ مُحْکمَاتُ آیَاتِک»\nکسی که برای خدا عامداً و عالماً همتایی قائل شود کافر است؛ کفرِ او به‌خاطر آیاتِ محکمی است که در قرآن ذکر شده.\n«وَنَطَقَتْ عَنْهُ شَوَاهِدُ حُجَجِ بَیِّنَاتِک»\nو دلایلِ روشنِ قطعی و عقلی هم او را کافر می‌داند. وقتی همهٔ ادله بر توحید است، کدام عقل می‌پذیرد خدا همتا داشته باشد؟ هم عقل و هم شرع، برای خدا شریک قائل نیستند.\n«وَأَنَّک أَنْتَ اللَّهُ الَّذِی لَمْ تَتَنَاهَ فِی الْعُقُولِ فَتَکونَ فِی مَهَبِّ فِکرِهَا مُکیَّفاً»\n(مخاطبِ کلامِ حضرت، خداست)\nخدایا! تو همان کسی هستی که عقل‌ها بر تو احاطه نمی‌یابند [لم تتناه]. اگر انسان بر تو احاطه پیدا کند، برای تو کیفیت، حالات و شرایطِ مختلف قرار می‌دهد. این حالات برای تو نیست تا تو در محلِ وزشِ [مهب] فکرها واقع شوی و صاحبِ کیفیت گردی. درحالی‌که خدا کیفیت ندارد؛ ساعاتی خوش و خندان، ساعاتی افسرده و غصه‌ناک؛ صاحبِ کیفیات نیست که فکرها بوزد و برای تو کیفیت متصور بشود.\n«وَلَا فِی رَوِیَّاتِ خَوَاطِرِهَا فَتَکونَ مَحْدُوداً مُصَرَّفاً»\nخدایا! تو کسی هستی که خواطر، فکر و اندیشه‌ها بر تو احاطه پیدا نمی‌کند که اگر پیدا کند تو محدود می‌شوی.\nکیفیتِ خلقِ اشیا\nنمونه‌های بارز، ظهور و بروزِ خدا هستند.\n«قَدَّرَ مَا خَلَقَ فَأَحْکمَ تَقْدِیرَهُ»\nخدا تقدیر کرد آنچه را که خلق کرد.\nفرق قضاوقدر:\nقضا: به معنای خواستن؛ آنچه را که اراده کرده، مسجل و حتمی شده برای خلقِ مخلوق.\nقدَر: به معنای اندازه؛ مخلوقِ خلق‌شده، چقدر عمر کند، کجا زندگی کند، از چه پدر و مادری متولد شود و کِی بمیرد؛ تقدیرات و اندازهٔ او را همراه با خلق، معین کرده [احکم تقدیره].\n«وَدَبَّرَهُ فَأَلْطَفَ تَدْبِیرَهُ»\nمرحله بعد از خلق، تدبیر می‌کند. چگونه تقدیر راه بیندازد. خدا تدبیر می‌کند به هم رسیدن یک خانواده را و فرزندی که قرار است در آن خانه متولد شود.\n«وَوَجَّهَهُ لِوِجْهَتِهِ»\nخدا او را حرکت می‌دهد به سمت‌وسویی [وجهه] که خود اراده کرده بود. هیچ موجودی در عالم نیست که تقدیری داشته باشد و نشود. باید برود و به همان مسیر و سرانجامی که اراده کرده برسد [مرگ]. خدا قضا دارد و قدر، تقدیر دارد و تدبیر.\n«فَلَمْ یَتَعَدَّ حُدُودَ مَنْزِلَتِهِ وَلَمْ یَقْصُرْ دُونَ الِانْتِهَاءِ إِلَی غَایَتِهِ»\nهیچ‌کس از حد و جایگاهِ خود نتواند تعدی کند و هیچ‌کس نمی‌تواند کوتاهی کند [لم یقصر].\nمعنای جبرواختیار:\nجبر در مورد قوانین است که هیچ‌کس نمی‌تواند از قوانین سرپیچی کند، اما آنچه مربوط به عمل و شریعت است، جبر نیست. در تکوین، سراسر جبر است؛ کسی با اختیارِ خود به دنیا نیامده، کسی نمی‌تواند نمیرد. جبر در اصلِ خلقت است. خلق کرد که از فلان خانواده به دنیا آید، فلان مقدار عمر تقدیر کرد؛ همه جبر است. اما در کیفیت، هیچ جبری نیست. بین حیات تا ممات، جبر نیست. هر مکلفی هر عملی کند، اختیارِ مطلق است. در شریعت مختار است عمل کند یا نکند، تا زمانِ مرگ که مقدر شد؛ بر آن هم اختیاری ندارد و نخواهند، به‌اجبار می‌برند.\n«وَلَمْ یَسْتَعْصِبْ إِذْ أُمِرَ بِالْمُضِیِّ عَلَی إِرَادَتِهِ»\nسخت و دشوار نشود بر خدا [لم یستعصب] هنگامی‌که امر کرد: «کُنْ فَیَکُونُ»؛ کسی نمی‌تواند سرپیچی کند. حرکت ادامه دارد بر مسیری که مخلوقات را قرار داده. اگر خدا اراده کرد مخلوقی را در مسیری ببرد، کسی نمی‌تواند مقابلِ ارادهٔ خدا را بگیرد. (اصلِ خلق، جبر است).\n«وَکیْفَ وَإِنَّمَا صَدَرَتِ الْأُمُورُ عَنْ مَشِیَّتِهِ»\nچگونه ممکن است کسی سرپیچی کند از خدا، درحالی‌که همهٔ امور به مشیتِ او صادر شده؟\nجبرواختیار:\nمشیتِ خدا بر قوانینِ کلی هست که در جهان صادر می‌شود. خورشید و قمر باید در مدارِ خود با گردشِ خاص بچرخند؛ آبِ دریا در مواجهه با جزرومد باید به گونهٔ خاص باشد؛ درختان در زمستان به خواب و در بهار بیدار شوند. طبیعت خود تصمیم نمی‌گیرد؛ طبیعت خود مخلوق است. مشیتِ خدا قوانینِ طبیعی را در عالم وضع کرده. یکی از قوانینِ وضع‌شدهٔ خدا این است که: انسان باید اختیار داشته باشد. انسان نمی‌تواند مجبور باشد، چون خدا می‌خواهد که مختار باشد و در قبالِ اختیار، هر عملِ انجام‌شده را باید حساب پس بدهد. اصلِ اختیار هم جبر است و اینکه از اختیار چطور استفاده کنیم، به خودِ افراد بستگی دارد.\n«الْمُنْشِئُ أَصْنَافَ الْأَشْیَاءِ»\nخدا ایجاد کرد و اشیا را گروه‌گروه و اصناف قرارداد. گروه نباتات، گروه حجر، گروه شجر و هر گروه هم صنفی دارد؛ درختان گرمسیری، سردسیری، بلوط، میوه؛ هر کدام انواعی دارد.\n«بِلَا رَوِیَّةِ فِکرٍ آلَ إِلَیْهَا»\nهمهٔ اصناف و اشیا را در گروه‌های مختلف خلق کرد:\n۱. بدون فکر و تأمل، بدون رفت‌وبرگشت فکر [آلَ الیها]؛ حرکت بین فکر و تعمق و نادانی. اندیشهٔ انسان چگونه باشد بهتر است؟ اما برای خدا اراده است و اراده عینِ ذاتِ اوست، ذاتِ او علم است؛ اراده کند علم می‌جوشد. انسان بافکر و تأمل عمل می‌کند، گاهی اشتباه هم می‌شود.\n«وَلَا قَرِیحَةِ غَرِیزَةٍ أَضْمَرَ عَلَیْهَا»\n۲. بدون غریزه‌ای که در درون پنهان باشد. غریزه: قدرتِ همگانی که برای حفظِ بقا و حیات در همه هست. کبوتران برای حفظِ سرما و گرما لانه‌سازی دارند؛ انسان برای حفظِ جان در هنگامِ خطرِ چشمی، ناخودآگاه چشم می‌بندد یا در خطرِ جدی فرار می‌کند. عقل به تمامِ اعضا دستورِ همکاری و پمپاژِ قلب و تنفسِ شدید صادر می‌کند تا با غریزه، جان حفظ شود. اما خدا غریزه ندارد که از روی ترس برای حفظِ بقایِ خود، عالم را خلق کند.\n«وَلَا تَجْرِبَةٍ أَفَادَهَا مِنْ حَوَادِثِ الدُّهُورِ»\n۳. خلقِ عالم از روی تجربه نبود. تجربه یعنی ندانستن که گذرِ زمان آموخته می‌کند. شکست و تجربه، انسان را دوباره به پیروزی می‌رساند. تجربهٔ جدید، رشدِ امکاناتِ دنیوی دارد، اما برای خدا معنا ندارد. ازل و ابدِ خدا فرقی ندارد؛ علمِ ازل همان علمِ ابد است.\n«وَلَا شَرِیک أَعَانَهُ عَلَی ابْتِدَاعِ عَجَائِبِ الْأُمُورِ»\n۴. شریکی هم نداشته که برای خلقِ اعجاب‌انگیز، او را یاری کند. انسان بافکر، غریزه، تجربه و معاونت، عملی را انجام می‌دهد.\n«فَتَمَّ خَلْقُهُ بِأَمْرِهِ، وَأَذْعَنَ لِطَاعَتِهِ، وَأَجَابَ إِلَی دَعْوَتِهِ»\nکامل شد مخلوقات به اراده و امرِ او. همهٔ عالم به اطاعتِ او گردن نهادند [اذعن]؛ اقرار به اطاعت و دعوت را اجابت کردند.\n«لَمْ یَعْتَرِضْ دُونَهُ رَیْثُ الْمُبْطِئِ»\nهیچ مخلوقی در برابرِ خدا عرضِ اهمال‌کاری [ریث]، سستی، خستگی و کندی [مبطی] نکرد.\n«وَلَا أَنَاةُ الْمُتَلَکئِ»\nبه‌گونه‌ای خلق کرد که درنگ، تأمل و تأخیری در آن نبود. با یک امر خلق کرد و بدون کم‌وکاستی همه اطاعت کردند. در نظامِ تکوین این‌گونه است که هیچ‌کس نمی‌تواند «نه» بگوید. در نظامِ تشریع چون نظامِ اختیار است، یک انسان در مقابلِ خدا می‌تواند «نه» بگوید. (فصلت، ۱۱)\nخدا به خلقِ آسمان پرداخت درحالی‌که دود بود. بعد از خلق، به زمین و آسمان امر کرد آنچه بر شما امر شده انجام‌وظیفه کنید؛ گفتند: «أَتَیْنَا طَائِعِینَ»؛ نه‌فقط زمین و آسمان، بلکه تمامِ مخلوقات گوش‌به‌فرمانِ خدایند.\n«فَأَقَامَ مِنَ الْأَشْیَاءِ أَوَدَهَا، وَنَهَجَ حُدُودَهَا»\nخدا عالم را خلق کرد بدون کجی [اوَد] و حدومرز هر شیء را مشخص کرد.\n«وَلَاءَمَ بِقُدْرَتِهِ بَیْنَ مُتَضَادِّهَا»\nباقدرت خودبین دو متضاد را پیوند داد [لآم]؛ بین آب‌وآتش، بین بادوخاک، سرما و گرما. بقایِ نظام در کنارِ هم بودنِ همین تضادهاست.\n«وَوَصَلَ أَسْبَابَ قَرَائِنِهَا، وَفَرَّقَهَا أَجْنَاساً»\nاجزای قرین و همگون را به هم وصل کرد؛ آن‌هایی که در یک مرحله بالاتر، جنس بودند از هم جدا کرد. اشیا درعین‌حال که اتصال داشتند، متفاوت کرد؛ جنس و فصلِ انسان و حیوان را از هم متمایز کرد. جنسِ انسان و حیوان را با هم جمع کرد و با قوهٔ ناطقه [عقل و روح]، انسان را از حیوان جدا کرد.\n«مُتَخَلِّفَاتٍ فِی الْحُدُودِ وَالْأَقْدَارِ وَالْغَرَائِزِ وَالْهَیَآتِ»\nاشیایِ عالم را در اندازه‌های مختلف از هم جدا کرد؛ کوه‌ها با وزن‌های مختلف، طبع‌های مختلف [غرایز]، اشکالِ مختلف [هیآت]. اختلافِ هرکدام هم علتی دارد.\n«بَدَایَا خَلَائِقَ أَحْکمَ صُنْعَهَا، وَفَطَرَهَا عَلَی مَا أَرَادَ وَابْتَدَعَهَا»\nخدایا! تو موجودات را بدونِ نمونه خلق کردی. صنعِ تو محکم و بدونِ تجربه، نقص و کاستی هم نداشت؛ در بهترین ساخت خلق کردی [فطر] و بنا بر آنچه اراده کردی، خلقِ تو ابداع و اختراعی بود.\n«اللَّهُمَّ أَکرِمْنَا بِنُورِ الْإِیمَانِ»","بخش پنجم\nمتن:\nفي صفة السماء:\nوَ نَظَمَ بِلَا تَعْلِيقٍ رَهَوَاتِ فُرَجِهَا وَ لَاحَمَ صُدُوعَ انْفِرَاجِهَا، وَ وَشَّجَ بَيْنَهَا وَ بَيْنَ أَزْوَاجِهَا وَ ذَلَّلَ لِلْهَابِطِينَ بِأَمْرِهِ وَ الصَّاعِدِينَ بِأَعْمَالِ خَلْقِهِ حُزُونَةَ مِعْرَاجِهَا، وَ نَادَاهَا بَعْدَ إِذْ هِيَ دُخَانٌ فَالْتَحَمَتْ عُرَى أَشْرَاجِهَا، وَ فَتَقَ بَعْدَ الِارْتِتَاقِ صَوَامِتَ أَبْوَابِهَا، وَ أَقَامَ رَصَداً مِنَ الشُّهُبِ الثَّوَاقِبِ عَلَى نِقَابِهَا وَ أَمْسَكَهَا مِنْ أَنْ تُمُورَ فِي خَرْقِ الْهَوَاءِ بِأَيْدِهِ، وَ أَمَرَهَا أَنْ تَقِفَ مُسْتَسْلِمَةً لِأَمْرِهِ، وَ جَعَلَ شَمْسَهَا آيَةً مُبْصِرَةً لِنَهَارِهَا، وَ قَمَرَهَا آيَةً مَمْحُوَّةً مِنْ لَيْلِهَا، وَ أَجْرَاهُمَا فِي مَنَاقِلِ مَجْرَاهُمَا وَ قَدَّرَ سَيْرَهُمَا فِي مَدَارِجِ دَرَجِهِمَا لِيُمَيِّزَ بَيْنَ اللَّيْلِ وَ النَّهَارِ بِهِمَا وَ لِيُعْلَمَ عَدَدُ السِّنِينَ وَ الْحِسَابُ بِمَقَادِيرِهِمَا، ثُمَّ عَلَّقَ فِي جَوِّهَا فَلَكَهَا وَ نَاطَ بِهَا زِينَتَهَا مِنْ خَفِيَّاتِ دَرَارِيِّهَا وَ مَصَابِيحِ كَوَاكِبِهَا، وَ رَمَى مُسْتَرِقِي السَّمْعِ بِثَوَاقِبِ شُهُبِهَا، وَ أَجْرَاهَا عَلَى أَذْلَالِ تَسْخِيرِهَا مِنْ ثَبَاتِ ثَابِتِهَا وَ مَسِيرِ سَائِرِهَا وَ هُبُوطِهَا وَ صُعُودِهَا وَ نُحُوسِهَا وَ سُعُودِهَا.\nترجمه:\n(خداوند) فاصله هاى وسيع و گشوده (کرات آسمانى) را بى آنکه بر چيزى تکيه داشته باشند، تنظيم نمود و شکاف هاى ميان (هر کدام از آنها) را پيوند داد، آنها و نظائر آنها را به يکديگر مربوط ساخت، و مشکل فرود آمدن فرشتگان را براى ابلاغ فرمان او، و بالا بردن اعمال مخلوقات را به آسمان، آسان نمود. به آسمانها در حالى که به صورت دود بودند، فرمان داد (فرمانى تکوينى براى پيمودن مراحل خلقت و تکامل). در اين هنگام، ميان بخش هاى مختلفِ آن ارتباط برقرار گشت (و به صورت توده عظيمى درآمدند). سپس آسمانها را از هم جدا ساخت و درهاى بسته آنها را باز گشود، و نگهبانانى از شهاب هاى ثاقب بر هر راهى گماشت (تا مانع نفوذ شياطين به آسمانها گردد) و آنها را با دست قدرتش بى آن که گرفتار حرکات ناموزون گردند (در فضا) نگاهداشت و به آنها فرمان داد که تسليم امر او بوده باشند (و از قوانين آفرينش پيروى کنند).\nخداوند خورشيد را نشانه روشنى بخش روز، و ماه را نورى محو و کم رنگ براى (زدودن شدّت تيرگى) شب ها قرار داد و آنها را در مسيرهايشان به حرکت درآورد; و مقدار سير آنها را در مراحلى که بايد بپيمايند معيّن فرمود، تا شب و روز را بدين وسيله از هم جدا سازد و عدد سال ها و زمان معلوم گردد. سپس در فضاى آسمان ها، فلک ها (مدارات کواکب) را آفريد، و آنچه زينت بخش آن بود از ستارگان مخفى و کم نور و ستارگان پر نور در آن جايگزين ساخت، و استراق سمع کنندگان را با شهاب هاى ثاقب تير باران نمود، و همه آسمانها را به تسخير خود درآورد، و ستارگان ثوابت و سيّار و هبوط کننده و صعود کننده و نحس و سعد آنها را به جريان انداخت.\nتفسیر:\n خطبهٔ اشباح؛ خلقت آسمان\n«وَنَظَمَ بِلَا تَعْلِیقٍ رَهَوَاتِ فُرَجِهَا، وَلَاحَمَ صُدُوعَ انْفِرَاجِهَا»\nفضای باز، پستی‌وبلندی و فاصله‌های وسیع آسمان‌ها را، بدون این‌که بر چیزی تکیه کند، نظام بخشید و شکاف‌های آن را به هم آورد.\nدر آسمان‌ها چه خبر است؟\nبرای خداشناسی به آسمان نگاه کنید؛ نگاه به آسمان، نگاه به عظمت خدای متعال است. خداوند فرازوفرود و وسعت آسمان را نظم بخشید و قدرتی را خلق کرد تا ستون باشد و آسمان‌ها را نگه دارد. البته این فرازوفرود و وسعت، دیدنی نیست. خدای متعال شکاف‌ها و گسستگی‌ها را به هم پیوند داد.\nهر کره و هر کهکشان را از دیگری جدا کرد و درعین‌حال که از یکدیگر جدا هستند، مجموعه‌ها را به هم پیوند داد.\n«وَوَشَّجَ بَیْنَهَا وَبَیْنَ أَزْوَاجِهَا»\nو هر یک را با آنچه تناسب داشت و جفت آن بود، پیوند داد.\nخدای متعال با ایجاد شبکه‌ای میان قطعاتی که مثل و مانند یکدیگر بودند، ارتباط برقرار کرد؛ شبکه‌ای درهم‌تنیده در آسمان که پیرامون خورشید شکل‌گرفته است. درعین‌حال که این اجزا از یکدیگر جدا هستند، با هم و در یک مجموعه قرار دارند. فعل‌وانفعالات، انفجارها و طوفان‌های خورشیدی بر اجرام دیگر تأثیر می‌گذارند؛ اما خدای متعال سپری پیرامون زمین قرار داده است تا به زمینیان آسیبی نرسد.\n«وَذَلَّلَ لِلْهَابِطِینَ بِأَمْرِهِ، وَالصَّاعِدِینَ بِأَعْمَالِ خَلْقِهِ، حُزُونَةَ مِعْرَاجِهَا»\nو دشواری فرودآمدن و برخاستن را بر فرشتگانی که فرمان او را به خلق می‌رسانند یا اعمال بندگان را بالا می‌برند، آسان کرد.\nخدای متعال برای ملائکه‌ای که قرار است از آسمان فرود آیند تا امر و دستور خدا را امتثال کنند، این مسیر را آسان کرد. همچنین برای آن دسته از ملائکه‌ای که روی زمین هستند و می‌خواهند به بالا صعود کنند، دشواری راه را برطرف ساخت. این ملائکه، با این‌که راهی طولانی و سخت دارند، در چشم برهم‌زدنی می‌روند و بازمی‌گردند.\n«وَنَادَاهَا بَعْدَ إِذْ هِیَ دُخَانٌ»\nدرحالی‌که آسمان به‌صورت دود و بخار بود، آن را ندا داد و به آن فرمان داد.\nحضرت در خطبهٔ اول، در بیان کیفیت خلقت آسمان، به‌خوبی به این موضوع پرداخته‌اند.\n«فَالْتَحَمَتْ عُرَی أَشْرَاجِهَا»\nپس پیوندهای آن را برقرار ساخت.\nخدای متعال به آسمان دستور داد که خلل‌ها و شکاف‌هایی که میان آسمان وجود دارد، از بین برود.\n«وَفَتَقَ بَعْدَ الِارْتِتَاقِ صَوَامِتَ أَبْوَابِهَا»\nسپس آن‌ها را از یکدیگر جدا کرد و میانشان فاصله انداخت.\nاین جمله به تشکیل آسمان‌های مختلف اشاره دارد. خدای متعال دستور داد که آسمان‌ها از یکدیگر جدا و طبقه‌طبقه شوند.\n«وَأَقَامَ رَصَداً مِنَ الشُّهُبِ الثَّوَاقِبِ عَلَی نِقَابِهَا»\nو بر هر راه و شکافی از آسمان، نگهبانی از شهاب‌های روشن گماشت.\nخدای متعال پس از خلقت آسمان، نگهبانانی برپا کرد که سلاحشان شهاب‌های نورانی بود. این فراز به چند آیه از قرآن کریم اشاره دارد.\nدر آسمان خبرهایی وجود دارد که مربوط به آینده است. شیاطینِ کافر به دنبال کسب خبر و اطلاع از آینده و رساندن آن به سلاطین جور هستند. خدای متعال هنگامی که راه را برای ملائکه آسان کرد، برای جلوگیری از رفت‌وآمد شیاطین، نگهبانانی از شهاب‌های ثاقب قرارداد.\n«وَحَفِظْنَاهَا مِنْ کلِّ شَیْطَانٍ رَجِیمٍ، إِلَّا مَنِ اسْتَرَقَ السَّمْعَ فَأَتْبَعَهُ شِهَابٌ مُبِینٌ، حِجْرٌ - ۱۸»\nآن را از دستبرد شیاطین حفظ کردیم. هر شیطانی که برای استراق سمع به آسمان نزدیک شود، شهابی شعله‌ور او را تعقیب می‌کند.\n«إِلَّا مَنْ خَطِفَ الْخَطْفَةَ فَأَتْبَعَهُ شِهَابٌ ثَاقِبٌ، صَافَّاتٌ - ۱۰»\nدر مورد واژهٔ «شهاب ثاقب» اختلاف‌نظر وجود دارد.\nبرخی شهاب ثاقب را تیری از تیرهای غیبی می‌دانند.\nگروهی دیگر، شهاب ثاقب را کنایه‌ای از عالم نورانیت و ملکوت می‌دانند؛ عالمی که شیاطین در نور و روشنایی آن کور و نابینا می‌شوند.\n«وَأَمْسَکَهَا مِنْ أَنْ تَمُورَ فِی خَرْقِ الْهَوَاءِ بِأَیْدِیهِ»\nو باقدرت خود، آن‌ها را از حرکت‌های ناموزون در فضا نگه داشت.\nخدای متعال با دست قدرت خود، آسمان‌ها را از حرکت‌های شدیدی که در عالم وجود دارد، حفظ کرد. آن‌سوی جوّ زمین، موج‌های سهمگینی وجود دارد؛ بااین‌حال، همهٔ کرات و اجرام آسمانی، بدون لحظه‌ای توقف، باکمال دقت در مدار خود حرکت می‌کنند. خداوند باقدرت خود این آرامش و سکون را به آن‌ها داد تا در میان آن امواج سهمگین و ارتعاشات، خود را حفظ کنند.\n«وَأَمَرَهَا أَنْ تَقِفَ مُسْتَسْلِمَةً لِأَمْرِهِ»\nو دستور داد تا در برابر فرمان او تسلیم باشند.\nخدای متعال اراده کرد تا آسمان‌ها بایستند و تسلیم ارادهٔ او شوند. هرچه را خدا می‌گوید اطاعت کنند؛ آسمان‌ها نیز پذیرفتند.\nحرکت خورشید، زمین و ستارگان و تغییر روز، ماه، سال و فصل‌ها، همگی به امر خدای متعال است.\n«وَجَعَلَ شَمْسَهَا آیَةً مُبْصِرَةً لِنَهَارِهَا»\nو خورشید را نشانه‌ای روشنی‌بخش برای روز آن قرارداد.\n«وَقَمَرَهَا آیَةً مَمْحُوَّةً مِنْ لَیْلِهَا»\nو ماه را با نوری کم‌رنگ برای تاریکی شب‌های آن قرارداد.\nخداوند برای شب، تاریکی محض را انتخاب نکرد؛ زیرا ظلمت محض موجب ترس بندگان می‌شود. ازاین‌رو ماه را نشانه و آیتی قرارداد تا فضای زمین تااندازه‌ای روشن باشد؛ زیرا شب برای استراحت و آرامش است.\n«وَأَجْرَاهُمَا فِی مَنَاقِلِ مَجْرَاهُمَا»\nو آن دو را در مسیر حرکت خویش به حرکت درآورد.\nخدای متعال خورشید و ماه را در مسیر خودشان قرارداد و به آن‌ها امر کرد که چه مقدار حرکت کنند و چگونه به حرکت خود ادامه دهند. میزان و چگونگی حرکت آن‌ها مشخص شده و به آن‌ها فرمان داده شده است.\n«وَالشَّمْسُ تَجْرِی لِمُسْتَقَرٍّ لَهَا، ذَلِک تَقْدِیرُ الْعَزِیزِ الْعَلِیمِ، وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّی عَادَ کالْعُرْجُونِ الْقَدِیمِ، یَس - ۲۹»\n«وَقَدَّرَ سَیْرَهُمَا فِی مَدَارِجِ دَرَجِهِمَا»\nو حرکت آن دو را به‌دقت اندازه‌گیری کرد تا در درجات تعیین‌شده حرکت کنند.\n«لِیُمَیِّزَ بَیْنَ اللَّیْلِ وَالنَّهَارِ بِهِمَا»\nهدف این بود که به‌وسیلهٔ آن دو، میان شب‌وروز تفاوت باشد و شما شب‌وروز را بشناسید.\n«وَلِیُعْلَمَ عَدَدُ السِّنِینَ وَالْحِسَابُ بِمَقَادِیرِهِمَا»\nو با رفت‌وآمد آن‌ها، شمارش سال‌ها و اندازه‌گیری زمان ممکن باشد.\n«ثُمَّ عَلَّقَ فِی جَوِّهَا فَلَکَهَا»\nسپس در فضای هر آسمان، فلک آن را آفرید.\nخدای متعال هنگامی که آسمان را خلق کرد، فلک را نیز آفرید. فلک، خطی فرضی است که هرکدام از این سیارات بر روی آن حرکت می‌کنند. خدای متعال این خط را ترسیم کرد و مسیر حرکت اجرام آسمانی را بر روی آن مشخص ساخت.\n«وَنَاطَ بِهَا زِینَتَهَا مِنْ خَفِیَّاتِ دَرَارِیِّهَا وَمَصَابِیحِ کوَاکبِهَا»\nو آسمان را با زینتی از گوهرهای تابنده و ستارگان درخشان آراست.\nخداوند ستاره‌های پرنور و کم‌نور را آفرید. البته ستاره‌های کوچک و کم‌نور از دید ما چنین به نظر می‌رسند؛ زیرا بسیار از ما دور هستند.\n«وَرَمَی مُسْتَرِقِی السَّمْعِ بِثَوَاقِبِ شُهُبِهَا»\nو کسانی را که می‌خواستند اسرار آسمان‌ها را دزدانه سرقت کنند، با شهاب‌های سوزان تیرباران کرد.\nدر آسمان‌ها خبرهایی وجود دارد و عده‌ای می‌خواهند استراق سمع کنند و از سخنان غیبی آگاه شوند. خداوند آن‌ها را با شهاب ثاقب تیرباران کرد.\n«وَأَجْرَاهَا عَلَی أَذْلَالِ تَسْخِیرِهَا مِنْ ثَبَاتِ ثَابِتِهَا وَمَسِیرِ سَائِرِهَا»\nو همهٔ ستارگان، اعم از ثابت، استوار، گردنده و بی‌قرار را تسلیم فرمان خود کرد.\nخدای متعال آسمان‌ها را بر راهی هموار به حرکت درآورد؛ راهی که همهٔ آن‌ها در آن مسخّر خدای متعال هستند. خداوند آسمان‌ها را خلق کرد و آسمان در پنجهٔ تسخیر اوست. همهٔ این ستاره‌ها، آسمان‌ها و اجرام آسمانی، تحت تصرف خداوند هستند.\nدر این آسمان، انواع‌واقسام سیاره‌ها و ستاره‌ها وجود دارند؛ برخی ثابت هستند و حرکت نمی‌کنند. البته در مقایسه با زمین ثابت به نظر می‌رسند و حرکتشان به‌اندازه‌ای کم است که ما آن را احساس نمی‌کنیم. دسته‌ای دیگر نیز در مسیر خود هستند و پیوسته حرکت می‌کنند؛ مانند حرکت وضعی و حرکت انتقالی.\n«وَهُبُوطِهَا وَصُعُودِهَا»\nو فرودآمدن و بالارفتن آن‌ها.\nستارگانی که فرود می‌آیند و ستارگانی که بالا می‌روند.\nخورشید در پایان زمستان شروع به صعود می‌کند و تا ابتدای تابستان به اوج می‌رسد. در بالاترین قسمت، مستقیم بر زمین می‌تابد؛ ازاین‌رو گرما افزایش می‌یابد.\nپس از گذشت تابستان، خورشید شروع به هبوط می‌کند و تا زمستان به نهایت فرود خود می‌رسد.\nهرکدام از ستارگان در شرایط خاص، حرکت روبه‌بالا و روبه‌پایین دارند؛ اما مدار خود را تغییر نمی‌دهند. اوج، فرازوفرود آن‌ها تغییر می‌کند.\nهمهٔ این حرکت‌ها برای انسان، حفظ نظام طبیعت و دیگر موجودات - که شاید در کرات دیگر نیز وجود داشته باشند و ما از آن‌ها خبر نداشته باشیم - قرار داده شده است. هیچ‌کدام از این حرکت‌ها به‌صورت مستقل در اختیار خودِ موجودات یا طبیعت نیست؛ بلکه خداوند این قوانین را بر آن‌ها جاری کرده است.\n«وَنُحُوسِهَا وَسُعُودِهَا»\nو نحوست و سعادت آن‌ها.\nستارگانی که نحوست و سعادت دارند، تسخیرشان در اختیار خدای متعال است.\nمخالفت انبیا با مردم بر سر اعمال، اخلاق و برخی اعتقادات بوده است. یکی از باورها و عقاید منحط، اعتقاد به نحس بودن ستاره‌هاست؛ این‌که ستارگان بر زندگی بشر تأثیر می‌گذارند.\nبرخی معتقدند هرکس در آسمان، ستارهٔ خوشبختی و بدبختی دارد. بحث مفصلی دربارهٔ ستارگان در خطبهٔ ۷۹ آمده است.\nسؤال:\nآیا باید به‌ظاهر این کلام اکتفا کنیم که ستاره‌ها نحس و سعد هستند؟\nآیا ستاره می‌تواند در زندگی فرد اثر بگذارد و او را بدبخت کند؟\nپاسخ:\nنخست این‌که نحس بودن، منحصر به آسمان نیست و به زمین نیز مربوط می‌شود.\nفلان روز مبارک و فلان روز نحس، به چه معناست؟\nنکتهٔ اول:\nاگر روزی نحس نامیده می‌شود، به‌خاطر اتفاق بدی است که در آن روز رخ‌داده است.\n«إِنَّا أَرْسَلْنَا عَلَیْهِمْ رِیحاً صَرْصَراً فِی یَوْمِ نَحْسٍ مُسْتَمِرٍّ»\nنحس بودن روز، به سبب عذابی است که بر قوم عاد نازل شده است؛ اما همان روز برای گروه مؤمنان، مبارک و مایهٔ شادمانی است.\nمبارک بودن روز نیز در این آیه بیان شده است:\n«إِنَّا أَنْزَلْنَاهُ فِی لَیْلَةٍ مُبَارَکةٍ»\nمبارک بودن شب، به سبب نزول قرآن در آن است.\nروز غدیر نیز به سبب ولایت علی بن ابی‌طالب مبارک است.\nاتفاق مهم است، نه تاریخ و روز؛ این اتفاق است که به تاریخ جایگاه و ارزش می‌دهد.\nاگر منظور از روز و ستاره این باشد که به‌صورت مستقل تأثیر می‌گذارند، این اعتقاد شرک است.\nبه قول علامهٔ طباطبایی:\nبه‌هیچ‌وجه امکان اقامهٔ دلیل عقلی بر نحس و سعد بودن روزگار وجود ندارد.\nهیچ دلیلی وجود ندارد که یک روز یا ستاره خوب و روز یا ستاره‌ای دیگر بد باشد. هر ستاره مخلوق خداست و از خود اختیاری ندارد.\nستارگان مانند اشخاص نیستند که بر اثر اطاعت و نافرمانی، حالات متفاوتی پیدا کنند.\nاگر قائل به وجود ستارهٔ نحس باشیم، در واقع باید بپذیریم که خداوند موجودی شر آفریده است؛ درحالی‌که از خدایی که همهٔ خیر است، ظلم و شر صادر نمی‌شود.\nنحس ذاتی وجود ندارد و نحسی به سبب نزول عذاب بر دشمنان است.\nنکتهٔ دوم:\nدربارهٔ نحس و سعد بودن ستارگان، در روایتی آمده است که امام صادق علیه‌السلام به مفضّل بن عمر فرمود:\nستارگان بر مزاج انسان تأثیر می‌گذارند.\nستاره موجب خوشبختی و بدبختی نمی‌شود؛ بلکه تأثیرات طبیعی دارد که بر مزاج اثر می‌گذارد.\nبرای نمونه، غذایی ممکن است در آغاز ماه تأثیری داشته باشد که در میانهٔ ماه همان تأثیر را نداشته باشد؛ بنابراین این‌که گفته شود ستارهٔ بخت ما شوم بوده، سخن نادرستی است.\nهمان‌گونه که ماه بر دریا تأثیر می‌گذارد و موجب جزرومد می‌شود، آب دریا نیز با حجم و وزن سنگین خود، تحت‌تأثیر قرار می‌گیرد و بالا و پایین می‌رود.\nاگر نحس و سعد بودن ستاره به این معنا باشد، درست است. ستارگان بر انسان و انسان نیز بر محیط و طبیعت اثر می‌گذارد.\nهمان‌طور که جزرومد بر دریا تأثیر دارد، بر انسان نیز اثر می‌گذارد. باید خود را با عالم و طبیعت هماهنگ کنیم.\nهمان دستورات طبیعی و پزشکی در باب عقد و نکاح و انعقاد نطفه نیز مطرح است. قرارگرفتن قمردرعقرب، در کارهای مهم و عقد، کراهت دارد؛ زیرا دارای تأثیر طبیعی است.\nاین تأثیر، طبیعی است، نه تکوینی.\nاگر ستاره بتواند به‌صورت مستقل حال انسان را خوب یا بد کند و عقد و ازدواج را خوب یا بد سازد، اعتقاد به چنین چیزی شرک است؛ زیرا نادیده‌گرفتن تأثیر خداوند است.\nخداوند به ستاره قدرت داده است که در برخورد با ستاره‌ای دیگر، قمردرعقرب قرار بگیرد و این وضعیت نیز آثار خاص خود را داشته باشد.\nاگر در شرایط خاص، عقب انداختن یا جلو انداختن عقد ممکن نباشد، با دادن صدقه می‌توان ضرر را دفع کرد.\nاین مسئله محدودیت و محصوریت مطلق ندارد؛ می‌توان با صدقه، حرکت را به سمت خیر و گشایش پیش برد.\nآسمان برنامه‌ای دقیق و مشخص دارد؛ خود را با قوانین آن هماهنگ کنید.\nچون در برابر قوانین الهی توان ایستادگی نداریم، خود را با آن‌ها تطبیق دهید تا در امان بمانید.\nنحس بودن ستاره به این معنا نیست که خودِ ستاره نحس است؛ بلکه قانون طبیعت است که خداوند بر آن جاری کرده و اثر خود را می‌گذارد.\n«اللَّهُمَّ أَخْرِجْنَا مِنْ ظُلُمَاتِ الْوَهْمِ»","بخش ششم\nمتن:\nفي صفة الملائكة:\nثُمَّ خَلَقَ سُبْحَانَهُ لِإِسْكَانِ سَمَاوَاتِهِ وَ عِمَارَةِ الصَّفِيحِ الْأَعْلَى مِنْ مَلَكُوتِهِ خَلْقاً بَدِيعاً مِنْ مَلَائِكَتِهِ وَ مَلَأَ بِهِمْ فُرُوجَ فِجَاجِهَا وَ حَشَا بِهِمْ فُتُوقَ أَجْوَائِهَا، وَ بَيْنَ فَجَوَاتِ تِلْكَ الْفُرُوجِ زَجَلُ الْمُسَبِّحِينَ مِنْهُمْ فِي حَظَائِرِ الْقُدُسِ وَ سُتُرَاتِ الْحُجُبِ‏ وَ سُرَادِقَاتِ الْمَجْدِ، وَ وَرَاءَ ذَلِكَ الرَّجِيجِ الَّذِي تَسْتَكُّ مِنْهُ الْأَسْمَاعُ سُبُحَاتُ نُورٍ تَرْدَعُ الْأَبْصَارَ عَنْ بُلُوغِهَا فَتَقِفُ خَاسِئَةً عَلَى حُدُودِهَا، وَ أَنْشَأَهُمْ عَلَى صُوَرٍ مُخْتَلِفَاتٍ وَ أَقْدَارٍ مُتَفَاوِتَاتٍ \"أُولِي أَجْنِحَةٍ\" تُسَبِّحُ جَلَالَ عِزَّتِهِ لَا يَنْتَحِلُونَ مَا ظَهَرَ فِي الْخَلْقِ مِنْ صُنْعِهِ وَ لَا يَدَّعُونَ أَنَّهُمْ يَخْلُقُونَ شَيْئاً مَعَهُ مِمَّا انْفَرَدَ بِهِ \"بَلْ عِبادٌ مُكْرَمُونَ لا يَسْبِقُونَهُ بِالْقَوْلِ وَ هُمْ بِأَمْرِهِ يَعْمَلُونَ\"، جَعَلَهُمُ اللَّهُ فِيمَا هُنَالِكَ أَهْلَ الْأَمَانَةِ عَلَى وَحْيِهِ، وَ حَمَّلَهُمْ إِلَى الْمُرْسَلِينَ وَدَائِعَ أَمْرِهِ وَ نَهْيِهِ، وَ عَصَمَهُمْ مِنْ رَيْبِ الشُّبُهَاتِ فَمَا مِنْهُمْ زَائِغٌ عَنْ سَبِيلِ مَرْضَاتِهِ، وَ أَمَدَّهُمْ بِفَوَائِدِ الْمَعُونَةِ، وَ أَشْعَرَ قُلُوبَهُمْ تَوَاضُعَ إِخْبَاتِ السَّكِينَةِ، وَ فَتَحَ لَهُمْ أَبْوَاباً ذُلُلًا إِلَى تَمَاجِيدِهِ، وَ نَصَبَ لَهُمْ مَنَاراً وَاضِحَةً عَلَى أَعْلَامِ تَوْحِيدِهِ.\nلَمْ تُثْقِلْهُمْ مُؤْصِرَاتُ الْآثَامِ، وَ لَمْ تَرْتَحِلْهُمْ عُقَبُ اللَّيَالِي وَ الْأَيَّامِ، وَ لَمْ تَرْمِ الشُّكُوكُ بِنَوَازِعِهَا عَزِيمَةَ إِيمَانِهِمْ، وَ لَمْ تَعْتَرِكِ الظُّنُونُ عَلَى مَعَاقِدِ يَقِينِهِمْ، وَ لَا قَدَحَتْ قَادِحَةُ الْإِحَنِ فِيمَا بَيْنَهُمْ، وَ لَا سَلَبَتْهُمُ الْحَيْرَةُ مَا لَاقَ مِنْ مَعْرِفَتِهِ بِضَمَائِرِهِمْ، وَ مَا سَكَنَ مِنْ عَظَمَتِهِ وَ هَيْبَةِ جَلَالَتِهِ فِي أَثْنَاءِ صُدُورِهِمْ، وَ لَمْ تَطْمَعْ فِيهِمُ الْوَسَاوِسُ فَتَقْتَرِعَ بِرَيْنِهَا عَلَى فِكْرِهِمْ\nترجمه:\nسپس خداوند سبحان براى سکونت در آسمانها و آباد ساختن آنها (با عبادت و نيايش) در بالاترين صفحه ملکوت خود، مخلوقاتى بديع از فرشتگان آفريد; تمام فواصل آسمان را با آنها پر کرد و فضاى ميان آن را از وجود فرشتگان، مالامال ساخت. (به گونه اى که) صداى تسبيح آنها، فاصله هاى آسمانها را پر کرده و در بارگاه قدس و درون حجابها و سراپرده هاى مجد و عظمت، طنين انداز است، و در ماوراى زلزله و غوغاى تسبيح آنان - که گوشها از آن کر مى شود - شعاع هاى خيره کننده نور، چشمها را از ديدن باز مى دارد و در محدوده خود متوقّف مى سازد.\nآنها را به صورتهاى مختلف و اندازه هاى گوناگون آفريد، «در حالى که داراى بالهاى متعددى هستند» (و از نظر قدرت، يکسان نمى باشند). همواره تسبيح جلال و عزّت او مى گويند و هرگز اسرار شگفت انگيز آفرينش مخلوقات را به خود نسبت نمى دهند و ادّعا نمى کنند که در آفرينش چيزى با او شرکت دارند، «بلکه آنها بندگان گرامى او هستند که هيچ گاه در سخن بر او پيشى نمى گيرند و به فرمان او (بى هيچ کم و کاست) عمل مى کنند».\nگروهى از آنها را امين وحى خود قرار داد، و به آنها براى رساندن ودايع امر و نهيش به پيامبران مأموريت داد، و از ترديد و شبهات مصونيّت بخشيد، به گونه اى که هيچ کدام از آنان از راه رضاى حقّ منحرف نمى شوند. آنان را از يارى خويش بهره مند ساخت (تا وظيفه ابلاغ وحى را به خوبى انجام دهند) و قلب آنان را با تواضع و خشوع و سکينه و آرامش قرين نمود (تا در انجام اين وظيفه خطير گرفتار خطا نشوند) و درهاى سهل و آسانى را براى مدح و تمجيد (و نيايش) خويش به روى آنها گشود (تا از اين طريق مصونيّت بيشترى به آنها ببخشد) و چراغ هاى روشنى جهت راهيابى به نشانه هاى توحيدش براى آنان نصب نمود.\nسنگينى گناهان هرگز فرشتگان را ناتوان و درمانده نساخته (چرا که آنها هرگز گناه نمى کنند.) و رفت و آمد شب و روز آنان را به سوى مرگ کوچ نداده است (تا ضعف و پيرى بر آنها چيره شود.) تيرهاى شک و شبهه، ايمان پر عزم آنان را هدف قرار نداده، و گمان و ترديد بر پايگاه يقين آنان راه نيافته (و آنها را متزلزل نساخته است). هيچ چيز آتش کينه و حسد را در ميان آنها بر نيافروخته (تا ضعف و فتورى در کار آنها راه يابد.) و هرگز حيرت و سرگردانى آنان را از معرفتى که در باطن دارند و آنچه از عظمت و هيبت و جلال الهى در درون سينه هايشان نهفته است، جدا نساخته، و (سرانجام) وسوسه ها در وجودشان راه نيافته، تا شک و ترديد ناشى از آن بر افکارشان چيره شود.\nتفسیر:","بخش هفتم\nمتن:\nوَ مِنْهُمْ مَنْ هُوَ فِي خَلْقِ الْغَمَامِ‏ الدُّلَّحِ وَ فِي عِظَمِ الْجِبَالِ الشُّمَّخِ وَ فِي قَتْرَةِ الظَّلَامِ الْأَيْهَمِ، وَ مِنْهُمْ مَنْ قَدْ خَرَقَتْ أَقْدَامُهُمْ تُخُومَ الْأَرْضِ السُّفْلَى فَهِيَ كَرَايَاتٍ بِيضٍ قَدْ نَفَذَتْ فِي مَخَارِقِ الْهَوَاءِ وَ تَحْتَهَا رِيحٌ هَفَّافَةٌ تَحْبِسُهَا عَلَى حَيْثُ انْتَهَتْ مِنَ الْحُدُودِ الْمُتَنَاهِيَةِ.\nقَدِ اسْتَفْرَغَتْهُمْ أَشْغَالُ عِبَادَتِهِ وَ [وَصَّلَتْ‏] وَصَلَتْ حَقَائِقُ الْإِيمَانِ بَيْنَهُمْ وَ بَيْنَ مَعْرِفَتِهِ وَ قَطَعَهُمُ الْإِيقَانُ بِهِ إِلَى الْوَلَهِ إِلَيْهِ وَ لَمْ تُجَاوِزْ رَغَبَاتُهُمْ مَا عِنْدَهُ إِلَى مَا عِنْدَ غَيْرِهِ قَدْ ذَاقُوا حَلَاوَةَ مَعْرِفَتِهِ وَ شَرِبُوا بِالْكَأْسِ الرَّوِيَّةِ مِنْ مَحَبَّتِهِ وَ تَمَكَّنَتْ مِنْ [سُوَيْدَاوَاتِ‏] سُوَيْدَاءِ قُلُوبِهِمْ وَشِيجَةُ خِيفَتِهِ فَحَنَوْا بِطُولِ الطَّاعَةِ اعْتِدَالَ ظُهُورِهِمْ وَ لَمْ يُنْفِدْ طُولُ الرَّغْبَةِ إِلَيْهِ مَادَّةَ تَضَرُّعِهِمْ وَ لَا أَطْلَقَ عَنْهُمْ عَظِيمُ الزُّلْفَةِ رِبَقَ خُشُوعِهِمْ وَ لَمْ يَتَوَلَّهُمُ الْإِعْجَابُ فَيَسْتَكْثِرُوا مَا سَلَفَ مِنْهُمْ وَ لَا تَرَكَتْ لَهُمُ اسْتِكَانَةُ الْإِجْلَالِ نَصِيباً فِي تَعْظِيمِ حَسَنَاتِهِمْ وَ لَمْ تَجْرِ الْفَتَرَاتُ فِيهِمْ عَلَى طُولِ دُءُوبِهِمْ وَ لَمْ تَغِضْ رَغَبَاتُهُمْ فَيُخَالِفُوا عَنْ رَجَاءِ رَبِّهِمْ وَ لَمْ تَجِفَّ لِطُولِ الْمُنَاجَاةِ أَسَلَاتُ أَلْسِنَتِهِمْ وَ لَا مَلَكَتْهُمُ الْأَشْغَالُ فَتَنْقَطِعَ بِهَمْسِ الْجُؤَارِ إِلَيْهِ أَصْوَاتُهُمْ وَ لَمْ تَخْتَلِفْ فِي مَقَاوِمِ الطَّاعَةِ مَنَاكِبُهُمْ وَ لَمْ يَثْنُوا إِلَى رَاحَةِ التَّقْصِيرِ فِي أَمْرِهِ رِقَابَهُمْ. وَ لَا تَعْدُو عَلَى عَزِيمَةِ جِدِّهِمْ بَلَادَةُ الْغَفَلَاتِ وَ لَا تَنْتَضِلُ فِي هِمَمِهِمْ خَدَائِعُ الشَّهَوَاتِ.\nترجمه:\nگروهى از آنها در درون ابرهاى پر آب و بر فراز کوههاى عظيم و مرتفع و در پوشش تاريکى هاى شديد قرار دارند و گروهى ديگر از آنها قدمهايشان تا قعر زمين پايين رفته و (قامت آنها) همچون پرچم هاى سفيدى دل هوا را شکافته و در زير آن بادهايى است که با سرعت و نظم حرکت مى کند و آنها را در مرزهاى معيّنى نگه مى دارد.\nاشتغال به عبادت پروردگار، تمام وجودشان را پر کرده است، و حقيقت ايمان ميان آنان و معرفت خدا پيوند داده، و يقين به پروردگار، آنها را تا سر حدّ عشق به او پيش برده است، و به جهت علاقه اى که به آنچه نزد خداست دارند به چيزى نزد غير او نمى انديشند.\nآنها شيرينى معرفت خدا را چشيده و از جام محبتّش سيراب شده اند، و (در عين حال) خوف او در اعماق جانشان جايگزين شده است; قامتشان از کثرت اطاعت خم شده و رغبت فراوان آنها به عبادت پروردگار، هرگز حال تضرّع و نشاط عبادت را در آنها از بين نبرده، و مقام برجسته آنان طوق خشوع را از گردنشان باز نکرده است; خودبينى و عُجب آنها را فرا نگرفته، تا اعمال گذشته خود را بسيار بشمرند، خضوع و کوچکى در برابر ذات با عظمتش، جايى براى بزرگ شمردن حسنات براى آنان باقى نگذارده است و با اينکه پيوسته مشغول عبادتند فتور و سستى به آنها دست نمى دهد و ادامه اين کار از رغبتشان نمى کاهد، تا از اميد به پروردگار خود روى برتابند.\nمناجاتهاى طولانى زبان آنان را خشک و ناتوان نساخته و اشتغال به غير خداوند، آنها را تحت سلطه خود نياورده، تا نداى بلند آنان را (در مقام تضرّع و تسبيح) کوتاه سازد، در مقام اطاعت و بندگى همچنان دوش به دوش ايستاده اند; و راحت طلبى، آنان را به کوتاهى در انجام فرمانش وانداشته و کودنى غفلت ها بر تلاش و عزم راسخ آنها چيره نگرديده، و تيرهاى فريبِ شهوات، همّت هاى آنها را هدف قرار نداده است!.\nتفسیر:\nصفت ملائکه\nشخصی در پی‌شناخت خداوند بود، امام فرمود: ما هنوز در شناخت مخلوقات مانده‌ایم و حقیقت آفریدگان برای ما روشن نشده است، پس چگونه می‌توانید خدا را بشناسید؟ ایشان از آثار آفرینش خداوند در بخش فرشتگان، مطالب آموزنده‌ای بیان فرمودند:\nعده‌ای از فرشتگان، رسولان الهی و مأمور ابلاغ وحی بودند و گروه بعدی که چندین دسته هستند:\n«مِنْهُمْ مَنْ هُوَ فی خَلْقِ الْغَمامِ الدُّلَحِ»\n۱- عده‌ای از فرشتگان که درون ابرهای سنگین [دُلَح] قرار دارند؛ همان ابرهای پرباری که از شدت وجود باران، گران‌بار شده‌اند. خداوند فرشته را مأمور حمل این ابر می‌کند تا مشخص کند کجا بایستد، کجا ببارد و چه مقدار بارش داشته باشد.\n«وَفی عِظَمِ الْجِبالِ الشُّمَّخِ»\n۲- برخی از فرشتگان بر فراز کوه‌های بلند و سر به فلک کشیده [شُمَّخ] استقرار یافته‌اند.\n«وَفی قُتْرَةِ الظَّلامِ الْأَیْهَمِ»\n۳- برخی دیگر از فرشتگان در میان تاریکی‌ها و ظلمت‌های سخت بیابان‌ها هستند؛ جایی که از شدت تاریکی، چشم هیچ‌چیز را نمی‌بیند.\nوظیفهٔ این فرشتگان چیست؟ اگر کوه‌ها باصلابت پابرجایند و منبع تغذیهٔ دشت‌های پایین‌دست خود محسوب می‌شوند، فرشتگانی دارند که مسئول حفاظت از آن‌ها هستند. برای روشن‌تر شدن بحث، در دعای سوم صحیفهٔ سجادیه، حضرت سجاد (ع) ابتدا به فرشتگان سلام و درود می‌فرستند و در بخشی اشاره می‌کنند که ملائکه موکل امور خاصی هستند:\n«وَخُزّانِ الْمَطَرِ وَزَواجِرِ السَّحابِ»: فرشتگانی که خزانه‌دار باران هستند و تدبیر می‌کنند که چه مقدار و در کجا ببارد.\n«وَالَّذینَ عَرَّفْتَهُمْ مَثاقیلَ الْمِیاهِ وَکَیْلَ ما تَحْویهِ لَواعِجُ الْأَمْطارِ»: فرشتگانی که مسئول حمل برف و تگرگ هستند.\n«وَالْهابِطینَ مَعَ قَطْرِ الْمَطَرِ اِذا نَزَلَ»: فرشتگانی که همراه قطرات باران فرود می‌آیند تا خود را به مکان موردنظر برسانند.\n«وَالْقُوّامِ عَلی خَزائِنِ الرِّیاحِ»: فرشتگانی که نگهبان خزینه‌های وزش باد هستند.\n«وَالْمُوَکَّلینَ بِالْجِبالِ فَلا تَزُولُ»: فرشتگانی که موکل کوه‌ها هستند و اگر نباشند، کوهی همچون دماوند فرومی‌ریزد.\nفرشتگان اموری را که از نظر شما طبیعی است اداره می‌کنند؛ ما وزش باد و بارش باران را می‌بینیم، درحالی‌که هر یک از این‌ها فرشتگان مخصوص به خود را دارند.\n«وَمِنْهُمْ مَنْ قَدْ خَرَقَتْ أَقْدامُهُمْ تُخُومَ الْأَرْضِ السُّفْلی»\nگروهی دیگر از فرشتگان هستند که پاهایشان اعماق زمین و پایین‌ترین طبقات آن را شکافته است.\n«فَهِیَ کَرایاتٍ بیضٍ قَدْ نَفَذَتْ فی مَخارِقِ الْهَواءِ»\nقد و قامت آن‌ها همچون پرچم‌های سفیدی است که تا ژرفای آسمان بالا رفته است؛ یعنی از پایین‌ترین قسمت زمین تا بالاترین جای آسمان قد کشیده‌اند.\nآیا این توصیف واقعی است یا جنبهٔ تشبیه و استعاره دارد؟ اگر واقعیت باشد که معنای خود را دارد، اما برخی گفته‌اند منظور «علمِ ملائکه» است که به همه چیز دسترسی دارند؛ بعید نیست که هر دو معنا درست باشد.\n«وَتَحْتَها ریحٌ هَفّافَةٌ تَحْبِسُها عَلی حَیْثُ انْتَهَتْ مِنَ الْحُدودِ الْمُتَناهِیَةِ»\nزیر پای این فرشتگان در قعر زمین، بادهایی می‌وزد. این بادها آرام و همچون نسیم [هَفّافَة] هستند و باعث می‌شوند فرشتگان در جای خود ثابت بمانند؛ پس معلوم است که برای آن‌ها نیز محدودیتی وجود دارد. این نسیم حدومرز آن‌ها را مشخص می‌کند (علم فرشتگان باید محدود باشد؛ زیرا خدا می‌خواهد صفت ستاری‌ات خود را نسبت به افراد حفظ کند).\n«قَدِ اسْتَفْرَغَتْهُمْ أَشْغالُ عِبادَتِهِ»\nفرشتگان کسانی هستند که هر مشغله‌ای جز عبادت، از وجودشان تهی شده است. آن‌ها آن‌چنان غرق در عبادت‌اند که حواسشان به‌جای دیگری نیست. ما انسان‌ها می‌توانیم در متن زندگی به تقرب برسیم، اما فرشتگان برای عبادت فارغ‌البال شده‌اند.\nمولوی:\nجهان مثل درخت است، برگ و میوه ز توست\nچو برگ و میوه نباشد، شجر چه سود کند؟\nانسانِ بی‌برگ‌وبار، بی‌برکت است و درختی که سایه و میوه نداشته باشد، بی‌ثمر خواهد بود.\nگذر کن از بشریت، فرشته باش دلا\nفرشتگی چو نباشد، بشر چه سود کند؟\nما آمده‌ایم تا ملکوتی شویم و زمینی نمانیم؛ هدف ما رسیدن به معراج است. در این بخش، حضرت حالات و خلقیات فرشتگان را توصیف می‌کنند:\n«وَوُصِلَتْ حَقائِقُ الْإیمانِ بَیْنَهُمْ وَبَیْنَ مَعْرِفَتِهِ»\nحقایقِ ایمانِ راسخ و مستحکم، میان آن‌ها و شناختِ خدا پیوند ایجاد کرده است. هر کس خواهان شناخت صحیح خداست، باید ایمانش را تقویت کند؛ زیرا آنچه مایهٔ شناخت خدا می‌شود، ایمان است و ایمان، معرفت می‌آورد. فرشتگان به سبب شدت ایمانشان به معرفت الهی متصل شده‌اند.\n«وَقَطَعَهُمُ الْإیقانُ بِهِ اِلَی الْوَلَهِ اِلَیْهِ»\nیقین به پروردگار، ملائکه را به مقام «واله شدن» و شیدایی نسبت به او رسانده است؛ آن‌ها عاشق خدا هستند و به همین دلیل دغدغهٔ دیگران را ندارند.\nمرحلهٔ اول: فراغت بال\nمرحلهٔ دوم: کسب ایمان\nمرحلهٔ سوم: معرفت\nمرحلهٔ چهارم: واله و عاشق خدا شدن.\nوقتی فراغت حاصل شود، ایمان رشد می‌کند؛ با رشد ایمان، معرفت به دست می‌آید و با زیادشدن معرفت، نمی‌توان عاشق خدا نبود. عاشق شدن، سهم اهل ایمان است.\nعشق آن است که امام صادق (ع) فرمود:\n«أَفْضَلُ النّاسِ مَنْ عَشِقَ الْعِبادَةَ وَآنَقَها»\nبرترینِ مردم کسی است که عاشق عبادت باشد و با آن معانقه کند (آن را در آغوش بگیرد).\n«وَأَحَبَّها بِقَلْبِهِ وَباشَرَها بِجَسَدِهِ وَتَفَرَّغَ لَها»: با قلب و تمام وجود در خدمت عبادت باشد و برای آن فراغت بال ایجاد کند.\n«وَلَمْ تَجاوَزْ رَغَباتُهُمْ ما عِنْدَهُ اِلی ما عِنْدَ غَیْرِهِ»\nفرشتگان هرگز به غیر خدا رغبت ندارند. گاهی ما هم به خدا و هم به غیر او میل داریم، اما فرشتگان تنها به او مشتاق‌اند. اگر درجهٔ عشق پایین باشد، انسان به هر چیزی ابراز علاقه می‌کند.\n«قَدْ ذاقُوا حَلاوَةَ مَعْرِفَتِهِ»\nفرشتگان حلاوت و شیرینیِ شناخت خدا را چشیده‌اند. «یا مَنْ ذِکْرُهُ حُلْوٌ»؛ یاد خدا شیرین است، اما نه از نوع شیرینی‌های دنیایی که ملال‌آور باشد، بلکه هر چه بیشتر بهره برده شود، لذت‌بخش‌تر است و وابستگی بیشتری ایجاد می‌کند.\nخداوند به حضرت داوود (ع) وحی فرمود: بندگان من چرا هم‌وغم دنیا را دارند؟ غم دنیا داشتن، شیرینیِ ذکر خدا را از بین می‌برد. اگر دل در گرو چندین جا باشد، لذت مناجات می‌رود؛ حلاوت در جایی است که فراغت بال حاصل شود.\n«وَشَرِبُوا بِالْکَأْسِ الرَّویَّةِ مِنْ مَحَبَّتِهِ»\nفرشتگان با جامی لبریز از محبت خداوند سیراب گشته‌اند؛ آن‌ها از سرچشمهٔ حیات، آب زلال نوشیده‌اند. حضرت علی (ع) فرمودند: «حُبُّ اللّهِ نارٌ لا تَمُرُّ عَلی شَیْءٍ اِلّا احْتَرَقَ»؛ محبت خدا آتشی است که بر هر چه بگذرد آن را می‌سوزاند. این آب، وجود را می‌سوزاند؛ اما سوزاندن محبوب، خود لذت است. کسانی که آتش عشق الهی در وجودشان روشن است، هرگز سیراب نمی‌شوند؛ فرشتگان این‌گونه‌اند که هر چه می‌نوشند، تشنه‌تر می‌گردند.\n«وَتَمَکَّنَتْ مِنْ سُوَیْداءِ قُلُوبِهِمْ وَشیجَةُ خیفَتِهِ»\nترس از خدا در اعماق قلب‌هایشان ریشه دوانده است. آن‌ها در عین طاعت، خوف الهی دارند؛ زیرا خوف‌ورجا (بیم و امید) باید در کنار هم باشند. اگر ترس نباشد، غرور پدید می‌آید. در هر مرتبه‌ای از عرفان باید خوف داشت و فرشتگان لحظه‌ای از آن غافل نمی‌شوند.\n«فَحَنَوْا بِطُولِ الطّاعَةِ اعْتِدالَ ظُهُورِهِمْ»\nکمر فرشتگان از شدت طاعت منحنی شده است [حَنَوْا]؛ یعنی از کثرت عبادت در حالت تواضع و خضوع قرار گرفته‌اند. نمی‌دانیم این توصیف استعاره است یا حقیقت. امام سجاد (ع) گاهی از حالات جدمان علی (ع) می‌گفتند که چگونه عبادت می‌کرده، یا حضرت زهرا (س) که پاهایشان از فرط عبادت ورم می‌کرده است؛ برای رسیدن به این شیرینی باید سختی کشید.\n«وَلَمْ یَنْفَدْ طُولُ الرَّغْبَةِ اِلَیْهِ مادَّةَ تَضَرُّعِهِمْ»\nعبادت‌های طولانی، مایهٔ تضرع و زاری آن‌ها را از بین نمی‌برد؛ فرشتگان بااین‌همه تقرب، تضرعشان کاسته نشده است.\n«وَلا أَطْلَقَ عَنْهُمْ عَظیمُ الزُّلْفَةِ رِبَقَ خُشُوعِهِمْ»\nنزدیک بودن به خدا، طوقِ بندگی و خشوع را از گردن فرشتگان باز نکرده است [لَمْ أَطْلَقَ]. هر چه بیشتر عبادت کردند، سربه‌زیرتر شدند. در دنیا برعکس است؛ مسئولان دنیایی همچون خورشید از دور زیبا و از نزدیک سوزانند، اما ملائکه هر چه به خدا نزدیک‌تر می‌شوند، خشوعشان بیشتر می‌گردد؛ چرا که بامعرفت بیشتر، عظمت خدا را بیشتر درک می‌کنند.\n«وَلَمْ یَتَوَلَّهُمُ الْاِعْجابُ فَیَسْتَکْثِرُوا ما سَلَفَ مِنْهُمْ»\nفرشتگان هرگز دچار عُجب (خودپسندی) نمی‌شوند و خدمات گذشتهٔ خود را زیاد نمی‌بینند. آن‌ها کسانی هستند که حتی تصورِ حجمِ عبادتشان ملال‌آور است، اما خودشان اعمالشان را بزرگ نمی‌بینند.\n«وَلا تَرَکَتْ لَهُمْ اِسْتِکانَةُ الْإِجْلالِ نَصیباً فی تَعْظیمِ حَسَناتِهِمْ»\nهنگامی که به عظمت خداوند می‌نگرند، اعمال خود را ناچیز می‌بینند. باید نگاه به مقامات بالا باشد؛ اعمال ما در برابر جلال الهی هیچ است. آن‌ها نسبت به گذشته عُجب ندارند و برای جلال خداوند بیشتر تلاش می‌کنند.\n«وَلَمْ تَجْرِ الْفَتَراتُ فیهِمْ عَلی طُولِ دُؤُوبِهِمْ»\nهیچ سستی و ضعفی بر فرشتگان، علی‌رغم کوشش مداومشان [دُؤُوب]، عارض نمی‌شود. در عالم دنیا، عبادت طولانی نیاز به استراحت ایجاد می‌کند، اما فرشتگان از کثرت عبادت خسته نمی‌شوند و دچار کم‌کاری نمی‌گردند. دربارهٔ این‌که آیا فرشتگان اختیار دارند یا خیر، دو نظر هست: ۱- مجبورند. ۲- اختیار دارند؛ اما چون سرشار از عشق‌اند، تنبلی در عبادت آن‌ها راه ندارد.\n«وَلَمْ تَغِضْ رَغَباتُهُمْ فَیُخالِفُوا عَنْ رَجاءِ رَبِّهِمْ»\nرغبت آن‌ها فروکش نمی‌کند تا امیدشان به پروردگار کم شود. آن‌ها پیوسته طاعت می‌کنند و به رحمت خدا امیدوارند. رجا (امید) به این معنا نیست که گوشه‌ای بنشینی؛ ما گاهی تنبلی را با رجا اشتباه می‌گیریم. امید به رحمت خدا پس از تلاش و زحمتِ بسیار معنا می‌یابد.\n«وَلَمْ تَجِفَّ لِطُولِ الْمُناجاةِ أَسَلاتُ أَلْسِنَتِهِمْ»\nفرشتگان همواره اهل ذکرند، بااین‌حال زبانشان از طول مناجات خشک نمی‌شود. ما با اندکی عبادت نیاز به تجدید قوا داریم.\n«وَلا مَلَکَتْهُمُ الْأَشْغالُ فَتَنْقَطِعَ بِهَمْسِ الْجُؤارِ اِلَیْهِ أَصْواتُهُمْ»\nفرشتگان با صدای بلند خداوند را تسبیح می‌کنند؛ صدایی که گوش‌ها را کر می‌کند و هرگز قطع نمی‌شود؛ زیرا انقطاع صدا ناشی از توجه به‌جای دیگر است و حواس فرشتگان هرگز پرت نمی‌شود.\n«وَلَمْ تَخْتَلِفْ فی مُقاوِمِ الطّاعَةِ مَناکِبُهُمْ»\nما در هنگام عبادت خسته می‌شویم، اما فرشتگان در صفوف منظم عبادت، شانه‌هایشان [مَناکِب] را تکان نمی‌دهند و از جای خود نمی‌جنبند.\n«وَلَمْ یَثْنُوا اِلی راحَةِ التَّقْصیرِ فی أَمْرِهِ رِقابَهُمْ»\nآن‌ها برای راحت‌طلبی و کوتاهی در فرمان خدا، گردن خم نمی‌کنند [لَمْ یَثْنُوا]. آداب عبادت را کاملاً رعایت می‌کنند، راحت‌طلب نیستند و از زیر بار مسئولیت شانه خالی نمی‌کنند؛ هر وظیفه‌ای را باهمت به سرانجام می‌رسانند.\n«وَلا تَعْدُوا عَلی عَزیمَةِ جَدِّهِمْ بَلادَةُ الْغَفَلاتِ»\nبر عزم و ارادهٔ محکم آن‌ها، سستیِ ناشی از غفلت حاکم نمی‌شود. غفلت نوعی نادانی و حماقت است؛ اگر کسی از خدا غافل شود، از عقل تهی گشته و به درجهٔ کودنی می‌رسد.\n«وَلا تَنْتَضِلُ فی هِمَمِهِمْ خَدائِعُ الشَّهَواتِ»\nهمت بلند فرشتگان مورد هدف تیرهای فریبندهٔ شهوات قرار نمی‌گیرد. همان آفت‌هایی که انسان به آن گرفتار است و تا قصدِ خوب شدن می‌کند، همتش می‌شکند. شهوتِ ریاست و شهرت، همت را از بین می‌برد. گاهی فکر گناه از خود آن فریبنده‌تر است؛ به‌طورکلی شهوت نوعی نیرنگ است.\nالحَمْدُ لِلَّهِ الَّذِی جَعَلَنَا مِنَ الْمُتَمَسِّکینَ بِوِلَایةِ أَمِیرِ الْمُؤْمِنِینَ.","بخش هشتم\nمتن:\nقَدِ اتَّخَذُوا ذَا الْعَرْشِ ذَخِيرَةً لِيَوْمِ فَاقَتِهِمْ وَ يَمَّمُوهُ عِنْدَ انْقِطَاعِ الْخَلْقِ إِلَى الْمَخْلُوقِينَ بِرَغْبَتِهِمْ لَا يَقْطَعُونَ أَمَدَ غَايَةِ عِبَادَتِهِ وَ لَا يَرْجِعُ بِهِمُ الِاسْتِهْتَارُ بِلُزُومِ طَاعَتِهِ إِلَّا إِلَى مَوَادَّ مِنْ قُلُوبِهِمْ غَيْرِ مُنْقَطِعَةٍ مِنْ رَجَائِهِ وَ مَخَافَتِهِ لَمْ تَنْقَطِعْ أَسْبَابُ الشَّفَقَةِ مِنْهُمْ فَيَنُوا فِي جِدِّهِمْ وَ لَمْ تَأْسِرْهُمُ الْأَطْمَاعُ فَيُؤْثِرُوا وَشِيكَ السَّعْيِ عَلَى اجْتِهَادِهِمْ لَمْ يَسْتَعْظِمُوا مَا مَضَى مِنْ أَعْمَالِهِمْ وَ لَوِ اسْتَعْظَمُوا ذَلِكَ لَنَسَخَ الرَّجَاءُ مِنْهُمْ شَفَقَاتِ وَجَلِهِمْ وَ لَمْ يَخْتَلِفُوا فِي رَبِّهِمْ بِاسْتِحْوَاذِ الشَّيْطَانِ عَلَيْهِمْ وَ لَمْ يُفَرِّقْهُمْ سُوءُ التَّقَاطُعِ وَ لَا تَوَلَّاهُمْ غِلُّ التَّحَاسُدِ وَ لَا تَشَعَّبَتْهُمْ مَصَارِفُ [الرَّيْبِ‏] الرِّيَبِ وَ لَا اقْتَسَمَتْهُمْ أَخْيَافُ الْهِمَمِ فَهُمْ أُسَرَاءُ إِيمَانٍ لَمْ يَفُكَّهُمْ مِنْ رِبْقَتِهِ زَيْغٌ وَ لَا عُدُولٌ وَ لَا وَنًى وَ لَا فُتُورٌ وَ لَيْسَ فِي أَطْبَاقِ السَّمَاءِ مَوْضِعُ إِهَابٍ إِلَّا وَ عَلَيْهِ مَلَكٌ سَاجِدٌ أَوْ سَاعٍ حَافِدٌ يَزْدَادُونَ عَلَى طُولِ الطَّاعَةِ بِرَبِّهِمْ عِلْماً وَ تَزْدَادُ عِزَّةُ رَبِّهِمْ فِي قُلُوبِهِمْ عِظَماً.\nترجمه:\nآنها (فرشتگان عشق به) خداوندى را که صاحب عرش است ذخيره روز بى نوايى خود قرار داده و در آن هنگام که ديگران به مخلوقات مى انديشند آنها تمام توجّه خود را به خالق معطوف ساخته اند. آنها هيچ گاه عبادت او را پايان نمى دهند (چرا که) علاقه آنها به لزوم عبادت پروردگار از رجا و خوف او - که هرگز از دل آنها برکنده نمى شود - سرچشمه مى گيرد، و هرگز اسباب خوف پروردگار از آنها قطع نشده تا در تلاش و کوشش خود سستى کند و طمع ها آنها را اسير چنگال خود نساخته تا سرعت سعى (در امور دنيا) را بر کوشش خود (در کار آخرت و طاعت پروردگار) مقدّم دارند.\nآنها اعمال گذشته خود را بزرگ نشمرده که اگر بزرگ مى شمردند اميدوارى (بيش از حدّ) خوفشان را از بين مى برد، آنها درباره پروردگارشان هرگز بر اثر وسوسه هاى شياطين گرفتار اختلاف نشده، و برخوردهاى بد، آنان را از هم جدا نساخته و حسادت هاى درونى، آنان را از هم دور ننموده است، عوامل شک و ترديد، آنها را پراکنده نکرده، و افکار متفرقه، جمع آنها را از هم جدا نساخته است، آنها هميشه پاى بند ايمانى هستند که هرگز طوق آن را به سبب شک و ترديد، و عدول از حق، و سستى و خستگى، از گردن خويش بر نمى دارند، در تمام آسمان ها به قدر جاى پوست حيوانى نتوان يافت که فرشته اى در آنجا به سجده نيفتاده باشد، يا ملکى تلاشگر و سريع و چابک مشغول به کار نباشد، فرشتگانى که طاعت فراوان پيوسته، بر يقين و معرفتشان نسبت به پروردگار مى افزايد و عزت خداوند را در قلوبشان فزونى مى بخشد!\nتفسیر:\nصفت ملائکه\nامیرالمؤمنین صلوات‌الله‌علیه در بیان خداشناسی، صفاتی از ملائک را بیان می‌دارند که برای انسان جنبهٔ تربیتی دارد تا مطالب اخلاقی، عرفانی و ملکوتی را بیاموزد.\nوظیفهٔ ما آن است که حرکت کنیم و برای ملکوتی شدن، صفات ملائک را در خود پیاده کنیم.\n«قَدِ اتَّخَذُوا ذَا الْعَرْشِ ذَخِیرَةً لِیَوْمِ فَاقَتِهِمْ»\nملائک، صاحب عرش، یعنی خداوند را برای روز نیاز خود [فاقتهم] ذخیره و پشتوانه قرار داده‌اند.\nاین تعبیر مهمی است که ملائک نیز روزی را پیشرو دارند که روز نیاز و حاجت آنان است؛\nمانند انسان که قبر، برزخ، حشر و معاد، جایگاه نیاز اوست.\nمرگ‌ومیر ملائک مانند انسان نیست؛ با ترتیب می‌آیند، اما در رفتن، ترتیب ندارند و همگی با هم می‌روند؛ در همان نفخهٔ صور که همه، جز خدا، می‌میرند.\nحشر دارند و برانگیخته می‌شوند. باید حساب پس بدهند، اما جهنمی ندارند. بهشت آنان بنابر مسئولیت، کیفیت عبادت و مرتبه‌هایشان با دیگر ملائک متفاوت است. آنان برای روزی که به تقرب بیشتر و جایگاه بهتر نیاز دارند، محتاج خدا هستند.\n«وَیَمَّمُوهُ عِنْدَ انْقِطاعِ الْخَلْقِ إِلَی الْمَخْلُوقِینَ بِرَغْبَتِهِمْ»\nخدا را قصد کرده‌اند و از خلق، انقطاع یافته‌اند. نگاه آنان به دست مخلوق نیست؛ همهٔ رغبتشان به خداست و از خلق بریده‌اند.\nنتیجه: نقطهٔ تفاوت انسانی که ملکوتی نمی‌شود، این است که نگاهش به دست دیگران است تا او را دستگیری کنند؛ درحالی‌که همه، تنها ابزار و وسیله‌اند.\n«لا یَقْطَعُونَ أَمَدَ غَایَةِ عِبادَتِهِ»\nملائک به آن حد نهایی عبادت نمی‌رسند.\nخدای بی‌نهایت را هرچه عبادت کنند، حق عبادت او را نمی‌توانند به‌جا آورند.\nدر عبادت خود پیوسته در سجده‌اند و برنمی‌خیزند، اما هنوز به انتهای عبادت نرسیده‌اند؛ زیرا خدا پایان‌پذیر نیست.\n«وَلا یَرْجِعُ بِهِمُ الِاسْتِهْتارُ بِلُزُومِ طاعَتِهِ»\nهیچ‌چیز، ملائکه را از عشق به خدا بازنمی‌گرداند و نمی‌تواند آنان را از شوق و عبادت منصرف کند، مگر این‌که:\n«إِلَّا إِلی مَوَادَّ مِنْ قُلُوبِهِمْ غَیْرِ مُنْقَطِعَةٍ مِنْ رَجائِهِ وَمَخافَتِهِ»\nمگر این‌که مواد اصلی آن عبادت از ملائک گرفته شود.\nچه ماده و قوهٔ محرکه‌ای در درون آنان هست که اگر نباشد، عبادت را ترک می‌کنند؟\nدو عامل خوف‌ورجا، دو مادهٔ اصلی آنان است که عاشق عبادتشان کرده است.\nکم و زیادشدن این دو عامل، خطراتی در پی دارد: اگر امید بیش از اندازه شود، انسان فقط بخشندگی خدا را می‌بیند و عبادتش کمتر می‌شود.\nاگر خوف بیش از رجا باشد، خود را همیشه بدهکار خدا می‌داند و چون از عهدهٔ شکر او برنمی‌آید، خود را جهنمی می‌بیند و رها می‌کند.\nنتیجهٔ هر دو، ترک عبادت است.\nاین دو ماده باید به یک اندازه و در تعادل باشند؛ اگر این تعادل حفظ شود، التزام به بندگی و عبادت در پی خواهد داشت.\nعبادت ترک یا کم نمی‌شود، مگر آنکه مادهٔ اصلی در وجود مختل شود.\n«لَمْ تَنْقَطِعْ أَسْبابُ الشَّفَقَةِ مِنْهُمْ فَیَنُوا فِی جِدِّهِمْ»\nاسباب ترس از خدا در ملائک قطع نمی‌شود تا آنان سستی کنند [یَنُوا] و از جدیت خود دست بکشند.\nاثر تربیتی ترس از خدا این است که تنبلی را از بین می‌برد و انسان را به تلاش و کوشش فراوان وامی‌دارد؛ مانند تفاوت دانش‌آموزی که از معلم خود حساب ببرد یا نبرد که در میزان تلاش او اثر می‌گذارد.\nاز جهت تربیتی، انذار غالباً از تشویق اثرگذارتر است. رعایت حدود است که انسان را سربه‌زیر می‌کند، نه تشویق زیاد. سخت‌گیری در موارد لازم، گاهی از تشویق مؤثرتر است.\n«وَلَمْ تَأْسِرْهُمُ الْأَطْماعُ فَیُؤْثِرُوا وَشِیکَ السَّعْیِ عَلی اجْتِهادِهِمْ»\nطمع، ملائک را اسیر نکرده است [تَأْسِرْهُم] تا تلاش نزدیک و زودگذر دنیا را بر کوشش اصلی خود مقدم بدارند [یُؤْثِرُوا].\nطمع، اسارت است. وقتی کسی اسیر شد، فقط به امروز خود می‌اندیشد، به فردا فکر نمی‌کند و برای فردا برنامه‌ای ندارد؛ چون اسیر است.\nطمع، اسارتِ همیشگی است و هیچ‌گاه آزادی نمی‌آورد.\nاسیر، آینده‌نگر نیست و در مقابل آن، زهد قرار دارد که انسان را آینده‌نگر می‌کند.\nاما در عرف امروز، زاهد را بیچاره‌ای می‌دانند که فقط در پی گذراندن روز خود است تا از گرسنگی نمیرد.\nدر عرف، این‌گونه می‌پندارند که پول، آینده را می‌سازد. در امور معنوی هم همین‌طور است؛ بلندنظری در زهد است؛ مانند نویسندگان کتاب‌های بزرگ که در عین زهد، بلندنظر بودند و با نوشتن کتاب، آیندگان را ساختند. طماع، دنیا را آباد می‌کند؛ زاهد، آخرت را هم آباد می‌کند.\n«وَلَمْ یَسْتَعْظِمُوا ما مَضی مِنْ أَعْمالِهِمْ»\nملائک، اعمال خود را بزرگ نمی‌شمارند. هرچه عملشان بیشتر باشد، خضوع و خشوع آنان بیشتر می‌شود.\nاثر سوء بزرگ دیدن اعمال چیست؟\n«وَلَوِ اسْتَعْظَمُوا ذلِکَ لَنَسَخَ الرَّجاءُ مِنْهُمْ شَفَقاتِ وَجَلِهِمْ»\nاگر اعمالشان را بزرگ می‌دیدند، رجا از آنان گرفته می‌شد و امیدواری حقیقی از بین می‌رفت.\nامیدبستن به عمل خود، امید به خدا را ضعیف می‌کند و همین امیدبستن به عمل، آغاز سقوط انسان است.\nدومین اثر امیدبستن به عمل خود، ازبین‌رفتن انواع خوف است [شَفَقاتِ وَجَلِهِمْ]؛ ترس از خدا از بین می‌رود و انسان، خود را بندهٔ خوب خدا می‌داند و ترس را مخصوص دیگرانی می‌بیند که بندهٔ خوب نیستند.\nدرحالی‌که زبیر لقب «مِنَّا أَهْلَ الْبَیْتِ» را گرفته بود و شمشیر او بارها غم را از چهرهٔ حضرت زدوده بود، اما خوف او از بین رفت و نتیجه‌اش سقوطش شد.\n«وَلَمْ یَخْتَلِفُوا فِی رَبِّهِمْ بِاسْتِهْواءِ الشَّیْطانِ عَلَیْهِمْ»\nهیچ اختلاف، شک و شبهه‌ای در مورد خدا ندارند، چون سلطهٔ شیطان است که چنین القا می‌کند.\nملائک شبهه ندارند، زیرا شیطان بر آنان مسلط نیست.\nنتیجه: اگر اختلافی در عالم پدید می‌آید، شیطان بر آن مسلط می‌شود و به آن رنگ می‌دهد.\nدر کنه وجود انسان، فطرت آدمی خداشناس آفریده شده است؛ اگر انسان به فطرت خود رجوع کند، خود را مخلوق خدا می‌داند و او را قادر مطلق و فرمان او را مطاع می‌شناسد. فطرت این معنا را خوب می‌فهمد.\nشیطان دقیقاً الهیات را هدف می‌گیرد تا اختلاف پدید آید. در اختلاف، وحدتی در کار نیست و بدون وحدت، توحید نیز استوار نمی‌ماند. وقتی توحید نشانه رفت و برهم خورد، اختلاف‌ها گسترده می‌شود و ستون اجتماع نیز فرومی‌ریزد.\nملائک این اختلافات را ندارند، چون شیطان بر آنان مسلط نیست.\n«وَلَمْ یُفَرِّقْهُمْ سُوءُ التَّقاطُعِ»\nبین ملائک، بدیِ قطع رابطه و بریدن از یکدیگر، تفرقه نینداخته است [سُوءُ التَّقاطُع].\nدر امور دنیوی، انسان‌ها معمولاً در برابر بدی دیگری، بدی می‌کنند. ارتباطات دنیوی بر محور منفعت است؛ اگر سودی داشته باشد، رابطه برقرار می‌شود. درحالی‌که دین فرمان داده است ارتباط بگیرید تا سود برسانید، نه این‌که سود بگیرید. ارتباط باید بر محور وظیفه باشد، حتی اگر طرف مقابل بدی کند.\nحضرت در خطبه‌های دیگر فرمودند: بالاترین جود آن است که اگر کسی رابطه‌اش را با تو قطع کرد، تو با او رابطه برقرار کنی. بین ملائک چنین قطع‌کردن‌هایی نیست و ازاین‌رو تفرقه‌ای هم پدید نمی‌آید.\n«وَلا تَوَلَّاهُمْ غِلُّ التَّحاسُدِ»\nکینه و حسد بر ملائک مسلط نشده است؛ این حسد است که کینه می‌آورد.\nفاصلهٔ انسان تا ملائک، فاصلهٔ زمانی نیست، بلکه فاصلهٔ حجابی است. این حجاب در دنیا می‌تواند کنار برود. حسادت، قطع رابطه و تسلط شیطان در ملائک راه ندارد. کسی که شبیه آنان شود، ملک گونه می‌شود و با ملک ارتباط می‌گیرد و فاصله برداشته می‌شود.\n«وَلا تَشَعَّبَتْهُمُ مَصارِفُ الرَّیْبِ»\nشک‌های گوناگون بر ملائک عارض نمی‌شود تا آنان را شعبه و پراکنده کند.\nعامل بدبختی، شک و سوءظن است و نتیجهٔ آن، تفرقه است. چنین نگاهی در جامعه نیز به پراکندگی اجتماعی می‌انجامد.\n«وَلا اقْتَسَمَتْهُمْ أَخْیافُ الْهِمَمِ»\nهمت‌های گوناگون، ملائک را قسمت نمی‌کند.\n«أَخْیاف» دو معنا دارد:\n۱- اختلاف؛ یعنی گروهی که هیچ نوع اختلافی در همت و دغدغه‌مندی ندارند. در اولویت‌بندی و تقسیم‌بندی اختلافی ندارند، اولویت‌ها را خوب می‌شناسند و به آن‌ها عمل می‌کنند. اولویت و دغدغهٔ همهٔ آن‌ها یکی است.\n۲- رنگ‌های گوناگون؛ مانند دورنگ سرمه در چشم که معنایی لطیف و کاربردی دارد.\nدر جامعهٔ انسانی، اختلاف در اولویت‌ها فراوان است و دغدغه‌ها با هم فرق دارد. درجه‌بندی دغدغه‌ها متفاوت است و اختلاف عقیده، نظر و سلیقه بسیار دیده می‌شود.\nاما برای ملائک، در عین آنکه هر یک کاری و وظیفه‌ای دارند، هیچ‌یک دیگری را تخطئه نمی‌کند و او را فرومایه نمی‌بیند. هرکدام باری بر دوش دارند، اما همین تفاوت وظایف باعث اختلاف آنان نمی‌شود.\nمشکل اجتماعات این است که اختلاف سلیقه‌ها گاهی به اختلاف تفرقه‌انگیز کشیده می‌شود. بنا نیست؛ چون اولویت‌ها متفاوت است، با نگاه حقارت به دیگری نگریسته شود. دغدغه‌ها متفاوت است، اما جامعهٔ درست، از کنار هم قرارگرفتن همین تفاوت‌ها شکل می‌گیرد.\n«فَهُمْ أُسَراءُ إِیمانٍ لَمْ یَفُکَّهُمْ مِنْ رِبْقَتِهِ زَیْغٌ وَلا عُدُولٌ وَلا وَنًی وَلا فُتُورٌ»\nملائک اسیر ایمان‌اند. هیچ‌گونه انحراف، عدول از حق، سستی [وَنًی] و خستگی [فُتُور]، طوق بندگی را از گردن آنان باز نمی‌کند.\nملائک به‌خاطر این امور، عبادت را ترک نمی‌کنند؛ زیرا اختلاف، عدول از حق، تنبلی و خستگی ندارند.\nتعبیر «أُسَراءُ إِیمانٍ» نشان‌دهندهٔ بی‌اختیاری و جبر نیست. ملائک اختیار دارند، اگرچه شهوت جنسی ندارند، اما امکان سرباز زدن از فرمان خدا برای آنان قابل‌تصور است.\nچون با اختیار خود اهل طاعت و عبادت‌اند، آنان را تجلیل می‌کنیم؛ وگرنه اگر به یک ربات برنامه بدهند که دائم در رکوع باشد، ارزشی ندارد، عجب کارخانه‌ای می‌شود دیگر!\nاگر جبر بر آنان حاکم بود و مجبور به عبادت بودند، با انسان قابل‌مقایسه نبودند. اما آنان نیز اختیار دارند و امکان سرپیچی برایشان قابل فرض است و «أُسَراءُ إِیمانٍ» به معنای اجبار نیست؛ مانند این‌که گفته شود فلان شخص در خدمت پدر و مادر، مثل اسیر است. در واقع او اسیر نیست، بلکه معتقد است که رام و تسلیم پدر و مادر است.\n«وَلَیْسَ فِی أَطْباقِ السَّماءِ مَوْضِعُ إِهابٍ إِلَّا عَلَیْهِ مَلَک ساجِدٌ أَوْ ساعٍ حافِدٌ»\nدر سراسر طبقات آسمان، به اندازهٔ پوست حیوانی [إِهاب] جای خالی یافت نمی‌شود، مگر این‌که بر آن فرشته‌ای در سجده باشد یا فرشته‌ای در حال تلاش و رفت‌وآمد [ساعٍ] باشد.\n«یَزْدادُونَ عَلی طُولِ الطّاعَةِ بِرَبِّهِمْ عِلْماً»\nبه سبب طول عبادت، علم آنان به پروردگار بیشتر می‌شود.\n«وَتَزْدادُ عِزَّةُ رَبِّهِمْ فِی قُلُوبِهِمْ عِظَماً»\nو عبادت طولانی باعث می‌شود عزت و جلال خدا در دل آنان بزرگ‌تر شود.\nدو اثر عبادت طولانی:\n۱- موجب علم می‌شود.\n۲- خدا را در چشم عابد بزرگ می‌کند [فِی قُلُوبِهِمْ عِظَماً].\nعلم فقط باکلاس رفتن و درس‌خواندن به دست نمی‌آید.\nخداوند در برابر تقوا، علم ذاتی و علم لدنی عطا می‌کند:\n«اتَّقُوا اللَّهَ وَیُعَلِّمُکُمُ اللَّهُ»\nاین علم، علم به حقایق امور است؛ چیزی نیست که فقط توصیف شود، بلکه باید چشیده شود.\nبسیاری از علوم، در گرو گناه‌نکردن است.\n«لا یَمَسُّهُ إِلَّا الْمُطَهَّرُونَ»\nاگر روح انسان طهارت و تقوا نداشته باشد، اجازهٔ دسترسی نمی‌دهند. علم قرآن را به اهل تطهیر می‌دهند.\nرابطهٔ میان بیشتر خواندن و بالاتر رفتن فهم، رابطه‌ای قطعی نیست؛ بلکه تقواست که فهم و علم را بیشتر می‌کند.\nچه‌بسا بی‌سوادان و کم‌سوادانی که دارای علم و فهم بالا شدند؛ مانند مرحوم دولابی و دیگران.\nاللَّهُمَّ اجْعَلْنَا مِنَ الْمُتَّقِینَ، وَأَلْحِقْنَا بِالصَّالِحِینَ.","بخش نهم\nمتن:\nفي صفة الأرض و دَحوُها على الماء:\nكَبَسَ الْأَرْضَ عَلَى مَوْرِ أَمْوَاجٍ مُسْتَفْحِلَةٍ وَ لُجَجِ بِحَارٍ زَاخِرَةٍ، تَلْتَطِمُ أَوَاذِيُّ أَمْوَاجِهَا وَ تَصْطَفِقُ مُتَقَاذِفَاتُ أَثْبَاجِهَا وَ تَرْغُو زَبَداً كَالْفُحُولِ عِنْدَ هِيَاجِهَا، فَخَضَعَ جِمَاحُ الْمَاءِ الْمُتَلَاطِمِ لِثِقَلِ حَمْلِهَا وَ سَكَنَ هَيْجُ ارْتِمَائِهِ إِذْ وَطِئَتْهُ‏ بِكَلْكَلِهَا وَ ذَلَّ مُسْتَخْذِياً إِذْ تَمَعَّكَتْ عَلَيْهِ بِكَوَاهِلِهَا فَأَصْبَحَ بَعْدَ اصْطِخَابِ أَمْوَاجِهِ سَاجِياً مَقْهُوراً وَ فِي حَكَمَةِ الذُّلِّ مُنْقَاداً أَسِيراً وَ سَكَنَتِ الْأَرْضُ مَدْحُوَّةً فِي لُجَّةِ تَيَّارِهِ وَ رَدَّتْ مِنْ نَخْوَةِ بَأْوِهِ وَ اعْتِلَائِهِ وَ شُمُوخِ أَنْفِهِ وَ سُمُوِّ غُلَوَائِهِ وَ كَعَمَتْهُ عَلَى كِظَّةِ جَرْيَتِهِ فَهَمَدَ بَعْدَ نَزَقَاتِهِ وَ لَبَدَ بَعْدَ زَيَفَانِ وَثَبَاتِهِ، فَلَمَّا سَكَنَ هَيْجُ الْمَاءِ مِنْ تَحْتِ أَكْنَافِهَا وَ حَمَلَ شَوَاهِقَ الْجِبَالِ الشُّمَّخِ الْبُذَّخِ عَلَى أَكْتَافِهَا فَجَّرَ يَنَابِيعَ الْعُيُونِ مِنْ عَرَانِينِ أُنُوفِهَا وَ فَرَّقَهَا فِي سُهُوبِ بِيدِهَا وَ أَخَادِيدِهَا وَ عَدَّلَ حَرَكَاتِهَا بِالرَّاسِيَاتِ مِنْ جَلَامِيدِهَا وَ ذَوَاتِ الشَّنَاخِيبِ الشُّمِّ مِنْ صيَاخِيدِهَا فَسَكَنَتْ مِنَ الْمَيَدَانِ لِرُسُوبِ الْجِبَالِ فِي قِطَعِ أَدِيمِهَا وَ تَغَلْغُلِهَا مُتَسَرِّبَةً فِي جَوْبَاتِ خَيَاشِيمِهَا وَ رُكُوبِهَا أَعْنَاقَ سُهُولِ الْأَرَضِينَ وَ جَرَاثِيمِهَا وَ فَسَحَ بَيْنَ الْجَوِّ وَ بَيْنَهَا وَ أَعَدَّ الْهَوَاءَ مُتَنَسَّماً لِسَاكِنِهَا وَ أَخْرَجَ إِلَيْهَا أَهْلَهَا عَلَى تَمَامِ مَرَافِقِهَا.\n ثُمَّ لَمْ يَدَعْ جُرُزَ الْأَرْضِ الَّتِي تَقْصُرُ مِيَاهُ الْعُيُونِ عَنْ رَوَابِيهَا وَ لَا تَجِدُ جَدَاوِلُ الْأَنْهَارِ ذَرِيعَةً إِلَى بُلُوغِهَا حَتَّى أَنْشَأَ لَهَا نَاشِئَةَ سَحَابٍ تُحْيِي مَوَاتَهَا وَ تَسْتَخْرِجُ نَبَاتَهَا أَلَّفَ غَمَامَهَا بَعْدَ افْتِرَاقِ لُمَعِهِ وَ تَبَايُنِ قَزَعِهِ حَتَّى إِذَا تَمَخَّضَتْ لُجَّةُ الْمُزْنِ فِيهِ وَ الْتَمَعَ بَرْقُهُ فِي كُفَفِهِ وَ لَمْ يَنَمْ وَمِيضُهُ فِي كَنَهْوَرِ رَبَابِهِ وَ مُتَرَاكِمِ سَحَابِهِ أَرْسَلَهُ سَحّاً مُتَدَارِكاً قَدْ أَسَفَّ هَيْدَبُهُ [يَمْرِي‏] تَمْرِيهِ الْجَنُوبُ دِرَرَ أَهَاضِيبِهِ وَ دُفَعَ شَآبِيبِهِ. فَلَمَّا أَلْقَتِ السَّحَابُ بَرْكَ بِوَانَيْهَا وَ بَعَاعَ مَا اسْتَقَلَّتْ بِهِ مِنَ الْعِبْ‏ءِ الْمَحْمُولِ عَلَيْهَا أَخْرَجَ بِهِ مِنْ هَوَامِدِ الْأَرْضِ النَّبَاتَ وَ مِنْ زُعْرِ الْجِبَالِ الْأَعْشَابَ فَهِيَ تَبْهَجُ بِزِينَةِ رِيَاضِهَا وَ تَزْدَهِي بِمَا أُلْبِسَتْهُ مِنْ رَيْطِ أَزَاهِيرِهَا وَ حِلْيَةِ مَا سُمِطَتْ بِهِ مِنْ نَاضِرِ أَنْوَارِهَا وَ جَعَلَ ذَلِكَ بَلَاغاً لِلْأَنَامِ وَ رِزْقاً لِلْأَنْعَامِ وَ خَرَقَ الْفِجَاجَ فِي آفَاقِهَا وَ أَقَامَ الْمَنَارَ لِلسَّالِكِينَ عَلَى جَوَادِّ طُرُقِهَا.\nترجمه:\nزمين را بر روى امواج پرهيجان و درياهاى مملو از آب قرار داد، امواجى که قسمتهاى بالاى آن متلاطم بود و پيوسته به هم مى خورد، و لايه اى از کف - همانند کفهاى دهان شتر به هنگام مستى - بر روى آنها پديد آمد. (سپس) قسمتهاى سرکش آب پر تلاطم بر اثر سنگينى خضوع نمود، و هيجان آن به سبب تماس با سينه زمين فرو نشست، و کاملا تسليم و رام شد; چرا که زمين بر آن مى غلتيد و به اين ترتيب آبها بعد از آن همه سر و صدا که بر اثر امواج خروشان پيدا شده بود، آرام شد و همچون اسب افسار شده اى اسير و رام گشت و زمين نيز آرام شد و (خشکيها) از دل امواج تدريجاً ظاهر و گسترده گشت، آب را از کبر و غرور و هيجان بى حدّ باز داشت و از شدّت حرکاتش کاست و بعد از آن همه جوش و خروش (کاملا) آرام شد و پس از آن همه جست و خيز متکبّرانه، به جاى خود ايستاد.\nهنگامى که هيجان آب در اطراف زمين فرو نشست، و زمين کوه هاى سخت و مرتفع را بر دوش خود حمل کرد، چشمه هاى آب را از بينى کوه ها جارى ساخت; و آن را در دشت هاى گسترده و گودال ها (و بستر رودخانه ها) پراکنده و جارى نمود و حرکات زمين را با صخره هاى عظيم و قلّه هاى بلند و استوار کوه ها تعديل کرد، و بدين ترتيب، لرزشهاى زمين به جهت نفوذ کوه ها در سطح آن و فرو رفتن ريشه هاى آن در اعماق زمين و سوار شدن آن ها بر گردن دشت ها و اعماق آن از لرزش و اضطراب باز ايستاد و خداوند ميان زمين و جوّ فاصله افکند، نسيم هوا را براى ساکنان زمين آماده ساخت و تمام نيازمندى ها و وسايل زندگى را براى اهل آن فراهم نمود.\nسپس خداوند هيچ يک از بلندى هاى زمين را که آب چشمه ها به نقاط مرتفع آن نمى رسد و جدول هاى نهرها به آن راه ندارد، به حال خود وانگذاشت; بلکه (براى آبيارى آنها) ابرهايى آفريد تا قسمتهاى مرده زمين را زنده کند و گياهان آن را بروياند. خداوند قطعات درخشنده و پراکنده و جداى ابرها را به هم پيوست و درياهايى از آب که در ابرها نهفته بود سخت به حرکت درآمد (و آماده نزول شد).\nبرق، در اطراف آن درخشيدن گرفت و از درخشندگى آن، در ابرهاى سفيد کوه پيکر و متراکم چيزى کاسته نشد; (و همچنان ادامه يافت) اين در حالى بود که ابرها (از شدّت سنگينى) به زمين نزديک شده بودند; در اين هنگام باد جنوب، باران را همچون شيرى از پستان حيوان بدوشيد و به شدّت بر زمين فرو ريخت هنگامى که ابرها سينه بر زمين نهادند و آبهاى فراوانِ سنگينى را که بر دوش داشتند، فرو ريختند، خداوند به وسيله آن از زمين هاى خشک و بى گياه، نباتات فراوانى رويانيد و از دامنه کوههاى کم گياه، سبزه بسيار خارج ساخت و زمين به زيور باغهايش غرق نشاط و شادى شد و با لباس نازک گلبرگها که بر خود پوشيده بود به ناز آمد، و از زينت و زيورى که از گردنبند گل هاى گوناگون يافته بود در وجد و شادى فرو رفت! و همه اينها را غذا وتوشه انسانها، و روزى چهارپايان قرار داد، در اطراف زمين (و در ميان کوهها) درّه ها و راههاى وسيعى شکافت و نشانه ها - براى آنان که بخواهند از شاهراه هاى وسيعش بگذرند - قرار داد.\nتفسیر:\nچگونگی پیدایش زمین؛ دَحوُالأرض\nکَبَسَ الْأَرْضَ عَلَی مَوْرِ أَمْوَاجٍ مُسْتَفْحِلَةٍ وَ لُجَجِ بِحَارٍ زَاخِرَةٍ تَلْتَطِمُ أَوَاذِی أَمْوَاجِهَا وَ تَصْطَفِقُ مُتَقَاذِفَاتُ أَثْبَاجِهَا وَ تَرْغُو زَبَدًا کالْفُحُولِ عِنْدَ هِیاجِهَا\nخداوند زمین را بر مَوْرِ اضطراب امواج خروشان قرارداد.\nدر خطبهٔ یک، حضرت مجموعه‌ای از آب را بیان فرمودند که برخی آن را بخار و دود دانسته‌اند.\nدر این جوش‌وخروش، مواد مذاب که بیشتر از چند صدهزار تن بودند، با جوش و غلیان به هر طرف پرتاب شدند. یکی از این قسمت‌های پرتاب‌شده، همین زمین است؛ گوی گردی که بر جوششی از مواد مذاب قرار گرفت. موج‌هایی عظیم و سرشار از آب مذاب وجود داشت که به‌خاطر غلظت، به یکدیگر ضربه می‌زدند. دورتادور این آب مذاب را کف فراگرفته بود؛ مانند حیوان مستی که در اوج مستی و شهوت، کف اطراف دهانش را می‌گیرد.\nفَخَضَعَ جِمَاحُ الْمَاءِ الْمُتَلَاطِمِ لِثِقَلِ حَمْلِهَا وَ سَکنَ هَیجُ ارْتِمَائِهِ إِذْ وَطِئَتْهُ بِکلْکلِهَا وَ ذَلَّ مُسْتَخْذِیا إِذْ تَمَعَّکتْ عَلَیهِ بِکوَاهِلِهَا فَأَصْبَحَ بَعْدَ اصْطِخَابِ أَمْوَاجِهِ سَاجِیا مَقْهُورًا وَ فِی حَکمَةِ الذُّلِّ مُنْقَادًا أَسِیرًا\nآرام‌آرام، سنگینی این شیء باعث شد خروش آب کاهش یابد؛ گویی بار سنگینی، مانند سینهٔ شتر، بر مواد مذاب قرار گرفت و دیگر اجازهٔ جوش‌وخروش به آن نداد. سنگینی زمین، این آب‌های خروشان را مانند کشتی‌گیرانی که شانه‌هایشان بر خاک ساییده شده است، در جای خود آرام کرد. حالت مذاب و سیال آن به ماده‌ای سخت تبدیل شد. این آب‌های خروشان، مانند حیوانی که لجام و افسار زده‌اند، آرام گرفتند.\nوَ سَکنَتِ الْأَرْضُ مَدْحُوَّةً فِی لُجَّةِ تَیارِهِ وَ رَدَّتْ مِنْ نَخْوَةِ بَأْوِهِ وَ اعْتِلَائِهِ وَ شُمُوخِ أَنْفِهِ وَ سُمُوِّ غُلَوَائِهِ وَ کعَمَتْهُ عَلَی کظَّةِ جَرْیتِهِ فَهَمَدَ بَعْدَ نَزَقَاتِهِ وَ لَبَدَ بَعْدَ زَیفَانِ وَثَبَاتِهِ فَلَمَّا سَکنَ هَیجُ الْمَاءِ مِنْ تَحْتِ أَکنَافِهَا\nزمین در دل این موج‌های پرتلاطم گسترش یافت (مَدْحُوَّةً).\nخداوند این آب‌ها را از نخوت، کبر و خودبزرگ‌بینی بازداشت و فرمود: دیگر بلندپروازی نکنید؛ اکنون زمان آرام‌گرفتن است.\nگاهی علوم، مطالبی را اثبات می‌کنند و گاهی نیز هنوز به آن دست نیافته‌اند. آنچه حضرت می‌فرماید، حق و مسلم است.\nوقتی از این مراحل سخن گفته می‌شود، منظور میلیاردها سال است؛ به‌گونه‌ای که گاهی دانشمندان قدمت آن را تا پانزده میلیارد سال نیز تخمین زده‌اند.\nدر خطبهٔ یک نیز حضرت می‌فرمایند: تودهٔ عظیمی که پروردگار خلق کرد، آبی بود که در زیر آن هوا قرار داشت و از بالا، بادی می‌وزید که آن را به خروش می‌آورد. این برخوردها باعث جوشیدن مواد مذاب شد و هرکدام از تکه‌ها به جایی پرتاب شدند. هرکدام در دایره‌ای که خدا تعیین کرده بود قرار گرفتند و همین کهکشانی که می‌بینیم، ایجاد شد.\nچه شد که این مواد مذاب آرام گرفتند؟\nدو پاسخ وجود دارد:\n۱. نظریهٔ طول زمان\nچون میلیاردها سال گذشت، لایه‌های نزدیک به سطح، در مجاورت هوا سرد شدند و این امر باعث شد مواد مذاب به سنگ یا لایه‌های بیرونی زمین تبدیل شوند.\n۲. نظریهٔ بارش باران‌های دائمی\nمیلیاردها سال، باران‌های سیل‌آسا بر زمین بارید؛ آن‌قدر بارید که سراسر زمین را آب فراگرفت. آرام‌آرام دحوالأرض شکل گرفت. برخی از زمین‌ها از زیر آب بیرون آمدند و فضا برای اسکان آدمیان فراهم شد.\nحَمَلَ شَوَاهِقَ الْجِبَالِ الشُّمَّخِ الْبُذَّخِ عَلَی أَبِیذِهَا وَ أَخَادِیدِهَا وَ عَدَّلَ حَرَکاتِهَا بِالرَّاسِیاتِ مِنْ جَلَامِیدِهَا وَ ذَوَاتِ الشَّنَاخِیبِ الشُّمِّ مِنْ صَیاخِیدِهَا فَسَکنَتْ مِنَ الْمَیدَانِ لِرُسُوبِ الْجِبَالِ فِی قِطَعِ أَدِیمِهَا وَ تَغَلْغُلِهَا مُتَسَرِّبَةً فِی جَوْبَاتِ خَیاشِیمِهَا وَ رُکوبِهَا أَعْنَاقَ سُهُولِ الْأَرَضِینَ وَ جَرَاثِیمِهَا\nوقتی آب از هیجان ایستاد و اطراف آن آرام گرفت، خداوند کوه‌های سنگین و سر به فلک کشیده را بر دوش زمین قرارداد. این کوه‌ها از سوی خدا مأمور بودند که به زمین آرامش بدهند و صفحات زمین را از حرکت‌های اضافی حفظ کنند. پس از آن، چشمه‌هایی از میان‌کوه‌ها، یعنی (عَرَانِینِ) که کنایه از قله یا نزدیک قله است، جاری شدند.\nخداوند آب‌ها را در سرزمین‌های هموار، بیابان‌ها، فلات‌ها و دره‌ها گستراند. رشته‌کوه‌های سر به فلک کشیده و صخره‌های سختی را قرارداد که دست‌بردن در آن‌ها به‌آسانی ممکن نیست.\nاین کوه‌ها در حوزه‌های درون زمین فرورفته‌اند (تَغَلْغُلِهَا) و در پهنهٔ دشت‌ها و اعماق زمین قرار گرفته‌اند؛ به‌گونه‌ای که اگر چنین نبود، آرامش برقرار نمی‌شد. انتهای کوه‌های آتشفشانی در عمق زمین نفوذ دارد.\nحضرت به‌گونه‌ای سخن می‌فرمایند که گویی در هنگام ایجاد این پدیده‌ها حضور داشته‌اند. نور حضرت پیامبر صلی‌الله علیه و آله و حضرت علی علیه‌السلام، پیش از خلقت آسمان و زمین وجود داشته است.\nحضرت رسول صلی‌الله علیه و آله فرمودند:\n«أَوَّلُ مَا خَلَقَ اللَّهُ نُورِی فَفَتَقَ مِنْهُ نُورَ عَلِی ثُمَّ خَلَقَ الْعَرْشَ وَ اللَّوْحَ وَ الشَّمْسَ وَ ضَوْءَ النَّهَارِ وَ نُورَ الْأَبْصَارِ وَ الْعَقْلَ وَ الْمَعْرِفَةَ الْخَبَرَ»\nبحارالانوار\nوَ فَسَحَ بَینَ الْجَوِّ وَ بَینَهَا وَ أَعَدَّ الْهَوَاءَ مُتَنَسَّمًا لِسَاکنِهَا وَ أَخْرَجَ إِلَیهَا أَهْلَهَا عَلَی تَمَامِ مَرَافِقِهَا\nخدای متعال میان زمینی که ما در آن قرار داریم و جوّ بالای سرمان، فاصله‌ای ایجاد کرد (فَسَحَ).\nمیان زمین و لایهٔ اوزون، هوا را برای تنفس (مُتَنَسَّمًا) قرارداد.\nپس از پایان این مراحل، به انسان‌فرمان داد که بر روی زمین زندگی کند؛ درحالی‌که زمین و هرآنچه را برای زندگی به آن نیاز دارد، در اختیارش قرار داده است.\nاین مطلب، یک برهان است بر این‌که خداوند هیچ‌گاه کاری را که انجام‌دادنش ممکن نیست، بر عهدهٔ انسان نمی‌گذارد؛ بلکه شرایط و امکانات لازم را فراهم می‌کند.\nپس تا زمانی که سلامت و عقل داری، به انجام تکلیف نیز ملزمی و پس از آن، هیچ عذری پذیرفته نیست.\nثُمَّ لَمْ یدَعْ جُرُزَ الْأَرْضِ الَّتِی تَقْصُرُ مِیاهُ الْعُیونِ عَنْ رَوَابِیهَابلوغ‌هاَا تَجِدُ جَدَاوِلُ الْأَنْهَارِ ذَرِیعَةً إِلَی بُلُوغِهَا حَتَّی أَنْشَأَ لَهَا نَاشِئَةَ سَحَابٍ تُحْیی مَوَاتَهَا وَ تَسْتَخْرِجُ نَبَاتَهَا أَلَّفَ غَمَامَهَا بَعْدَ افْتِرَاقِ لُمَعِهِ وَ تَبَاینِ قَزَعِهِ حَتَّی إِذَا تَمَخَّضَتْ لُجَّةُ الْمُزْنِ فِیهِ\nخداوند قسمت‌هایی از زمین را که بلند و قله‌دار بودند و معمولاً آب چشمه به آن‌ها نمی‌رسید یا امکان جدول‌کشی و هدایت آب رودخانه‌ها به آن‌ها وجود نداشت، رها نکرد؛ بلکه ابرهایی ایجاد کرد که زمین مرده را زنده می‌کردند و گیاهان نهفتهٔ زمین را بیرون می‌آوردند.\nاو ابرها را پس از آنکه تکه‌تکه بودند، یکپارچه و با یکدیگر مأنوس کرد (أَلَّفَ غَمَامَهَا). این ابرهای کوچک، در گوشه‌وکنار پراکنده بودند.\nحَتَّی إِذَا تَمَخَّضَتْ لُجَّةُ الْمُزْنِ فِیهِ وَ الْتَمَعَ بَرْقُهُ فِی کفَفِهِ وَ لَمْ ینَمْ وَمِیضُهُ فِی کنَهْوَرِ رَبَابِهِ وَ مُتَرَاکمِ سَحَابِهِ أَرْسَلَهُ سَحًّا مُتَدَارِکا قَدْ أَسَفَّ هَیدَبُهُ تَمْرِیهِ الْجَنُوبُ دِرَرَ أَهَاضِیبِهِ وَ دُفَعَ شَآبِیبِهِ\nتا این‌که ابرها به‌شدت به حرکت درآمدند و آب فراوانی در آن‌ها جمع شد. خداوند نیز رعدوبرق را به ابرها افزود.\nرعدوبرق خلأ و فاصلهٔ میان قطره‌ها را برطرف می‌کند و بر اثر غرش شدید آن، قطره‌ها به یکدیگر می‌پیوندند. هیچ‌گاه نورانیت این ابر متراکم خاموش نشد.\nخدای متعال آب‌های ازهم‌گسیخته را در قالب ابری یکپارچه (مُتَدَارِکا) گرد آورد. این ابر، به دلیل وزن زیاد، از ارتفاع پایین آمد و به زمین نزدیک شد.\nباد جنوب که به سمت شمال می‌وزد ــ و اغلب همین باد جنوب است که باران‌ها را فراهم می‌کند ــ بارانی را که درون ابر است می‌دوشد و باران شدیدی از این ابرها بر زمین می‌ریزد (دُفَعَ شَآبِیبِهِ).\nأَلْقَتِ السَّحَابُ بَرْک بِوَانِیهَا وَ بَعَاعَ مَا اسْتَقَلَّتْ بِهِ مِنَ الْعِبْءِ الْمَحْمُولِ عَلَیهَا أَخْرَجَ بِهِ مِنْ هَوَامِدِ الْأَرْضِ النَّبَاتَ وَ مِنْ زُعْرِ الْجِبَالِ الْأَعْشَابَ\nوقتی ابر سنگین شد، سینه‌اش را به زمین نزدیک کرد؛ گویی زمان وضع‌حمل فرارسیده است. سپس باران را مانند کودکی که در آغوش گرفته شده است، بر زمین فروریخت.\nفَهِی تَبْهَجُ بِزِینَةِ رِیاضِهَا وَ تَزْدَهِی بِمَا أُلْبِسَتْهُ مِنْ رَیطِ أَزَاهِیرِهَا وَ حِلْیةِ مَا سُمِطَتْ بِهِ مِنْ نَاضِرِ أَنْوَارِهَا وَ جَعَلَ ذَلِک بَلَاغًا لِلْأَنَامِ وَ رِزْقًا لِلْأَنْعَامِ وَ خَرَقَ الْفِجَاجَ فِی آفَاقِهَا وَ أَقَامَ الْمَنَارَ لِلسَّالِکینَ عَلَی جَوَادِّ طُرُقِهَا\nهمین زمین خشک و لم‌یزرع، به‌محض سیراب‌شدن، شاهدرویش گیاهان سبز می‌شود.\nزمین تا زمانی که سرسبز نباشد، افسرده است؛ اما همین که سرسبز می‌شود و گل‌های متنوع در آن می‌رویند و باغ‌های زمین فراوان می‌شوند، بهجت و شادی می‌یابد و به لباسی که خداوند بر آن پوشانده است، کرشمه می‌کند.\nنشاط زمین به سرسبزی آن است. نشاط محله نیز به سرسبزی آن است و ما انسان‌های روی زمین نیز با سرزندگی زمین، سرزنده می‌شویم.\nاین فراز نهج‌البلاغه را می‌توان به‌عنوان تبیینی از کیفیت رابطهٔ انسان و محیط‌زیست مطرح کرد. انسان باید کاری کند که فضای سبز افزایش یابد. زمین با پوشیدن لباس گل‌دار و آویختن گردن‌بندی از گلبرگ‌های گوناگون بر گردن خود، سرخوش می‌شود.\nچرا خداوند آسمان و زمین را خلق کرد؟\nخداوند همهٔ این آسمان و زمین را آفرید تا انسان از نعمت طعام و لذت بهره‌مند شود، به اهداف خود برسد و گل‌ها و گیاهان نیز غذای حیوانات شوند؛ حیواناتی که آن‌ها هم می‌توانند برای انسان سودمند باشند.\nنکته\nخدایی که این مواد مذاب را میلیاردها سال آرام کرد، ما را نیز می‌تواند به‌طورقطع و یقین آرام کند؛ به‌شرط آنکه ما هم مانند آسمان و زمین، مطیع فرمان خدا باشیم.\nغَفَرَ اللَّهُ لِی وَ لَکمْ، وَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِینَ","بخش دهم\nمتن:\nفَلَمَّا مَهَدَ أَرْضَهُ وَ أَنْفَذَ أَمْرَهُ اخْتَارَ آدَمَ (علیه السلام) خِيرَةً مِنْ خَلْقِهِ وَ جَعَلَهُ أَوَّلَ جِبِلَّتِهِ وَ أَسْكَنَهُ جَنَّتَهُ وَ أَرْغَدَ فِيهَا أُكُلَهُ وَ أَوْعَزَ إِلَيْهِ فِيمَا نَهَاهُ عَنْهُ، وَ أَعْلَمَهُ أَنَّ فِي الْإِقْدَامِ عَلَيْهِ التَّعَرُّضَ لِمَعْصِيَتِهِ وَ الْمُخَاطَرَةَ بِمَنْزِلَتِهِ، فَأَقْدَمَ عَلَى مَا نَهَاهُ عَنْهُ مُوَافَاةً لِسَابِقِ عِلْمِهِ، فَأَهْبَطَهُ بَعْدَ التَّوْبَةِ لِيَعْمُرَ أَرْضَهُ بِنَسْلِهِ وَ لِيُقِيمَ الْحُجَّةَ بِهِ عَلَى عِبَادِهِ؛ وَ لَمْ يُخْلِهِمْ بَعْدَ أَنْ قَبَضَهُ مِمَّا يُؤَكِّدُ عَلَيْهِمْ حُجَّةَ رُبُوبِيَّتِهِ وَ يَصِلُ بَيْنَهُمْ وَ بَيْنَ مَعْرِفَتِهِ، بَلْ تَعَاهَدَهُمْ بِالْحُجَجِ عَلَى أَلْسُنِ الْخِيَرَةِ مِنْ أَنْبِيَائِهِ وَ مُتَحَمِّلِي وَدَائِعِ رِسَالاتِهِ قَرْناً فَقَرْناً، حَتَّى تَمَّتْ بِنَبِيِّنَا مُحَمَّدٍ (صلی الله علیه وآله)‏ حُجَّتُهُ وَ بَلَغَ الْمَقْطَعَ عُذْرُهُ وَ نُذُرُهُ.\nوَ قَدَّرَ الْأَرْزَاقَ، فَكَثَّرَهَا وَ قَلَّلَهَا وَ قَسَّمَهَا عَلَى الضِّيقِ وَ السَّعَةِ، [فَعَدَّلَ‏] فَعَدَلَ فِيهَا لِيَبْتَلِيَ مَنْ أَرَادَ بِمَيْسُورِهَا وَ مَعْسُورِهَا وَ لِيَخْتَبِرَ بِذَلِكَ الشُّكْرَ وَ الصَّبْرَ مِنْ غَنِيِّهَا وَ فَقِيرِهَا، ثُمَّ قَرَنَ بِسَعَتِهَا عَقَابِيلَ فَاقَتِهَا وَ بِسَلَامَتِهَا طَوَارِقَ آفَاتِهَا وَ بِفُرَجِ أَفْرَاحِهَا غُصَصَ أَتْرَاحِهَا، وَ خَلَقَ الْآجَالَ فَأَطَالَهَا وَ قَصَّرَهَا وَ قَدَّمَهَا وَ أَخَّرَهَا، وَ وَصَلَ بِالْمَوْتِ أَسْبَابَهَا وَ جَعَلَهُ خَالِجاً لِأَشْطَانِهَا وَ قَاطِعاً لِمَرَائِرِ أَقْرَانِهَا.\nترجمه:\nهنگامى که (خداوند) زمين را آماده ساخت و فرمان خويش را (در تمام جهات) نافذ کرد، آدم را از ميان تمام مخلوقاتش برگزيد، و او را نخستين و برترين آفريده، خويش قرار داد; او را در بهشت خود ساکن کرد و غذاهاى فراوان و گوارا را در اختيارش نهاد و (در عين حال) قبلا از آنچه ممنوعش کرده بود وى را بر حذر داشت، و آگاهش ساخت که اقدام بر آن (و تناول از درخت ممنوع) سبب عصيان و نافرمانى او خواهد بود و مقام و منزلتش را به خطر خواهد افکند! ولى آدم اقدام بر آن چيزى که از آن نهى شده بود کرد و علم خداوند درباره او به وقوع پيوست; به همين جهت، او را پس از توبه از بهشت فرو فرستاد تا با کمک نسل خود زمين را آباد سازد و حجّت را بر بندگانش اقامه کند;\nو بعد از از مرگ آدم، بندگان را از حجّت بر ربوبيّتش خالى نگذاشت و ميان فرزندان آدم و معرفت خويش پيوندى برقرار ساخت و قرن به قرن، حجت ها و دليل ها را بر زبان پيامبران برگزيده و حاملان ودايع رسالت خويش براى آنها اقامه نمود، سرانجام به وسيله پيامبر ما محمّد(صلى الله عليه وآله) حجتش تمام شد (و سلسله پيامبران ختم گرديد) و بيان احکام و انذار و (بشارت) به آخر رسيد.\nخداوند روزى ها را مقدّر کرد و اندازه گيرى فرمود; گاه آن را زياد و گاه کم نمود، گاه با تنگى و گاه با وسعت روزى را تقسيم کرد و (در عين حال) عدالت را در آن رعايت فرمود، و هدف از آن تقسيم، اين بود که هر کس را بخواهد با وسعت روزى يا تنگى آن بيازمايد و به وسيله آن، شکر و صبر غنى و فقير را آزمايش کند. سپس روزىِ وسيع را با فقر و بيچارگى درآميخت، تندرستى را با حوادث دردناک توأم ساخت، و شادى و سرور را با غصّه و اندوه قرين کرد.\nسرآمدِ عمر را آفريد; آن را گاه طولانى و گاه کوتاه قرار داد و گاه مقدّم و گاه موخّر داشت و سرانجام مرگ را با عوامل پايان عمر پيوند داد و با آن، رشته هاى طولانى حيات را درهم پيچيد و پيوندهاى محکم زندگىِ (توانمندان) را قطع کرد.\nتفسیر:\nآمادگی زمین برای خلق آدم\nخلاصهٔ درس قبل:\nخدای متعال زمین را خلق کرد. خشکی‌ها از زیر آب بیرون آمدند. کوه‌ها سر برافراشتند. رودخانه‌ها جاری شدند. در میانهٔ این کوه‌ها دره‌هایی قرارداد.\nو نشانه‌هایی برای آنان که بخواهند از جاده‌های وسیع آن عبور کنند، تعیین کرد.\nنشانه‌هایی قرارداد تا اگر کسی خواست از این کوه‌ها عبور کند، سرگردان نشود.\nنکتهٔ اول:\nتصور کنید کوه‌ها و رشته‌کوه‌ها هیچ راه عبوری نداشتند و مانند سدّی بزرگ، زمین را به دو قسمت تقسیم می‌کردند. اوّلاً، این امر چقدر باعث تفرقهٔ انسان‌ها می‌شد و جدایی میان شهرها و روستاها پدید می‌آورد. ثانیاً، حرکت آب مختل می‌شد و سرزمین‌های پایین‌دست از آب بی‌بهره می‌ماندند.\nخدای متعال کوه را با همهٔ مزایا و خواصی که دارد، ایجاد نمود؛ ولی درعین‌حال، کوه برای انسان خلق شد؛ ازاین‌رو راه‌هایی در میانهٔ این کوه‌ها قرارداد تا انسان به‌راحتی رفت‌وآمد کند.\nنکتهٔ دوم:\nدر این کوه‌ها نشانه‌هایی قرارداد تا راه را پیدا کنند. کوهنوردان، ظاهر کوه‌ها را شبیه یکدیگر نمی‌بینند و تفاوت‌های آن‌ها را با یکدیگر به‌خوبی می‌شناسند. کوه‌ها شکل‌های مختلف و جنس‌های گوناگون دارند و این خود نشانه‌ای است تا انسان‌ها بتوانند مسیرهای مختلف و شهرهای گوناگون را به سبب همین کوه‌ها بشناسند و راه را پیدا کنند.\nفَلَمَّا مَهَّدَ أَرْضَهُ\nهنگامی که خداوند زمین را برای زندگی انسان آماده ساخت.\nوَ أَنْفَذَ أَمْرَهُ\nو فرمان خود را صادر فرمود.\nخداوند متعال زمین را آماده کرد و فرمان خود را نافذ ساخت و هرچه دستور داد، دستورش اجرا شد و همهٔ این مقدمات فراهم گردید تا این‌که:\nاخْتَارَ آدَمَ خِیرَةً مِنْ خَلْقِهِ\nآدم علیه‌السلام را از میان مخلوقاتش برگزید.\nخدای متعال جناب آدم علیه‌السلام را به‌عنوان مخلوقی برگزیده اختیار کرد.\nوَ جَعَلَهُ أَوَّلَ جِبِلَّتِهِ\nو او را نخستین سرشت و آفرینش خود در زمین قرارداد.\nنخستین کسی که خلق شد تا بر روی زمین بیاید و نخستین انسانی که در قالب جسم بود و جسم او برای دنیا خلق شد، جناب آدم علیه‌السلام بود.\nاز نکات مهم این است که حضرت می‌فرمایند: کنْتُ صَدَّقْتُهُ وَ آدَمُ بَینَ الْمَاءِ وَ الطِّینِ: من پیامبر خدا صلی‌الله علیه و آله را تصدیق کردم و به نبوّت او اعتراف و اعتقاد داشتم، درحالی‌که خدای متعال گل آدم را می‌سرشت. وجود مقدّس پیامبر صلی‌الله علیه و آله و اهل‌بیت علیهم‌السلام، همه پیش از حضرت آدم علیه‌السلام بودند.\nشبهه: آیا انسان، تکامل‌یافتهٔ مخلوقات دیگر است؟\nپاسخ: در مکتب حضرت، انسان مخلوق خاص خداست. پرورش‌یافته و تکامل‌یافتهٔ مخلوقات دیگر نیست. انسان، انسان خلق شده است.\nوَ أَسْکنَهُ جَنَّتَهُ\nابتدا آدم علیه‌السلام را در بهشت جای داد.\nمیان مفسّران اختلاف است و سؤال این است که بهشتی که خدای متعال انسان را در آن جای داد، چگونه بهشتی بود؟\nعده‌ای اعتقاد دارند که آن بهشت، همان بهشت خلد برین بود که خدا وعده داده است؛ ولی از ظاهر کلمات اهل‌بیت علیهم‌السلام استفاده می‌شود که این جنت، معنای باغ و بوستان می‌دهد و دنیایی بود. آیات «خالِدِینَ فِیهَا أَبَدًا» و «وَ ما هُمْ بِخارِجِینَ مِنْها» در قرآن کریم دلالت بر این دارد که بهشت خلد برین جاودانه است و کسی از آن خارج نمی‌شود. به همین دلیل، بهشتی که آدم علیه‌السلام در آن سکنا گزید، بهشت جاویدان نبود. ضمن این‌که شیطان به بهشت خلد برین راه ندارد. پس بهشتی که آدم علیه‌السلام در آن ساکن بود، بهشتی دنیایی بود.\nوَ أَرْغَدَ فِیهَا أُکلَهُ\nو خوراکی‌های گوارا به او بخشید.\nهرچه می‌خواهید بخورید.\nوَ أَوْعَزَ إِلَیهِ فِیمَا نَهَاهُ عَنْهُ\nو او را از آنچه نهی کرده بود، برحذر داشت.\nبا اشاره به جناب آدم علیه‌السلام فهماند و امر کرد که همه چیز مجاز است، به‌جز آن چیزی که از آن منع شده‌اید. با استفاده از قرآن کریم معلوم می‌شود که منظور حضرت، شجرهٔ ممنوعه است.\nوَ أَعْلَمَهُ أَنَّ فِی الْإِقْدَامِ عَلَیهِ التَّعَرُّضَ لِمَعْصِیتِهِ\nو او را آگاه ساخت که اقدام بر آن، در معرض نافرمانی او قرارگرفتن است.\nخدای متعال به آدم علیه‌السلام فهماند و آموخت که اگر به سراغ آن کاری که از آن نهی کرده‌ام بروی، معصیت کرده‌ای.\nوَ الْمُخَاطَرَةَ بِمَنْزِلَتِهِ\nو مقام و منزلت او را به خطر خواهد افکند.\nشبهه: چرا آدم علیه‌السلام گناه کرد؟ مگر پیامبران الهی معصوم نیستند؟\nپاسخ: اوّلاً این کارِ جناب آدم علیه‌السلام ترکِ اَوْلی بود. ثانیاً برخی از نهی‌ها نتیجهٔ تکوینی دارند که اثر آن در دنیاست و گناهی بر آن مترتّب نیست. خوردن از شجرهٔ ممنوعه از جنس نهی تشریعی نبود، بلکه از سنخ تکوینی است؛ یعنی اثر خوردن، هبوط و خروج از مقام و منزلتی است که آدم علیه‌السلام داشت.\nدر حقیقت، گناهی حاصل نشد؛ ولی تبعات آن برای آدم علیه‌السلام پدید آمد که افتادن در تلاش، رنج و سختی دنیا بود.\nفَأَقْدَمَ عَلَی مَا نَهَاهُ عَنْهُ\nاما آدم علیه‌السلام به آنچه از آن نهی شده بود، اقدام کرد.\nآدم به‌سوی شجرهٔ ممنوعه رفت و از آن خورد و به چیزی اقدام کرد که خدای متعال از آن نهی کرده بود.\nمُوَافَاةً لِسَابِقِ عِلْمِهِ\nو علم پیشین خداوند دربارهٔ او تحقّق یافت.\nاین عملی که آدم علیه‌السلام انجام داد، موافق با علمی بود که خدا از پیش‌داشت.\nاین فراز به علم ازلی خدا نسبت به اشیا، پیش از خلقت آن‌ها، اشاره دارد. خدای متعال می‌دانست که آدم علیه‌السلام با اختیار خودش از شجرهٔ ممنوعه می‌خورد. عده‌ای قائل به جبر شده‌اند و این شبهه را مطرح می‌کنند.\nشبهه: من مجبورم گناه کنم تا علم خداوند زیر سؤال نرود.\nپاسخ: درست است که خدا به اشیا علم دارد، ولی ما با ارادهٔ خود، عملی را انجام می‌دهیم. اگر معتقد باشیم که خدای متعال علم دارد و علم او به فعل ما تعلّق می‌گیرد، این جبر است.\nدرحالی‌که ما معتقدیم علم الهی به ارادهٔ ما تعلّق می‌گیرد. به‌عبارت‌دیگر، خداوند متعال می‌داند که من با ارادهٔ خودم فعلی را مرتکب می‌شوم. علم الهی به ارادهٔ من است؛ پس علم الهی به جبر ختم نمی‌شود و خدای متعال ارادهٔ ما را می‌داند.\nفَأَهْبَطَهُ بَعْدَ التَّوْبَةِ\nتا آنکه پس از توبه، او را از بهشت به‌سوی زمین فرستاد.\nدر مورد هبوط، مناقشه‌ای وجود دارد. اگر منظور از هبوط، هبوط مکانی باشد، معنایش این است که آدم علیه‌السلام از بهشت برین فرود آمد؛ و این همان ذهنیت غالب مردم است. درحالی‌که هبوط در اینجا به معنای تنزّل درجه است. یعنی انسان از جایگاهی که داشت و با خوبان عالم و فرشتگان در ارتباط بود، جدا شد و باید شرایط سخت را تحمّل کند و در قالب جسم قرار گیرد. پس هبوط، مکانی نیست.\nلِیعْمُرَ أَرْضَهُ بِنَسْلِهِ\nتا زمین را با نسل و ذرّیهٔ خود آباد کند.\nو عمارت و آبادانی را به جامعه بازگرداند. در قرآن کریم نیز هدف از خلقت انسان در زمین، این‌گونه بیان شده است:\n«هُوَ أَنْشَأَکمْ مِنَ الْأَرْضِ وَ اسْتَعْمَرَکمْ فِیها وَ اسْتَغْفِرُوهُ» هود - ۶۳\nخلق کرد تا انسان زمین را آباد کند. هیچ‌کس حق تخریب ندارد. انسان باید آباد کند و رشد و ترقّی پدید آورد.\nدر حقیقت، توبهٔ آدم علیه‌السلام پذیرفته شد تا آبادانی ایجاد کند. پس آمدن بر روی زمین، یکی برای ازدیاد نسل و دیگری برای آبادانی بود.\nنتیجه می‌گیریم که توبهٔ برخی از گناهان، خدمات اجتماعی و عام‌المنفعه است. خدمت به خلق و کوشش در راه سعادت و فلاح مردم مهم است و خدمات اجتماعی باعث رشد و تعالی می‌گردد.\nوَ لِیقِیمَ الْحُجَّةَ بِهِ عَلَی عِبَادِهِ\nو بدین‌وسیله حجّت را بر بندگان تمام کرد.\nخدای متعال آدم علیه‌السلام را فرستاد تا حجّت خود را اقامه کند و آدم بر دیگران حجّت و دلیل شد.\nوَ لَمْ یخْلِهِمْ بَعْدَ أَنْ قَبَضَهُ مِمَّا یؤَکدُ عَلَیهِمْ حُجَّةَ رُبُوبِیتِهِ\nو پس از آنکه او را قبض روح کرد، آنان را از چیزی که حجّت ربوبیّت او را بر ایشان تأکید می‌کند، خالی نگذاشت.\nاین موضوع ترک نشد و ادامه پیدا کرد و خدای متعال مخلوقاتش را رها نکرد.\nوَ یصِلُ بَینَهُمْ وَ بَینَ مَعْرِفَتِهِ\nو میان آنان و معرفت خویش پیوند برقرار می‌کند.\nپیامبران آمدند و میان شناخت خدای متعال و مخلوقات، پیوند برقرار نمودند.\nبَلْ تَعَاهَدَهُمْ بِالْحُجَجِ عَلَی أَلْسُنِ الْخِیرَةِ مِنْ أَنْبِیائِهِ وَ مُتَحَمِّلِی وَدَائِعِ رِسَالاتِهِ قَرْنًا فَقَرْنًا\nبلکه آنان را پی‌درپی با حجّت‌ها، بر زبان پیامبران برگزیدهٔ خویش و حاملان ودایع رسالت‌هایش، مورد رسیدگی قرارداد.\nخدای متعال از طریق انبیای الهی که بار رسالت را بر دوش کشیدند، با مردم سخن گفت و صلاح و فلاح آنان را بیان نمود. دوره به دوره انبیای الهی آمدند و حجّت‌های الهی را آوردند.\nحَتَّی تَمَّتْ بِنَبِینَا مُحَمَّدٍ (صَلَّی اللَّهُ عَلَیهِ وَ آلِهِ وَ سَلَّمَ) حُجَّتُهُ\nتا آنکه حجّت او به‌وسیلهٔ پیامبر ما محمد صلی‌الله علیه و آله و سلم کامل شد.\nسلسلهٔ انبیا با پیامبر اسلام صلی‌الله علیه و آله به اتمام رسید. بار رسالت و امانت الهی به پیامبر خاتم صلی‌الله علیه و آله رسید و رسالت کامل شد و پیامبر اسلام آنچه را لازم بود، برای مردم بازگو کرد.\nوَ بَلَغَ الْمَقْطَعَ عُذْرُهُ وَ نُذُرُهُ\nو عذر و بیم دادن‌های او به نهایت خود رسید.\nبیان احکام و نیز انذار و بشارت الهی به سرمنزل نهایی رسید. پیامبر صلی‌الله علیه و آله همهٔ بشارت‌ها و انذارها را برای انسان‌ها بیان کرد و پس از پیامبر صلی‌الله علیه و آله نیز این سلسله در قالبی دیگر، به‌وسیلهٔ اوصیا ادامه یافت. با این تفاوت که انبیای الهی شریعت آوردند؛ ولی ائمّهٔ اطهار علیهم‌السلام، بیان‌کننده و مبلّغ شریعت رسول خاتم صلی‌الله علیه و آله هستند.\nحضرت، دو ابتلا و امتحان را برای بشر بیان می‌نماید: ارزاق و مرگ که هر دو امتحان الهی‌اند.\nوَ قَدَّرَ الْأَرْزَاقَ\nخدای متعال روزی انسان‌ها را اندازه‌گیری و مقدّر فرمود.\nارزاق را میان بندگان تقسیم کرد و متکفّل روزی انسان شد.\nفَکثَّرَهَا وَ قَلَّلَهَا\nگاه آن را زیاد و گاه کم قرارداد.\nبه برخی بیشتر و به برخی از بندگان کمتر عطا نمود.\nوَقسم‌هاَّمَهَا عَلَی الضِّیقِ وَ السَّعَةِ\nو آن را بر تنگی و گشایش تقسیم کرد.\nبه بعضی از بندگان، کمبود و تنگی، و به برخی دیگر، روزیِ وسیع داد.\nسؤال: خدای متعال که عادل است، بر چه اساسی به برخی کمتر و به برخی بیشتر می‌دهد؟\nحضرت، خود پاسخ می‌دهد:\nفَعَدَلَ فِیهَا لِیبْتَلِی مَنْ أَرَادَ بِمَیسُورِهَا وَ مَعْسُورِهَا\nپس در آن عدالت ورزید تا هرکس را که بخواهد، با آسانی و سختی آن بیازماید.\nاصلاً این فکر به ذهن شما خطور نکند که خدای متعال بی‌عدالتی کرده است. خداوند به عدالت رفتار نموده و این کم‌وزیاد شدن، برای امتحان است و هیچ منافاتی باعدالت ندارد.\nهمچنین بر اساس روایتی از رسول خدا صلی‌الله علیه و آله، برخی از مؤمنان را فقط فقر می‌تواند سربه‌راه و مؤمن نگه دارد و اگر آن بنده غنا و ثروت داشته باشد، فاسد می‌شود. خدای متعال برای رعایت مصالح بندگان، ابدیت آنان را بر دنیایشان ترجیح می‌دهد. بیماری، تنگدستی و مانند آن، همه از عدالت و حکمت خدای متعال است.\nوَ لِیخْتَبِرَ بِذلِک الشُّکرَ وَ الصَّبْرَ مِنْ غَنِیهَا وَ فَقِیرِهَا\nو تا با این وسیله، شکر و صبرِ توانگر و تهی‌دست را بیازماید.\nخدای متعال می‌خواهد همهٔ بندگان را امتحان کند: از غنی، ازاین‌جهت که آیا شکر عملی به‌جا می‌آورد یا نه؛ و از فقیر، امتحان صبر می‌گیرد.\nثُمَّ قَرَنَ بِسَعَتِهَا عَقَابِیلَ فَاقَتِهَا وَ بِسَلَامَتِهَا طَوَارِقَ آفَاتِهَا\nسپس با گشایش آن، پیامدهای فقرش را همراه ساخت و با سلامت آن، بلاهای ناگهانی‌اش را پیوند داد.\nالبتّه اگر امروز کسی ثروتمند باشد، معلوم نیست فردا نیز همین‌گونه بماند؛ و اگر امروز بیمار باشد، ممکن است فردا سلامت خود را بازیابد.\nوَ بِفُرَجِ أَفْرَاحِهَا غُصَصَ أَتْرَاحِهَا\nو با گشایش شادی‌های آن، گلوگیرهای اندوه‌هایش را همراه کرد.\nدوران شادی و سرور را با غصه و اندوه نزدیک ساخت. خدای متعال رهایی از شادی‌ها را با غصه‌ها قرین کرد. شادی و غصه به هم متصل‌اند. به قول صائب تبریزی:\nشکوفه با ثمر هرگز نگردد جمع در یک جا\nیک روز شادی است و یک روز غم. پس دل‌نگران نباشید و در هر موقعیت، امتحان خوبی پس بدهید.\nوَ خَلَقَ الْآجَالَ فَأَطَالَهَا وَ قَصَّرَهَا وَ قَدَّمَهَا وَ أَخَّرَهَا\nو اجل‌ها را آفرید، پس برخی را طولانی و برخی را کوتاه قرارداد و بعضی را پیش انداخت و بعضی را پس افکند.\nاجل و سرآمد زندگی را مشخص کرد. آن را گاهی طولانی و زمانی کوتاه قرارداد. برای آن تقدّم و تأخّر قرارداد.\nخدای متعال مرگ را خلق کرد. گاه عمر انسان را کوتاه و عمر برخی را طولانی نمود. گاهی مرگ به تعویق می‌افتد و گاهی جلو می‌آید. جزع‌وفزع و بی‌تابی، از عواملی است که انسان را زودتر از پا درمی‌آورد. انسان آرام، عمر بیشتری دارد و انسان مضطرب و ناآرام، کمتر عمر می‌کند. صلهٔ رحم و خوش‌خلقی، عمر را طولانی می‌کند.\nوَ وَصَلَ بِالْمَوْتِ أَسْبَابَهَا\nو اسباب آن را به مرگ پیوند داد.\nخدای متعال موجبات مرگ را نیز فراهم ساخت.\nمرگ بر اثر تصادف، بیماری، سکته، شهادت و مانند آن، اسباب گوناگون مرگ هستند.\nوَ جَعَلَهُ خَالِجًا لِأَشْطَانِهَا\nو مرگ را برکَنَندهٔ طناب‌های آن قرارداد.\nوَ قَاطِعًا لِمَرَائِرِ أَقْرَانِهَا\nو بُرَندهٔ پیوندهای هم‌قرین‌های آن ساخت.\nخدای متعال مرگ را قطع‌کنندهٔ طناب‌های زندگی قرارداد. انسان تعلّقاتی دارد و خدا مرگ را وسیلهٔ بریدن انسان از این تعلّقات قرار می‌دهد؛ زیرا در حقیقت، مرگ انقطاع است. هرچه تعلّقات بیشتر باشد، دل‌کندن از آن‌ها سخت‌تر خواهد بود.\nاللَّهُمَّ أَحْینَا حَیاةَ مُحَمَّدٍ وَ آلِ مُحَمَّدٍ","بخش یازدهم\nمتن:\nعَالِمُ السِّرِّ مِنْ ضَمَائِرِ الْمُضْمِرِينَ وَ نَجْوَى الْمُتَخَافِتِينَ وَ خَوَاطِرِ رَجْمِ الظُّنُونِ وَ عُقَدِ عَزِيمَاتِ الْيَقِينِ وَ مَسَارِقِ إِيمَاضِ الْجُفُونِ، وَ مَا ضَمِنَتْهُ أَكْنَانُ الْقُلُوبِ وَ غَيَابَاتُ الْغُيُوبِ، وَ مَا أَصْغَتْ لِاسْتِرَاقِهِ مَصَائِخُ الْأَسْمَاعِ وَ مَصَايِفُ الذَّرِّ وَ مَشَاتِي الْهَوَامِّ وَ رَجْعِ الْحَنِينِ مِنَ الْمُولَهَاتِ وَ هَمْسِ الْأَقْدَامِ وَ مُنْفَسَحِ الثَّمَرَةِ مِنْ وَلَائِجِ غُلُفِ الْأَكْمَامِ وَ مُنْقَمَعِ الْوُحُوشِ مِنْ غِيرَانِ الْجِبَالِ وَ أَوْدِيَتِهَا وَ مُخْتَبَإِ الْبَعُوضِ بَيْنَ سُوقِ الْأَشْجَارِ وَ أَلْحِيَتِهَا وَ مَغْرِزِ الْأَوْرَاقِ مِنَ الْأَفْنَانِ وَ مَحَطِّ الْأَمْشَاجِ مِنْ مَسَارِبِ الْأَصْلَابِ وَ نَاشِئَةِ الْغُيُومِ وَ مُتَلَاحِمِهَا وَ دُرُورِ قَطْرِ السَّحَابِ فِي مُتَرَاكِمِهَا، وَ مَا تَسْفِي الْأَعَاصِيرُ بِذُيُولِهَا وَ تَعْفُو الْأَمْطَارُ بِسُيُولِهَا وَ عَوْمِ بَنَاتِ الْأَرْضِ فِي كُثْبَانِ الرِّمَالِ وَ مُسْتَقَرِّ ذَوَاتِ الْأَجْنِحَةِ بِذُرَا شَنَاخِيبِ الْجِبَالِ وَ تَغْرِيدِ ذَوَاتِ الْمَنْطِقِ فِي دَيَاجِيرِ الْأَوْكَارِ، وَ مَا أَوْعَبَتْهُ الْأَصْدَافُ وَ حَضَنَتْ عَلَيْهِ أَمْوَاجُ الْبِحَارِ، وَ مَا غَشِيَتْهُ سُدْفَةُ لَيْلٍ أَوْ ذَرَّ عَلَيْهِ شَارِقُ نَهَارٍ، وَ مَا اعْتَقَبَتْ عَلَيْهِ أَطْبَاقُ الدَّيَاجِيرِ وَ سُبُحَاتُ النُّورِ وَ أَثَرِ كُلِّ خَطْوَةٍ وَ حِسِّ كُلِّ حَرَكَةٍ وَ رَجْعِ كُلِّ كَلِمَةٍ وَ تَحْرِيكِ كُلِّ شَفَةٍ وَ مُسْتَقَرِّ كُلِّ نَسَمَةٍ وَ مِثْقَالِ كُلِّ ذَرَّةٍ وَ هَمَاهِمِ كُلِّ نَفْسٍ هَامَّةٍ، وَ مَا عَلَيْهَا مِنْ ثَمَرِ شَجَرَةٍ أَوْ سَاقِطِ وَرَقَةٍ أَوْ قَرَارَةِ نُطْفَةٍ أَوْ نُقَاعَةِ دَمٍ وَ مُضْغَةٍ أَوْ نَاشِئَةِ خَلْقٍ وَ سُلَالَةٍ، لَمْ يَلْحَقْهُ فِي ذَلِكَ كُلْفَةٌ وَ لَا اعْتَرَضَتْهُ فِي حِفْظِ مَا ابْتَدَعَ مِنْ خَلْقِهِ عَارِضَةٌ وَ لَا اعْتَوَرَتْهُ فِي تَنْفِيذِ الْأُمُورِ وَ تَدَابِيرِ الْمَخْلُوقِينَ مَلَالَةٌ وَ لَا فَتْرَةٌ، بَلْ نَفَذَهُمْ عِلْمُهُ وَ أَحْصَاهُمْ عَدَدُهُ وَ وَسِعَهُمْ عَدْلُهُ وَ غَمَرَهُمْ فَضْلُهُ مَعَ تَقْصِيرِهِمْ عَنْ كُنْهِ مَا هُوَ أَهْلُهُ‏.\nترجمه:\nخداوند از اسرار پنهانى رازداران آگاه است، واز نجواى آنان که آهسته سخن مى گويند با خبر است، از آنچه به اذهان از طريق ظنّ و گمان، مى گذرد، و از تصميماتى که به يقين مى پيوندد، آگاهى دارد. \nبرق نگاه هاى خيانت آميز چشم ها را که از لابه لاى پلک ها خارج مى شود، مى بيند و از آنچه در نهانگاه دلها قرار دارد و آنچه در پشت پرده هاى ظلمانى غيب پوشيده و پنهان است و از آنچه که پرده هاى گوشها مخفيانه مى شنود، آگاه است، او از درون لانه هاى تابستانى مورچه گان و خانه هاى زمستانى حشرات، و آهنگ اندوه بار زنان غم ديده، و صداى آهسته گامها، آگاهى دارد.\nو نيز از جايگاه پرورش ميوه ها در درون غلاف شکوفه ها، و از مخفى گاههاى وحوش در درون غارهاى کوهها و اعماق درّه ها، و از نهانگاه پشه ها در ميان ساقه ها و پوستهاى درختان، و از محل پيوستگى برگها و شاخه ها و از جاى حرکت نطفه ها از صلب (پدران) و آميزش با نطفه (مادران) در درون رحم ها مطلع است. او از ابرهاى رقيقى که (در آسمان) پيدا مى شود، سپس به هم پيوسته، و متراکم مى گردد و نيز از ريزش قطرات باران از ابرهاى متراکم و آنچه گردبادها با دامن خويش از روى زمين بر مى گيرند و باران ها با سيلاب خود آن را فرو مى نشانند و محو مى کنند و از فرورفتن جانوران زمين، در ميان تپه هاى شن (در همه جا و در هر زمان و در هر حال) به خوبى آگاه است!\nخداوند، از جايگاه پرندگان در قلّه بلند کوهها، و از نغمه مرغان خواننده در آشيانه هاى تاريک، باخبر است. همچنين از لؤلؤهايى که در دل صدف ها پنهان شده و امواج دريا آنها را در دامن خويش پرورش داده است، و آنچه تاريکى شب آن را فرا گرفته، يا خورشيد به آن نور افشانده، و آنچه ظلمت ها و امواج نور يکى بعد از ديگرى آن را در بر مى گيرد، و اثر هر گام و احساسِ هرگونه حرکت و آهنگ هر سخن، و جنبش هر لب، و جايگاه هر انسان، و وزن هر مورچه، و ناله هر صاحب اندوه، و ميوه هايى که بر شاخسار درختان قرار گرفته، و برگ هايى که روى زمين ريخته، و قرارگاه هر نطفه ها، يا جمع شدن خون، و مضغه يا پرورش يافتن انسان و ساير مخلوقات.\n(آرى!) از همه اينها به خوبى آگاه است، وهيچ گونه مشقّتى براى او در اين علم و آگاهى وجود ندارد. بلکه در حفظ و نگهدارى آنچه از مخلوقات ابداع کرده، نيز مشکلى براى او رخ نداده، و در تنفيذ امور و تدبير موجودات نيز ملالت و فتورى بر او عارض نشده است. بلکه علمش در همه آنها نافذ و احصاى او همه را شامل شده، و عدالتش همه را در برگرفته است و با اينکه آنها در آنچه شايسته مقام اوست تقصير دارند، فضل و رحمتش شامل حال همه آنهاست.\nتفسیر:\nلطایف علم الهی\nبخش پایانی خطبهٔ حضرت دربارهٔ هبوط جناب آدم به زمین و امتحان‌هایی است که از انسان گرفته می‌شود.\nامتحان فقر و غنا و امتحان مرگ؛ همه می‌میرند، تعلّقاتشان از دنیا قطع می‌شود و باید برای آن سرا آماده باشند.\nدر این بخش، حضرت از جزئیات علم الهی سخن می‌گوید. وقتی می‌گوییم خدا همه چیز را می‌داند، منظورمان کلیات است؛ درحالی‌که حضرت می‌فرماید خداوند ریزترین امور خلقت را نیز می‌داند. علم الهی هم به کلیات تعلّق دارد و هم به جزئیات.\nعَالِمُ السِّرِّ مِنْ ضَمَائِرِ الْمُضْمِرِینَ\nخداوند عالم و آگاه است و از رازهای درون انسان‌ها خبر دارد. گاهی رازی در درون انسان وجود دارد که خود او نیز آن را فراموش کرده است. خداوند هم ظاهر را می‌داند و هم‌رازهای پنهان را؛ حتی رازی را که انسان فراموش کرده است، می‌داند.\nوَ نَجْوَی الْمُتَخَافِتِینَ\nخداوند نجوا و گفت‌وگوی درگوشی را نیز می‌داند. اگر دو نفر آهسته و پنهانی، یعنی [مُتَخَافِتِینَ]، با یکدیگر صحبت کنند، گرچه از دیگران پنهان است، از خداوند پنهان نیست. در واژهٔ «نجوا»، مفهوم آرام و آهسته بودن نیز وجود دارد. ما باید هم مناجات، یعنی گفت‌وگوی آرام باخدا، داشته باشیم و هم منادات، یعنی دعا خواندن با صدای بلند.\nوَ خَوَاطِرِ نَجْمِ الظُّنُونِ\nخداوند گمان‌هایی را که به ذهن انسان خطور می‌کند، می‌داند. گاهی چیزهایی به ذهن انسان خطور می‌کند که عمدی نیست؛ ولی خداوند همهٔ آن‌ها را می‌داند. از بزرگان عرفاً نقل شده است که نسبت به خواطر نیز باید سلوک داشت. خواطر گناه ندارند، ولی در تربیت انسان اثر می‌گذارند. خداوند خواطر و اندیشه‌هایی را که از ذهن انسان می‌گذرد، می‌داند.\nوَ عَقْدِ عَزِیمَاتِ الْیقِینِ\nتصمیم‌های قطعی و عقیده‌هایی را که انسان قصد انجام آن‌ها را دارد، خداوند می‌داند.\nوَ مَسَارِقِ إِیمَاضِ الْجُفُونِ\nخداوند نگاه‌های دزدکی، یعنی [مَسَارِق]، چشم‌ها را می‌داند.\nزمانی را که چشم‌ها، یعنی [جُفُون]، برق می‌زنند، یعنی [إِیمَاض]، و انسان به دیگران نگاه می‌کند، نیز می‌داند.\nسرقت فقط بالارفتن از دیوار مردم نیست. اگر فردی محدود و عفیف باشد و کسی وارد حریم او شود، این کار نیز نوعی دزدی است.\nوَ مَا ضَمِنَتْهُ أَکنَانُ الْقُلُوبِ وَ غَیابَاتُ الْقُلُوبِ\nخداوند آنچه را در قلب‌ها پنهان شده است، می‌داند؛ مانند نگاه آلوده و خطورات ذهنی.\nاو غیب و امور پنهان را می‌داند. بعضی چیزها که از نظر ما غیب هستند، برای ملائکه آشکارند و بعضی امور برای ملائکه نیز پنهان‌اند؛ اما خداوند آنچه را که غیب الغیوب است، می‌داند.\nوَ مَا أَصْغَتْ لِاسْتِرَاقِهِ مَصَائِخُ الْأَسْمَاعِ\nخداوند گوش‌هایی را که مخفیانه درصدد شنیدن و استراق سمع هستند، می‌داند.\nهرجا کسی گوش‌تیز کرده است تا سخنان پنهانی را که مربوط به او نیست بشنود، خداوند از آن آگاه است.\nوَ مَصَائِفِ الذَّرِّ\nحضرت از این قسمت، بحث را تغییر می‌دهد و علم دیگری را بیان می‌کند که خداوند از آن آگاه است.\nخداوند به مورچه‌هایی، یعنی [الذَّر] که در اقامتگاه‌های تابستانی، یعنی [مَصَائِف]، زندگی می‌کنند، علم دارد.\nمورچه به دلیل ریز بودن، به چشم نمی‌آید. مورچه‌ها در تابستان بیشترین فعالیت را دارند و در حال تهیهٔ غذا هستند. خداوند به همهٔ این امور علم دارد.\nوَ مَشَاتِی الْهَوَامِّ\nخداوند زمانی را که حشرات به خواب زمستانی فرومی‌روند نیز می‌داند. او هم مورچه‌های ریزی را که در حال رفت‌وآمد هستند می‌شناسد و هم از مورچه‌هایی که درون زمین به خواب زمستانی فرورفته‌اند، آگاه است.\nوَ رَجْعَ الْحَنِینِ مِنَ الْمُولَهَاتِ\nخداوند هق‌هق گریهٔ مادران فرزند ازدست‌داده، یعنی [الْمُولَهَات]، را می‌داند.\nهمهٔ این امور یک ظاهر و یک باطن دارند. این موضوع دربارهٔ حیوانی که فرزند خود را ازدست‌داده نیز صادق است. خداوند آه جان‌سوز هر موجودی را که اندوهگین است، می‌داند.\nعلّت گریه و ناله و حتی نوع گریه را نیز می‌داند و آگاه است که این گریه برای چیست.\nوَ مُنْفَسَحِ الثَّمَرَةِ مِنْ وَلَائِجِ غُلُفِ الْأَکمَامِ\nخداوند می‌داند شکوفه‌هایی که بر روی درخت پدید آمده‌اند، غلافی دارند که میوه در آن شکل می‌گیرد. او می‌داند درون هر غلاف چه میوه‌ای قرار دارد و آن میوه چه شرایطی خواهد داشت؛ از کجا آمده و سرانجامش چیست. آیا شیرین می‌شود یا کال می‌ماند؟ آیا رسیده می‌شود یا بر زمین می‌افتد و یا چیده خواهد شد؟\nوَ مُنْقَمَعِ الْوُحُوشِ مِنْ غِیرَانِ الْجِبَالِ وَ أَوْدِیتِهَا\nخداوند می‌داند حیوانات وحشی در بیابان‌ها و شکاف کوه‌ها، در کجا خانه گزیده‌اند.\nاین حیوانات از سرما و گرما و حملهٔ دسته‌جمعی در امان نیستند. خداوند می‌داند در کدام بیابان، یعنی [أَوْدِیتِهَا]، کدام حیوان وحشی و در کدام غارهای کوه، یعنی [غِیرَان]، لانه کرده است و درد و رنج آن چیست.\nوَ مُخْتَبَإِ الْبَعُوضِ بَینَ سُوقِ الْأَشْجَارِ وَ أَلْحِیتِهَا\nخداوند می‌داند پشه‌ها و حشرات در میان ساقه و پوستهٔ درختان چگونه لانه ساخته‌اند و چند مورچه و پشه در این درخت لانه کرده‌اند.\nوَ مَغْرِزِ الْأَوْرَاقِ مِنَ الْأَفْنَانِ\nخداوند محل اتصال برگ‌ها به شاخه‌ها، یعنی [مَغْرِز]، را می‌داند. درخت، برگ و ساقه و شاخه دارد و خدا می‌داند این برگ چگونه به درخت چسبیده است که در برابر باد چنین استحکامی دارد.\nوَ مَحَطِّ الْأَمْشَاجِ مِنْ مَسَارِبِ الْأَصْلَابِ\nخداوند محل فرودآمدن نطفه‌ها در رحم‌ها را می‌داند؛ نطفه‌هایی که از صلب پدران حرکت می‌کنند و به قرارگاه خود، یعنی رحم مادران، می‌رسند.\nچرا به نطفه «امشاج» گفته می‌شود؟ چون استعدادهای فراوانی در نطفه قرار گرفته است.\nوَ نَاشِئَةِ الْغُیومِ وَ مُتَلَاحِمِهَا\nخداوند می‌داند کدام ابرها از یکدیگر گسسته و کدام‌یک به هم پیوسته‌اند. ابرها ابتدا از هم جدا هستند و سپس به یکدیگر متصل می‌شوند.\nوَ دُرُورِ قَطْرِ السَّحَابِ فِی مُتَرَاکمِهَا\nزمانی که ابرها به یکدیگر پیوستند، خداوند مقدار ریزش باران از ابرهای متراکم شده، سرزمینی را که باران به آن می‌رسد و این‌که باران سودمند است یا زیان‌بار، همه را می‌داند.\nوَ مَا تَسْفِی الْأَعَاصِیرُ بِذُیولِهَا وَ تَعْفُو الْأَمْطَارُ بِسُیولِهَا\nخداوند پراکندگی و گردآوری‌ای را که گردبادها پدید می‌آورند، می‌داند.\nحضرت گردباد را به دامان زن، یعنی [ذُیولِهَا]، تشبیه کرده است. وقتی دامن می‌چرخد، محیط زیادی را در برمی‌گیرد. گردباد نیز مانند دامنی است که محیط وسیعی را فرامی‌گیرد و بسیاری از خار و خاشاک را بلند می‌کند و به آسمان می‌برد.\nخداوند می‌داند وقتی گردباد برخاست و هوا را آلوده کرد، چه زمانی باران می‌آید و آثار خاکی را که بر اثر گردباد پدیدآمده است، محو می‌کند، یعنی [تَعْفُو].\nوَ عَوْمِ نَبَاتِ الْأَرْضِ فِی کثْبَانِ الرِّمَالِ\nخداوند فرورفتن حشرات در ریگ‌های بیابان را می‌داند و می‌داند در زیر بیابان چه حشره‌ای و چه تعداد حشره در زمین فرورفته است.\nوَ مُسْتَقَرِّ ذَوَاتِ الْأَجْنِحَةِ بِذُرَی شَنَاخِیبِ الْجِبَالِ\nحضرت از زمین به اوج آسمان می‌پردازد.\nخداوند می‌داند در قلهٔ کوه‌ها کدام پرندگان، یعنی [ذَوَاتِ الْأَجْنِحَة]، ساکن هستند. او می‌داند روزی آن‌ها چیست، چند جوجه دارند، چگونه جوجه‌های خود را سیر می‌کنند و چرا این کوه را برای زندگی انتخاب کرده‌اند.\nوَ تَغْرِیدِ ذَوَاتِ الْمَنْطِقِ فِی دَیاجِیرِ الْأَوْکارِ\nخداوند نغمهٔ پرندگانِ سخنگو را در تاریکی لانه‌ها می‌داند. پرنده‌ای که در بالای درخت لانه دارد، تاریکی لانه و نجوای پرندگان را به‌خوبی می‌داند.\nوَ مَا أَوْعَبَتْهُ الْأَصْدَافُ وَ حَضَنَتْ عَلَیهِ أَمْوَاجُ الْبِحَارِ\nخداوند می‌داند در دریاها و اقیانوس‌های پهناور، چند صدف زنده است و درون هر صدف چند مروارید قرار دارد. همچنین می‌داند آیا این مرواریدها به بار می‌نشینند و به دست انسان می‌رسند یا نه.\nخداوند موج‌هایی را مأمور حفاظت از صدف می‌کند تا مروارید، آن‌گونه که خدا می‌خواهد، شکل بگیرد. امواج دریا برای صدف مادری می‌کنند، یعنی [حَضَنَتْ]، تا مرواریدها حفظ شوند.\nامواج برای ما ظاهراً یکسان‌اند؛ ولی برای خداوند، هر موج مسئول کاری است: موجی مأمور حفظ صدف‌هاست، موجی مسئول حمل ماهی است و موجی مأمور گرفتن جان کسی است. وظیفهٔ هر موج جداگانه است.\nوَ مَا غَشِیتْهُ سُدْفَةُ لَیلٍ أَوْ ذَرَّ عَلَیهِ شَارِقُ نَهَارٍ\nخداوند آنچه را تاریکی شب پوشانده است، می‌داند.\nاو می‌داند چه کسی در کجا قرار دارد و چه نیازی دارد. همین که چیزی از ذهن عبور کند، خداوند آن را می‌داند.\nهمچنین می‌داند آنچه را که نور درخشان خورشید بر آن تابیده است.\nوَ مَا اعْتَقَبَتْ عَلَیهِ أَطْبَاقُ الدَّیاجِیرِ وَ سُبُحَاتُ النُّورِ\nتاریکی‌ها و نورهای شدید، پشت سر یکدیگر می‌آیند؛ یعنی [اعْتَقَبَتْ]. این بخش مربوط به عالم بالاست.\nخداوند می‌داند چه چیزهایی را پرده‌های تاریکی و پرده‌های نور پوشانده‌اند و در ماورای این حجاب‌ها چه چیزی وجود دارد؛ همان چیزهایی که مخلوقات از دیدن آن‌ها منع شده‌اند.\nوَ أَثَرَ کلِّ خَطْوَةٍ\nچرا حضرت بر علم الهی تأکید می‌کند؟ حضرت صرفاً مسائل علمی را بیان نمی‌کند، بلکه می‌خواهد ما را به راه هدایت بکشاند.\nثمرهٔ دانستن علم الهی این است که انسان باید بااحتیاط و مراقبت حرکت کند. خداوند به همه چیز آگاه است؛ بنابراین انسان باید مراقب اعمال خود باشد. خداوند اثر و نتیجهٔ هر قدمی را که انسان برمی‌دارد، می‌داند. اثر علم الهی همین است.\nتوحید فقط این نیست که بگوییم خدا یگانه است. توحید می‌گوید وارد این وادی شوید که خداوند عالم است؛ یعنی به مقام و جایگاه خداوند علم پیدا کنید. باید اثر او را در زندگی خود ببینید. خداوند عالم است؛ یعنی گناه نکنید، خطورات خود را کنترل کنید و بدانید همه‌جا محضر خداست.\nخداوند اثر هر گام را می‌داند:\n«إِنَّا نَحْنُ نُحْیی الْمَوْتَیٰ وَ نَکتُبُ مَا قَدَّمُوا وَ آثَارَهُمْ»\nروزی از این دنیا خواهیم رفت. وقتی رفتیم، دو چیز از ما ثبت و ضبط می‌شود:\n۱. چه چیزی پیش فرستادیم.\n۲. وَ آثَارَهُمْ: آثار اعمال نیز محاسبه می‌شود. سخنی که گفته شد، چه اثری داشت؟ هم اصل عمل و هم اثر آن به‌حساب می‌آید.\nحَسَّ کلِّ حَرَکةٍ\nخداوند حسّ هر حرکتی و صدای هر حرکتی را می‌داند. حالت و انگیزهٔ حرکت نیز مهم است. خداوند می‌داند عبادت بدون احساس، از روی غرور انجام شده یا از روی اکراه.\nوَ رَجْعَ کلِّ کلِمَةٍ\n«رجع» دو معنا دارد:\n۱. آهنگ؛ یعنی هر کلمه با چه آهنگی گفته شده است: با تواضع یا با آهنگ کبر.\n۲. بازگشت؛ یعنی خداوند می‌داند بازگشت سخن تو چیست. سخن تو چه آتش فتنه‌ای را خاموش می‌کند یا چه آتشی را روشن می‌سازد؟\nوَ تَحْرِیک کلِّ شَفَةٍ وَ مُسْتَقَرِّ کلِّ نَسَمَةٍ\nخداوند حرکت لب‌ها و جایگاه هر نفسی را که در هر جای عالم هستی قرار دارد، می‌داند.\nوَ مِثْقَالِ کلِّ ذَرَّةٍ\nخداوند وزن هر ذره را می‌داند. البته «ذره» در جمله‌های قبل به معنای مورچه آمده است و خداوند می‌داند هر مورچهٔ کوچک چه وزنی دارد.\nوَ هَمَاهِمِ کلِّ نَفْسٍ هَامَّةٍ\nخداوند همهمه و سروصدای هر انسان اندوهگین را می‌داند. او صدای نالهٔ گریه‌کنندگان و آه حسرت خوردگان را می‌شنود.\n«همهمه» یک معنا دارد و «همّت» معنای دیگری.\nخداوند می‌داند هرکدام از شما چه همّتی دارید و نتیجهٔ همّت شما چیست. هرچه همّت بلندتر باشد، بازگشت نور و رحمت خدا بیشتر است. او صدای ناله و اوج همّت را می‌داند. در حکمت‌ها آمده است:\n«قَدْرُ الرَّجُلِ عَلَی قَدْرِ هِمَّتِهِ»\nقدر هر انسان به اندازهٔ همّت اوست. خداوند بلندهمّتی را می‌خرد و به آن ترتیب اثر می‌دهد.\nوَ مَا عَلَیهَا مِنْ ثَمَرِ شَجَرَةٍ أَوْ سَاقِطِ وَرَقَةٍ\nخداوند می‌داند کجا میوه یا برگی از درخت سقوط می‌کند و علّت سقوط برگ و میوه را نیز می‌داند.\nما افتادن برگی از درخت را می‌بینیم و می‌گوییم؛ چون پاییز است، برگ درختان می‌ریزد؛ اما درختان با یکدیگر متفاوت‌اند. خدا می‌داند برگ به‌وسیلهٔ کدام باد، با چه جهتی و از کدام سمت، در چه مسیری سقوط کرده است.\nدر نظر ما، برگی همین‌طور افتاده است؛ اما در دستگاه الهی، هر چیزی دارای حساب‌وکتاب است.\nأَوْ قَرَارَةِ نُطْفَةٍ\nخداوند می‌داند جایگاه هر نطفه کجاست و قرارگاه هر نطفه را می‌شناسد.\nأَوْ نُقَاعَةِ دَمٍ وَ مُضْغَةٍ أَوْ نَاشِئَةِ خَلْقٍ وَ سُلَالَةٍ\nخداوند می‌داند این نطفه چه زمانی به خون تبدیل می‌شود و چه زمانی به انسانی کامل تبدیل خواهد شد. همچنین می‌داند از این نطفه چه نسلی پدید می‌آید و نسل و ذرّیهٔ او چه خواهد شد.\nاین‌که خداوند علم دارد، یعنی در همین نطفه نیز مطالب و آینده‌هایی نهفته است و استعداد نسل‌های آینده در آن وجود دارد. یکی از علوم غیبی، شناخت آیندهٔ فرزندی است که در رحم قرار دارد؛ این‌که چه آینده‌ای خواهد داشت و سعادتمند می‌شود یا شقی.\nلَمْ تَلْحَقْهُ فِی ذَلِک کلْفَةٌ\nاین‌همه علم و آگاهی به جزئیات امور، برای خداوند هیچ سختی و مشقّتی ندارد.\nوَ لَا اعْتَرَضَتْهُ فِی حِفْظِ مَا ابْتَدَعَ مِنْ خَلْقِهِ عَارِضَةٌ\nآفرینش هیچ‌چیزی برای خداوند سخت نیست.\nوَ لَا اعْتَوَرَتْهُ فِی تَنْفِیذِ الْأُمُورِ وَ تَدَابِیرِ الْمَخْلُوقِینَ مَلَالَةٌ وَ لَا فَتْرَةٌ\nخداوند در اجرای دستوراتش دربارهٔ مخلوقات، هیچ سختی و ملالتی ندارد و ضعف و سستی از ناحیهٔ مخلوقات، در کار خداوند پدید نمی‌آورد.\nبَلْ نَفَذَهُمْ عِلْمُهُ وَ أَحْصَاهُمْ عَدُّهُ\nعلم خداوند در همهٔ هستی نفوذ دارد.\nاو تعداد همهٔ مخلوقات را می‌داند.\nوَ وَسِعَهُمْ عَدْلُهُ\nهمهٔ کارهای خداوند از روی عدل است. چرا و پرسش در دستگاه الهی راه ندارد؛ او همه چیز را می‌داند و هر کار خداوند از روی عدل و حکمت است.\nوَ غَمَرَهُمْ فَضْلُهُ\nفضل، رحمت و بخشش خداوند بر همهٔ موجودات احاطه دارد، یعنی [غَمَرَهُمْ]. لطف خداوند بیش از عدل اوست و به همه، بیش از استحقاقشان عطا می‌کند.\nکسی از حضرت سؤال کرد: «صِفْ لَنَا رَبَّنَا»؛ خدا را برای ما توصیف کن.\nمَعَ تَقْصِیرِهِمْ عَنْ کنْهِ مَا هُوَ أَهْلُهُ\nمخلوقات در برابر علم خداوند، پر کاهی بیش نیستند. انسانی که نمی‌تواند علم خدا را به مخلوقات تصور کند، چگونه می‌تواند از علم خدا سر دربیاورد؟\nخداشناسی، شناخت علم خدا نسبت به خویش است.\nابن ابی‌الحدید می‌گوید:\nزمانی می‌گوییم پیامبر از چه طایفه‌ای است؟ می‌گوییم پیامبر از قریش و بنی‌هاشم است. اما وقتی رسول خدا به عظمت و جایگاهی می‌رسد که می‌گوییم قریش از پیامبر است، از لحاظ عظمت پیامبر، به‌جای نسبت‌دادن پیامبر به کل، کل را به پیامبر نسبت می‌دهیم.\nدرست نیست بگوییم علی ادیب و فصیح است یا ادبیات عرب را می‌داند. باید بگوییم ادبیات، یعنی علی؛ فصاحت، یعنی علی؛ و توصیف توحید، عدل و نبوّت، یعنی علی.\nالْحَمْدُ لِلَّهِ الَّذِی جَعَلَنَا مِنَ الْمُتَمَسِّکینَ بِوِلَایةِ أَمِیرِ الْمُؤْمِنِینَ","بخش دوازدهم\nمتن:\nاللَّهُمَّ أَنْتَ أَهْلُ الْوَصْفِ الْجَمِيلِ وَ التَّعْدَادِ الْكَثِيرِ، إِنْ تُؤَمَّلْ فَخَيْرُ مَأْمُولٍ وَ إِنْ تُرْجَ فَخَيْرُ مَرْجُوٍّ. اللَّهُمَّ [فَقَدْ] وَ قَدْ بَسَطْتَ لِي فِيمَا لَا أَمْدَحُ بِهِ غَيْرَكَ وَ لَا أُثْنِي بِهِ عَلَى أَحَدٍ سِوَاكَ، وَ لَا أُوَجِّهُهُ إِلَى مَعَادِنِ الْخَيْبَةِ وَ مَوَاضِعِ الرِّيبَةِ، وَ عَدَلْتَ بِلِسَانِي عَنْ مَدَائِحِ الْآدَمِيِّينَ وَ الثَّنَاءِ عَلَى الْمَرْبُوبِينَ الْمَخْلُوقِينَ؛ اللَّهُمَّ وَ لِكُلِّ مُثْنٍ عَلَى مَنْ أَثْنَى عَلَيْهِ مَثُوبَةٌ مِنْ جَزَاءٍ أَوْ عَارِفَةٌ مِنْ عَطَاءٍ، وَ قَدْ رَجَوْتُكَ دَلِيلًا عَلَى ذَخَائِرِ الرَّحْمَةِ وَ كُنُوزِ الْمَغْفِرَةِ؛ اللَّهُمَّ وَ هَذَا مَقَامُ مَنْ أَفْرَدَكَ بِالتَّوْحِيدِ الَّذِي هُوَ لَكَ وَ لَمْ يَرَ مُسْتَحِقّاً لِهَذِهِ الْمَحَامِدِ وَ الْمَمَادِحِ غَيْرَكَ وَ بِي فَاقَةٌ إِلَيْكَ لَا يَجْبُرُ مَسْكَنَتَهَا إِلَّا فَضْلُكَ وَ لَا يَنْعَشُ مِنْ خَلَّتِهَا إِلَّا مَنُّكَ وَ جُودُكَ؛ فَهَبْ لَنَا فِي هَذَا الْمَقَامِ رِضَاكَ وَ أَغْنِنَا عَنْ مَدِّ الْأَيْدِي إِلَى سِوَاكَ، إِنَّكَ عَلى‏ كُلِّ شَيْ‏ءٍ قَدِير.\nترجمه:\nخداوندا! تو دارى اوصاف جمال و صفات کمال فراوان هستى; اگر به تو آرزومنديم به خاطر آن است که تو بهترين آروزى مايى. و اگر به تو اميدواريم تو بهترين اميد ما هستى.\nبارالها! تو به من توان دادى که به مدحى بپردازم که غير تو را با آن مدح نمى گويم، و به ثنايى روى آورم که بر غير تو نمى خوانم; و روى سخنم را به کسانى که کانون نوميدى و شک و ترديد هستند، متوجّه نمى سازم، تو زبانم را (در پرتو معرفتت) از مدح و ستايش انسان ها و ثناخوانى مخلوقات بازداشتى. \nخداوندا! هر ثناخوانى; از سوى کسى که ثنايش را مى گويد، پاداش و عطايى دارد (به همين دليل) من اميدوارم که مرا به سوى ذخاير رحمت و گنج هاى مغفرت رهنمون گردى.\nخداوندا! اين وضع کسى است که تو را در توحيد خاصّ خودت يکتا شمرده، و غير تو را لايق اين ستايش ها، و ثناها نمى داند.\n(خداوندا!) من به تو نياز دارم. نيازى که جز فضل تو نمى تواند آن را برطرف سازد; و پريشانم، پريشانى و فقرى که جز بخشش تو نمى تواند آن را برطرف سازد. حال که چنين است، رضاى خود را در اين موقعيّت به ما عطا کن و دست نياز ما را از دامن غير خود کوتاه گردان «که تو بر هر چيز توانايى».\nتفسیر:\nخطبةُ الأَشْبَاحِ\nخلاصه‌ای از قبل:\nدر پاسخِ سؤال‌کننده‌ای که گفت خدا را چنان توصیف کن که گویی او را ببینیم، امیرالمؤمنین از سخن او ناراحت شد.\nالف) چرا خدا را مجسّمه و مشبّهه فرض می‌کنید؟\nب) دسترسی به شناختِ ذاتِ خدا ممکن نیست و شناخت باید از طریق آثار و تدبّر در نشانه‌های هستی باشد.\nحضرت، مصادیقی از این آثار را بیان فرمودند؛ از جمله: خلقت آسمان و زمین، ملائکه، سلسلهٔ آدم و انبیا، اسرار خلقت و علم الهی و در بخش پایانی، دعایی متناسب با حال‌وهوای همان سؤال‌کننده فرمود:\nاللَّهُمَّ أَنْتَ أَهْلُ الْوَصْفِ الْجَمِیلِ\nخداوندا، تو شایستهٔ اوصاف و صفات جمیل هستی و همهٔ صفات نیکویی که در عالم هست، از تو سرچشمه گرفته است. هرکس صفات جمالی دارد، آن را از تو وام‌گرفته و به مقامی رسیده است. به تعبیر قرآن، تو کسی هستی که همهٔ اسماء الهی و اسماء حُسنا از آنِ توست.\n«وَ لِلَّهِ الْأَسْمَاءُ الْحُسْنَیٰ فَادْعُوهُ بِهَا»\nحتی آنجا که خداوند منتقم است، این انتقام از روی لج‌بازی دنیایی و ظلم و تعدّی نیست؛ بلکه صفتِ منتقم نیز از اسماء جمال و زیبایی الهی است؛ چراکه در عین جمال الهی بودن، باطن این صفت به کمال الهی می‌رسد. منتقم باید باشد تا مجرم را در دادگاه عدل الهی حاضر کند و از او انتقام بگیرد. پس انتقام خداوند زیباست؛ چون به کسی ظلم نمی‌شود.\nوَ التَّعْدَادِ الْکثِیرِ\nخدایا، تو دارای صفات بی‌شماری برای حمد و ثنا و ستایشی. هرکدام از این صفاتِ خداوند، کارکرد و جایگاه خاص و ویژه‌ای دارند؛ مانند «یا رزّاق» برای طلب رزق‌وروزی.\nإِنْ تُؤَمَّلْ فَخَیرُ مَأْمُولٍ وَ إِنْ تُرْجَ فَخَیرُ مَرْجُوٍّ\nیک اصل وجود دارد: هرچه می‌خواهید، از خدا بخواهید. هر امیدی دارید، از خداوند بخواهید، نه از خلق خدا.\nخدایا، ما رضایت خودِ تو را می‌طلبیم. خواهش و خواستهٔ من، رسیدن به رضایت توست؛ نه این‌که تو واسطه شوی تا من به بهشت یا خواسته‌های دنیایی برسم، یا به غیر تو امیدوار باشم.\nطبق فرمایش‌های پیشین در همین خطبه، از عجایب علمی که حضرت امیر به آن اشاره فرمودند، تسلّط و علم غیب خداوند بر همهٔ هستی و کائنات است؛ و این چیز کمی نیست و جای شکر دارد.\nمثال: ما در گوشهٔ بیابان، تنهای تنها گرفتار شده‌ایم. کسی که ما را می‌بیند و صدای ما را می‌شنود و به ما کمک می‌کند و از گرفتاری نجاتمان می‌دهد و دستگیری‌مان می‌کند، ذات اقدس خداوندِ عالمیان است. آیا این جای شکر و سپاس ندارد؟\nما از اول خطبهٔ ۹۱، پابه‌پای حضرت امیر علیه‌السلام آمدیم تا یک مطلب را بگوییم. آن مطلب چیست؟ این‌که: خدایا، خودِ تو آرزو و امید ما باش؛ و از آن بالاتر، به جایی برسیم که جز تو امیدی نداشته باشیم؛ و تو محبوب و یار دلخواه ما باشی، نه این‌که تو واسطه باشی تا ما به آنچه می‌خواهیم برسیم:\nما از تو و از غیر تو تمنّا نداریم\nحلوا به کسی ده که محبّت نچشیده\nکسی که محبّت حضرت علی علیه‌السلام را چشیده باشد، دل به دیگران نمی‌دهد.\nاللَّهُمَّ وَ قَدْ بَسَطْتَ لِی فِیمَا لَا أَمْدَحُ بِهِ غَیرَک وَ لَا أُثْنِی بِهِ عَلَی أَحَدٍ سِوَاک\nخدایا، این توفیق را به علی دادی تا تو را مدح کنم؛ آن‌گونه که دیگران را مدح نمی‌کنم.\nاز مسلّمات است که هرکس خدمتی عرضه کرد، باید قدردانی و قدرشناسی شود؛ ولی واژهٔ «الْحَمْدُ لِلَّهِ» مخصوص ذات مقدّس خالق یگانه است. اگر کسی توانسته کاری یا خدمتی برای دیگری انجام دهد، تو او را فرستاده‌ای و او خود، به‌تنهایی و بدون ارادهٔ تو، نمی‌توانست کاری بکند. پس حمد و ثنای من جز برای خدا نیست.\nاللَّهُمَّ وَ قَدْ بَسَطْتَ لِی فِیمَا لَا أَمْدَحُ بِهِ غَیرَک وَ لَا أُثْنِی بِهِ عَلَی أَحَدٍ سِوَاک\nخدایا، تو شرایطی برای من مهیّا کردی که شاکر و مادحِ تو باشم و جز تو، مدح و ثنای کسی را نگویم.\nوَ لَا أُوَجِّهُهُ إِلَیٰ مَعَادِنِ الْخَیبَةِ وَ مَوَاضِعِ الرِّیبَةِ\nخدایا، ممنون توام. تو کسی هستی که توفیق نشستن بر سر سفرهٔ احسانِ علی را به من دادی. خدایا، ما را منصرف و روی‌گردان نکن و توجّه ما را به مردمی جلب نکن که خود روی‌گردان‌اند. ما را محتاج کسانی که معدن شک و شبهه‌اند و پر از آشوب و دلهره‌اند، قرار نده؛ چون آنان شک و دلهره را به جان ما نیز می‌اندازند و نمی‌دانند که همه چیز در اراده و مشیّت توست.\nباید با همنشینیِ عالمان و بامطالعه، غدّهٔ شک و شبهه را، پیش از آنکه به غدّه‌ای بدخیم تبدیل شود و همهٔ اعتقادات توحیدی و نبوّت و امامت ما را هدف قرار دهد، از بین ببریم.\nوظیفهٔ ما ترکِ ناامیدی و استقرار یقین در جان است.\nوَ عَدَلَتْ بِلِسَانِی عَنْ مَدَائِحِ الْآدَمِیینَ وَ الثَّنَاءِ عَلَی الْمَرْبُوبِینَ الْمَخْلُوقِینَ\nخدایا، از تو شاکرم که زبان مرا از مدح دیگران و چاپلوسی و ثنای مخلوق بازگرداندی.\nزبانم را منصرف کردی از این‌که به ثنای مخلوقی چون خودم مشغول باشم. آنان مربوب و مخلوق تو هستند.\nمدح‌کردن دیگران، انسان را به تملّق و چاپلوسی می‌کشاند.\nخداوند همهٔ عالم را برای انسان خلق و مسخّر کرده است، به‌شرط آنکه انسان، انسانیّت را فراموش نکند، در برابر قانون خدا سرپیچی نکند، به عبودیّت برسد و فقط در برابر خدا گردن خم کند.\n«تُو هَمْ گَرْدَن اَزْ حُکمِ دَاوَرْ مَپِیچْ»\nانسان اگر گردن از قانون عالم نپیچاند، عالم نیز برای او پیچیده نمی‌شود.\nاللَّهُمَّ وَ لِکلِّ مُثْنٍ عَلَیٰ مَنْ أَثْنَیٰ عَلَیهِ مَثُوبَةٌ مِنْ جَزَاءٍ أَوْ عَارِفَةٌ مِنْ عَطَاءٍ\nاز قدیم رسم بر این بود که شاعران نزد پادشاهان مدح و ثنا می‌گفتند و صله‌ای باارزش دریافت می‌کردند.\nخدایا، هرگاه کسی مدح و ثنای شخص بزرگی را بگوید، آن شخص پاداشی، یعنی [مَثُوبَة]، به او می‌دهد و من عمری درگاه تو را ستوده‌ام و مدح کسی جز تو بر زبانم جاری نشده است. از تو جزا و عطایی درشت و چشم‌پرکن، یعنی [عَارِفَة]، تقاضا دارم.\nوَ قَدْ رَجَوْتُک دَلِیلًا عَلَیٰ ذَخَائِرِ الرَّحْمَةِ وَ کنُوزِ الْمَغْفِرَةِ\nامید دارم که مرا راهنمایی کنی؛ راهنمای من باشی تا به ذخایر رحمت تو برسم.\nپاداش ما این باشد که به رحمت خود متصلمان کنی و به گنج‌های مغفرت خود برسانی.\nبه پاداش اندک راضی نمی‌شویم. رسیدن به دو پاداش باارزش، یعنی گنج مغفرت و معدن رحمت، ما را راضی می‌کند.\nاللَّهُمَّ وَ هَذَا مَقَامُ مَنْ أَفْرَدَک بِالتَّوْحِیدِ الَّذِی هُوَ لَک\nخدایا، در این مقام و جایگاهی که هستم، با تو سخن می‌گویم و فقط تو را خدای یگانه می‌دانم؛ [أَفْرَدَک].\nو در واقع نیز همین‌گونه است؛ [الَّذِی هُوَ لَک].\nجز تو در عالم خدایی نیست. همه‌کارهٔ عالم هستی فقط تویی.\nشرط استجابت دعا این است که انسان از اسباب و ابزار منقطع شود؛ زیرا با بریدن از آن‌ها به توحید می‌رسد و توحید، شرط استجابت است.\nوَ لَمْ یرَ مُسْتَحِقًّا لِهَذِهِ الْمَحَامِدِ وَ الْمَمَادِحِ غَیرَک\nهیچ‌کس جز تو را مستحق مدح و ثنا نمی‌دانم.\nکسی غیر از تو لایق مدح نیست.\nوَ بِی فَاقَةٌ إِلَیک\nخدایا، ما فقیرِ درگاه تو هستیم.\nاعتراف به فقرِ خود در بارگاه الهی، عزّت و غنا و شکوه است؛ بر خلاف اظهار فقر در برابر دیگران که ذلّت و عجز به همراه دارد.\nوَ لَا یجْبُرُ مَسْکنَتَهَا إِلَّا فَضْلُک\nخدایا، کسی نمی‌تواند فقر و مسکنت مرا جبران کند.\nهیچ‌کس جز فضل تو نمی‌تواند شکستگیِ روح مرا ترمیم کند.\nوَ لَا یتَعَشَّی مِنْ خَلَّتِهَا إِلَّا مَنُّک وَ جُودُک\nکسی نمی‌تواند جز جود تو، خلّت و نداریِ مرا برطرف کند.\nاوّلاً، اثبات فقر خود؛\nثانیاً نیافتن کسی جز خدا؛\nثالثاً، یافتن جود و فضل در خدا؛\nرابعاً، استمداد و طلب از خدا که برابر با اجابت است.\nفَهَبْ لَنَا فِی هَذَا الْمَقَامِ رِضَاک\nرضایت خود را بر ما ارزانی بدار.\nخدایا، من جز به رضایت تو به چیزی راضی نمی‌شوم.\nارزش هر آدمی به دعا و دغدغه‌مندی اوست. افق دید او چقدر است؟\nجز رضایت الهی و راضی شدن به خدا، به چیزی راضی نمی‌شوم. در برابر فقر و غنا، بیماری و سلامت، غم و شادی، نارضایتی در فانوسِ دل ما نباشد و رضایتمند باشیم.\nوَ أَغْنِنَا عَنْ مَدِّ الْأَیدِی إِلَیٰ سِوَاک\nخدایا، دست ما را کوتاه کن.\nما را بی‌نیاز کن از این‌که به غیر تو دست نیاز دراز کنیم.\nحضرت فرمود: آبروی انسان جامد و سخت است؛ اگر کسی به دیگری رو بیندازد و دست دراز کند، آن جامد تبدیل به مایع می‌شود و فرومی‌ریزد.\nإِنَّک عَلَیٰ کلِّ شَیءٍ قَدِیرٌ\nتو همان خدایی هستی که بر هر چیزی قادر و توانایی. همهٔ امور به دست توست و از کسی کاری برنمی‌آید.\nحضرت در نهج‌البلاغه در سه موضع، لفظ «إِنَّک عَلَیٰ کلِّ شَیءٍ قَدِیرٌ» را به کار برده‌اند:\n۱. در خطبهٔ قاصعه، در جریان معجزهٔ پیامبر:\nدرخواست کردند درخت با تمام ریشه از جای خود حرکت کند و دوباره به‌جای خود بازگردد.\nآن‌ها این معجزه را دیدند، ولی ایمان نیاوردند. در نقل این معجزه از پیامبر فرمودند: همه‌کارهٔ عالم خداست. در جریان معجزه فرمود: «إِنَّک عَلَیٰ کلِّ شَیءٍ قَدِیرٌ».\n۲. در انتهای همین خطبه:\nدست به‌سوی کسی دراز نشود و امید ما جز به خدا نباشد.\n«إِنَّک عَلَیٰ کلِّ شَیءٍ قَدِیرٌ».\n۳. در خطبهٔ ۲۲۵:\nدر تنگدستی و نیاز، مبادا اظهار حاجت به غیر، آبروی ما را بریزد.\nاگر خدا بخواهد، می‌رسد و اگر نخواهد، هرگز نمی‌رسد:\n«إِنَّک عَلَیٰ کلِّ شَیءٍ قَدِیرٌ».\nیک مورد آن در معجزه بود و دو مورد دیگر در همین مسائل دنیایی، درخواست‌ها و طلب رزق.\nمعجزه از دست غیر خارج است و عهده‌دار آن فقط خداست. پس همان خدا می‌تواند در امور عادی نیز به‌خوبی دستگیری کند."]});
